/**
 * Tests for {@link ExchangeAttributeParser#parse(String)}.
 *
 * <p>The parsed result is inspected through its observable contract: the concrete attribute
 * implementation that is produced (a single attribute for exactly one token, a
 * {@link CompositeExchangeAttribute} otherwise), the value read back from constant-only
 * results, the textual rendering of the attribute ({@link Object#toString()}) and the
 * exception thrown for malformed input.</p>
 */
@Tag("io.undertow.testutils.category.UnitTest")
class ExchangeAttributeParserParseTests {

    private ExchangeAttributeParser parser;

    @BeforeEach
    void createParser() {
        parser = ExchangeAttributes.parser(getClass().getClassLoader());
    }

    // ------------------------------------------------------------------
    // pure literal input
    // ------------------------------------------------------------------

    @Test
    void parsePlainLiteralReturnsSingleConstantAttribute() {
        ExchangeAttribute attribute = parser.parse("literal");

        assertInstanceOf(ConstantExchangeAttribute.class, attribute);
        assertFalse(attribute instanceof CompositeExchangeAttribute);
        assertEquals("literal", attribute.readAttribute(null));
        assertEquals("literal", attribute.toString());
    }

    @Test
    void parseLiteralContainingBracesButNoTokenReturnsConstantAttribute() {
        ExchangeAttribute attribute = parser.parse("{abc}");

        assertInstanceOf(ConstantExchangeAttribute.class, attribute);
        assertEquals("{abc}", attribute.readAttribute(null));
    }

    @Test
    void parseLiteralContainingUnbalancedClosingBraceReturnsConstantAttribute() {
        ExchangeAttribute attribute = parser.parse("x}y");

        assertInstanceOf(ConstantExchangeAttribute.class, attribute);
        assertEquals("x}y", attribute.readAttribute(null));
    }

    @Test
    void parseEmptyStringReturnsEmptyCompositeAttribute() {
        ExchangeAttribute attribute = parser.parse("");

        assertInstanceOf(CompositeExchangeAttribute.class, attribute);
        assertEquals("", attribute.readAttribute(null));
        assertEquals("", attribute.toString());
    }

    // ------------------------------------------------------------------
    // single token input -> single attribute, never a composite
    // ------------------------------------------------------------------

    @Test
    void parseSingleShortTokenReturnsSingleAttribute() {
        ExchangeAttribute attribute = parser.parse("%a");

        assertInstanceOf(RemoteIPAttribute.class, attribute);
        assertSame(RemoteIPAttribute.INSTANCE, attribute);
        assertEquals("%{REMOTE_IP}", attribute.toString());
    }

    @Test
    void parseSingleLongTokenReturnsSingleAttribute() {
        ExchangeAttribute attribute = parser.parse("%{REMOTE_IP}");

        assertSame(RemoteIPAttribute.INSTANCE, attribute);
        assertEquals("%{REMOTE_IP}", attribute.toString());
    }

    @Test
    void parseSingleMethodTokenReturnsSingleAttribute() {
        ExchangeAttribute attribute = parser.parse("%m");

        assertInstanceOf(RequestMethodAttribute.class, attribute);
        assertSame(RequestMethodAttribute.INSTANCE, attribute);
        assertEquals("%{METHOD}", attribute.toString());
    }

    @Test
    void parseSingleHeaderTokenReturnsRequestHeaderAttribute() {
        ExchangeAttribute attribute = parser.parse("%{i,x-test}");

        assertInstanceOf(RequestHeaderAttribute.class, attribute);
        assertFalse(attribute instanceof CompositeExchangeAttribute);
        assertEquals("%{i,x-test}", attribute.toString());
    }

    @Test
    void parseSinglePredicateContextTokenReturnsPredicateContextAttribute() {
        ExchangeAttribute attribute = parser.parse("${ctx}");

        assertInstanceOf(PredicateContextAttribute.class, attribute);
        assertEquals("${ctx}", attribute.toString());
    }

    @Test
    void parseUnknownPercentTokenFallsBackToConstantAttribute() {
        ExchangeAttribute attribute = parser.parse("%z");

        assertInstanceOf(ConstantExchangeAttribute.class, attribute);
        assertEquals("%z", attribute.readAttribute(null));
    }

    @Test
    void parseEmptyBracesTokenFallsBackToConstantAttribute() {
        ExchangeAttribute attribute = parser.parse("%{}");

        assertInstanceOf(ConstantExchangeAttribute.class, attribute);
        assertEquals("%{}", attribute.readAttribute(null));
    }

    // ------------------------------------------------------------------
    // escaped characters
    // ------------------------------------------------------------------

    @Test
    void parseDoublePercentIsEscapedToLiteralPercent() {
        ExchangeAttribute attribute = parser.parse("%%");

        assertInstanceOf(ConstantExchangeAttribute.class, attribute);
        assertEquals("%", attribute.readAttribute(null));
        assertEquals("%", attribute.toString());
    }

    @Test
    void parseDoubleDollarIsEscapedToLiteralDollar() {
        ExchangeAttribute attribute = parser.parse("$$");

        assertInstanceOf(ConstantExchangeAttribute.class, attribute);
        assertEquals("$", attribute.readAttribute(null));
        assertEquals("$", attribute.toString());
    }

    @Test
    void parseSurroundingLiteralsWithEscapesReassemblesOriginalText() {
        ExchangeAttribute attribute = parser.parse("a%%b$$c");

        assertInstanceOf(CompositeExchangeAttribute.class, attribute);
        assertEquals("a%b$c", attribute.readAttribute(null));
        assertEquals("a%b$c", attribute.toString());
    }

    @Test
    void parsePercentEncodedLiteralDigitsReassemblesOriginalText() {
        ExchangeAttribute attribute = parser.parse("100%%25");

        assertInstanceOf(CompositeExchangeAttribute.class, attribute);
        assertEquals("100%25", attribute.readAttribute(null));
    }

    // ------------------------------------------------------------------
    // composite inputs
    // ------------------------------------------------------------------

    @Test
    void parseLiteralTokenLiteralReturnsCompositeWithThreeAttributes() {
        ExchangeAttribute attribute = parser.parse("x%ay");

        assertInstanceOf(CompositeExchangeAttribute.class, attribute);
        assertEquals("x%{REMOTE_IP}y", attribute.toString());
    }

    @Test
    void parseTypicalLogPatternReturnsComposite() {
        ExchangeAttribute attribute = parser.parse("%a - %m");

        assertInstanceOf(CompositeExchangeAttribute.class, attribute);
        assertEquals("%{REMOTE_IP} - %{METHOD}", attribute.toString());
    }

    @Test
    void parseAdjacentTokensReturnsComposite() {
        ExchangeAttribute attribute = parser.parse("%a%m");

        assertInstanceOf(CompositeExchangeAttribute.class, attribute);
        assertEquals("%{REMOTE_IP}%{METHOD}", attribute.toString());
    }

    @Test
    void parseMixedHeaderAndPredicateContextTokensReturnsComposite() {
        ExchangeAttribute attribute = parser.parse("%{i,x-test}${ctx}");

        assertInstanceOf(CompositeExchangeAttribute.class, attribute);
        assertEquals("%{i,x-test}${ctx}", attribute.toString());
    }

    // ------------------------------------------------------------------
    // nested braces
    // ------------------------------------------------------------------

    @Test
    void parseTokenWithNestedBracesIsTreatedAsOneToken() {
        ExchangeAttribute attribute = parser.parse("${a${b}}");

        assertInstanceOf(PredicateContextAttribute.class, attribute);
        assertFalse(attribute instanceof CompositeExchangeAttribute);
        assertEquals("${a${b}}", attribute.toString());
    }

    @Test
    void parseTextAroundTokenWithNestedBraces() {
        ExchangeAttribute attribute = parser.parse("pre${a${b}}post");

        assertInstanceOf(CompositeExchangeAttribute.class, attribute);
        assertEquals("pre${a${b}}post", attribute.toString());
    }

    // ------------------------------------------------------------------
    // invalid input -> mismatched braces
    // ------------------------------------------------------------------

    @ParameterizedTest
    @ValueSource(strings = {
            "%",
            "$",
            "%{",
            "${",
            "%{i,x",
            "${x",
            "abc%",
            "abc$",
            "abc%{i,x",
            "%{i,${x}",
            "${a${b}",
            "%{i,x}%"
    })
    void parseMismatchedBracesThrows(String valueString) {
        RuntimeException exception = assertThrows(RuntimeException.class, () -> parser.parse(valueString));

        assertTrue(exception.getMessage().contains("Mismatched braces"),
                "Unexpected message: " + exception.getMessage());
        assertTrue(exception.getMessage().contains(valueString),
                "Message should mention the offending value: " + exception.getMessage());
    }

    @Test
    void parseInvalidInputDoesNotPoisonParser() {
        assertThrows(RuntimeException.class, () -> parser.parse("%{"));

        ExchangeAttribute attribute = parser.parse("%a");
        assertSame(RemoteIPAttribute.INSTANCE, attribute);
    }

    // ------------------------------------------------------------------
    // wrappers must be applied to every parsed attribute
    // ------------------------------------------------------------------

    @Test
    void parseAppliesWrappersToEachAttribute() {
        List<ExchangeAttribute> wrapped = new ArrayList<>();
        ExchangeAttributeParser wrappedParser = ExchangeAttributes.parser(getClass().getClassLoader(),
                attribute -> {
                    wrapped.add(attribute);
                    return new ConstantExchangeAttribute("<" + attribute.toString() + ">");
                });

        ExchangeAttribute attribute = wrappedParser.parse("a%a");

        assertInstanceOf(CompositeExchangeAttribute.class, attribute);
        assertEquals("<a><%{REMOTE_IP}>", attribute.readAttribute(null));
        assertEquals(2, wrapped.size());
        assertEquals("a", wrapped.get(0).toString());
        assertInstanceOf(RemoteIPAttribute.class, wrapped.get(1));
    }

    @Test
    void parseWithoutWrappersKeepsOriginalAttributes() {
        ExchangeAttribute attribute = parser.parse("a%a");

        assertInstanceOf(CompositeExchangeAttribute.class, attribute);
        assertEquals("a%{REMOTE_IP}", attribute.toString());
    }
}

