        ByteBuffer buf = ascii(hex + "\r\n");

        assertEquals(expected, reader.readChunk(buf));

        assertFalse(buf.hasRemaining());
        assertEquals(expected, reader.getChunkRemaining());
        assertEquals(List.of(expected), counter.added);
        assertEquals(hex.length() + 2, counter.increments);
    }

    @Test
    void acceptsChunkSizeEqualToTheLimit() throws IOException {
        long limit = Long.MAX_VALUE >> 6;
        String hex = Long.toHexString(limit);
        ByteBuffer buf = ascii(hex + "\n");

        assertEquals(limit, reader.readChunk(buf));

        assertFalse(buf.hasRemaining());
        assertEquals(List.of(limit), counter.added);
        assertEquals(hex.length() + 1, counter.increments);
        assertEquals(limit, reader.getChunkRemaining());
    }

    @Test
    void throwsWhenChunkSizeExceedsTheLimit() {
        ByteBuffer buf = ascii("FFFFFFFFFFFFFFFF\n");

        IOException exception = assertThrows(IOException.class, () -> reader.readChunk(buf));

        assertTrue(exception.getMessage().contains("Chunk size too large"),
                "unexpected message: " + exception.getMessage());
        assertEquals(16, counter.increments, "the offending digit is still counted");
        assertTrue(counter.added.isEmpty(), "chunk size must not be accounted before it is complete");
    }

    @Test
    void readsChunkSizeSplitAcrossSeveralBuffers() throws IOException {
        assertEquals(0, reader.readChunk(ascii("1a")));
        assertEquals(0, reader.getChunkRemaining());
        assertTrue(counter.added.isEmpty());

        assertEquals(0, reader.readChunk(ascii("\r")));
        assertEquals(0, reader.getChunkRemaining());
        assertEquals(List.of(26L), counter.added);

        assertEquals(26, reader.readChunk(ascii("\n")));

        assertEquals(4, counter.increments);
        assertEquals(List.of(26L), counter.added);
        assertEquals(26, reader.getChunkRemaining());
    }

    @Test
    void readsChunkSizeTerminatorSplitFromItsDigits() throws IOException {
        assertEquals(0, reader.readChunk(ascii("5\r")));
        assertEquals(0, reader.getChunkRemaining());
        assertEquals(List.of(5L), counter.added);

        assertEquals(5, reader.readChunk(ascii("\n")));

        assertTrue(counter.added.equals(List.of(5L)));
        assertEquals(3, counter.increments);
        assertEquals(5, reader.getChunkRemaining());
    }

    @Test
    void acceptsBareLineFeedAsChunkSizeTerminator() throws IOException {
        ByteBuffer buf = ascii("5\n");

        assertEquals(5, reader.readChunk(buf));

        assertFalse(buf.hasRemaining());
        assertEquals(2, counter.increments);
        assertEquals(List.of(5L), counter.added);
    }

    @Test
    void skipsChunkExtensionsUntilEndOfLine() throws IOException {
        ByteBuffer buf = ascii("5;foo=bar\r\n");

        assertEquals(5, reader.readChunk(buf));

        assertFalse(buf.hasRemaining());
        assertEquals(List.of(5L), counter.added);
        assertEquals(buf.limit(), counter.increments);
        assertEquals(5, reader.getChunkRemaining());
    }

    @Test
    void skipsChunkExtensionContainingSpacesAndPunctuation() throws IOException {
        assertEquals(5, reader.readChunk(ascii("5;name=\"some value\";flag\r\n")));

        assertEquals(List.of(5L), counter.added);
        assertEquals(5, reader.getChunkRemaining());
    }

    @Test
    void returnsChunkRemainingWithoutConsumingBufferWhileChunkIsInProgress() throws IOException {
        assertEquals(5, reader.readChunk(ascii("5\r\n")));
        int incrementsAfterHeader = counter.increments;

        ByteBuffer data = ascii("hello");

        assertEquals(5, reader.readChunk(data));

        assertEquals(0, data.position(), "the reader must not consume chunk body bytes");
        assertEquals("hello", remaining(data));
        assertEquals(incrementsAfterHeader, counter.increments);
        assertEquals(5, reader.getChunkRemaining());
    }

    @Test
    void consumesNewlineAfterChunkBodyBeforeParsingNextSize() throws IOException {
        assertEquals(5, reader.readChunk(ascii("5\r\n")));
        reader.setChunkRemaining(0);
        assertEquals(0, reader.getChunkRemaining());

        ByteBuffer buf = ascii("\r\n3\r\n");

        assertEquals(3, reader.readChunk(buf));

        assertFalse(buf.hasRemaining());
        assertEquals(List.of(5L, 3L), counter.added);
        assertEquals(8, counter.increments);
        assertEquals(3, reader.getChunkRemaining());
    }

    @Test
    void setChunkRemainingIsIgnoredWhileParsingAChunkSize() {
        reader.setChunkRemaining(7);
        assertEquals(0, reader.getChunkRemaining());

        reader.setChunkRemaining(-1);
        assertEquals(0, reader.getChunkRemaining());
    }

    @Test
    void handlesWholeChunkedBodyEndToEnd() throws IOException {
        ByteBuffer buf = ascii("5\r\nhello\r\n0\r\n\r\n");

        assertEquals(5, reader.readChunk(buf));
        assertEquals(3, buf.position());

        buf.position(buf.position() + 5);
        reader.setChunkRemaining(0);

        assertEquals(-1, reader.readChunk(buf));

        assertFalse(buf.hasRemaining());
        assertEquals(List.of(5L, 0L), counter.added);
        assertEquals(10, counter.increments, "chunk body bytes are not read by readChunk");
        assertEquals(-1, reader.getChunkRemaining());
