    @Test
    void finalChunkWithTerminatorReturnsMinusOne() throws IOException {
        ByteBuffer buf = ascii("0\r\n\r\n");

        assertEquals(-1, reader.readChunk(buf));

        assertFalse(buf.hasRemaining());
        assertEquals(5, counter.increments);
        assertEquals(List.of(0L), counter.added);
        assertEquals(-1, reader.getChunkRemaining());
    }

    @Test
    void finalChunkWithoutTerminatorWaitsForItAndThenFinishes() throws IOException {
        assertEquals(0, reader.readChunk(ascii("0\r\n")));

        assertEquals(List.of(0L), counter.added);
        assertEquals(3, counter.increments);
        assertEquals(0, reader.getChunkRemaining());

        assertEquals(-1, reader.readChunk(ascii("\r\n")));

        assertEquals(5, counter.increments);
        assertEquals(-1, reader.getChunkRemaining());
    }

    @Test
    void finalChunkTerminatedByBareLineFeed() throws IOException {
        assertEquals(0, reader.readChunk(ascii("0\n")));
        assertEquals(List.of(0L), counter.added);
        assertEquals(2, counter.increments);

        assertEquals(-1, reader.readChunk(ascii("\n")));
        assertEquals(-1, reader.getChunkRemaining());
    }

    @Test
    void trailersAreAttachedWhenLastChunkAndTrailersArriveTogether() throws IOException {
        ByteBuffer buf = ascii("0\r\nX-Trailer: value\r\n\r\n");

        assertEquals(-1, reader.readChunk(buf));

        assertFalse(buf.hasRemaining());
        HeaderMap trailers = attachable.getAttachment(HttpAttachments.REQUEST_TRAILERS);
        assertNotNull(trailers);
        assertEquals("value", trailers.getFirst("X-Trailer"));
        assertEquals(-1, reader.getChunkRemaining());
    }

    @Test
    void multipleTrailersAreAttached() throws IOException {
        ByteBuffer buf = ascii("0\r\nX-One: 1\r\nX-Two: 2\r\n\r\n");

        assertEquals(-1, reader.readChunk(buf));

        HeaderMap trailers = attachable.getAttachment(HttpAttachments.REQUEST_TRAILERS);
        assertNotNull(trailers);
        assertEquals("1", trailers.getFirst("X-One"));
        assertEquals("2", trailers.getFirst("X-Two"));
    }

    @Test
    void trailersSplitAcrossBuffersAreAttachedOnlyWhenComplete() throws IOException {
        assertEquals(0, reader.readChunk(ascii("0\r\nX-Trailer: value\r\n")));
        assertNull(attachable.getAttachment(HttpAttachments.REQUEST_TRAILERS));

        assertEquals(-1, reader.readChunk(ascii("\r\n")));

        HeaderMap trailers = attachable.getAttachment(HttpAttachments.REQUEST_TRAILERS);
        assertNotNull(trailers);
        assertEquals("value", trailers.getFirst("X-Trailer"));
        assertEquals(-1, reader.getChunkRemaining());
    }

    @Test
    void incompleteTrailerDoesNotAttachHeaderMap() throws IOException {
        assertEquals(0, reader.readChunk(ascii("0\r\nX-Trailer: value")));

        assertNull(attachable.getAttachment(HttpAttachments.REQUEST_TRAILERS));
        assertEquals(0, reader.getChunkRemaining());
    }

    @Test
    void trailerNameFollowedByCarriageReturnWithoutColonThrows() {
        IOException exception = assertThrows(IOException.class,
                () -> reader.readChunk(ascii("0\r\nX-Trailer\r\n\r\n")));

        assertTrue(exception.getMessage().contains("Could not decode trailers"),
                "unexpected message: " + exception.getMessage());
        assertNull(attachable.getAttachment(HttpAttachments.REQUEST_TRAILERS));
    }

    @Test
    void trailerEndingWithUnexpectedCharacterThrows() {
        IOException exception = assertThrows(IOException.class,
                () -> reader.readChunk(ascii("0\r\nX-Trailer: value\r\n\rZ")));

        assertTrue(exception.getMessage().contains("Could not decode trailers"),
                "unexpected message: " + exception.getMessage());
    }

    @Test
    void entitySizeIncrementFailureIsPropagated() {
        ChunkReader failingReader = new ChunkReader(attachable, HttpAttachments.REQUEST_TRAILERS, new BytesCounter<IOException>() {
            @Override
            public void increment() throws IOException {
                throw new IOException("increment failed");
            }

            @Override
            public void add(long bytes) throws IOException {
                throw new IOException("add failed");
            }
        });

        IOException exception = assertThrows(IOException.class, () -> failingReader.readChunk(ascii("5\r\n")));

        assertEquals("increment failed", exception.getMessage());
    }

    @Test
    void entitySizeAddFailureIsPropagated() {
        ChunkReader failingReader = new ChunkReader(attachable, HttpAttachments.REQUEST_TRAILERS, new BytesCounter<IOException>() {
            @Override
            public void increment() {
                // accepted
            }

            @Override
            public void add(long bytes) throws IOException {
                throw new IOException("add failed");
            }
        });

        IOException exception = assertThrows(IOException.class, () -> failingReader.readChunk(ascii("5\n")));

        assertEquals("add failed", exception.getMessage());
    }

    private static ByteBuffer ascii(final String text) {
        return ByteBuffer.wrap(text.getBytes(StandardCharsets.US_ASCII));
    }

    private static String remaining(final ByteBuffer buf) {
        ByteBuffer copy = buf.duplicate();
        byte[] bytes = new byte[copy.remaining()];
        copy.get(bytes);
        return new String(bytes, StandardCharsets.US_ASCII);
    }

    private static final class RecordingCounter implements BytesCounter<IOException> {

        private int increments;
        private final List<Long> added = new ArrayList<>();

        @Override
        public void increment() {
            increments++;
        }

        @Override
        public void add(final long bytes) {
            added.add(bytes);
        }
    }

    private static final class MapAttachable implements Attachable {

        private final Map<AttachmentKey<?>, Object> attachments = new HashMap<>();

        @Override
        public <T> T getAttachment(final AttachmentKey<T> key) {
            return key.cast(attachments.get(key));
        }

        @SuppressWarnings("unchecked")
        @Override
        public <T> List<T> getAttachmentList(final AttachmentKey<? extends List<T>> key) {
            List<T> list = (List<T>) attachments.get(key);
            return list == null ? Collections.emptyList() : list;
        }

        @Override
        public <T> T putAttachment(final AttachmentKey<T> key, final T value) {
            T old = getAttachment(key);
            if (value == null) {
                attachments.remove(key);
            } else {
                attachments.put(key, value);
            }
            return old;
        }

        @Override
        public <T> T removeAttachment(final AttachmentKey<T> key) {
            return key.cast(attachments.remove(key));
        }

        @Override
        public <T> void addToAttachmentList(final AttachmentKey<AttachmentList<T>> key, final T value) {
