    private static final class RecordingSinkConduit implements StreamSinkConduit {

        final ByteArrayOutputStream wire = new ByteArrayOutputStream();
        long consumeLimit = Long.MAX_VALUE;
        int arrayWriteCalls;
        int singleWriteCalls;
        boolean failOnWrite;
        boolean flushResult = true;
