        @Override
        public long write(ByteBuffer[] srcs, int offset, int length) throws IOException {
            arrayWriteCalls++;
            if (failOnWrite) {
                throw new IOException("simulated write failure");
            }
            long budget = consumeLimit;
            long consumed = 0;
            for (int i = 0; i < length && budget > 0; i++) {
                ByteBuffer buffer = srcs[offset + i];
                int n = (int) Math.min((long) buffer.remaining(), budget);
                for (int j = 0; j < n; j++) {
                    wire.write(buffer.get());
                }
                budget -= n;
                consumed += n;
            }
            return consumed;
        }

