    private static final class RecordingSink implements StreamSinkConduit {

        private final ByteArrayOutputStream written = new ByteArrayOutputStream();
        private int writeLimit = Integer.MAX_VALUE;
        private int remainingLimit = Integer.MAX_VALUE;
        private IOException failure;
        private boolean writeShutdown;
        private int writeCalls;
        private int writeArrayCalls;
        private int writeFinalCalls;
        private int writeFinalArrayCalls;

        private int consume(final ByteBuffer buffer) throws IOException {
            if (failure != null) {
                throw failure;
