 * Tests for {@link ChunkedStreamSourceConduit#read(ByteBuffer)}.
 *
 * <p>The source conduit (the "next" conduit) and the pooled buffer wrapper are faked so that the
 * observable behaviour of the de-chunking read can be verified: how many payload bytes are copied
 * into the destination, what is reported at the end of the chunked stream, which bytes are pushed
 * back, when the pooled buffer is released, when the finish listener fires and which trailers are
 * attached to the exchange.</p>
 */
public class ChunkedStreamSourceConduitReadTests {

    @Test
    public void readsSingleChunkPayloadAndReportsEndOfStream() throws IOException {
        Fixture fixture = new Fixture("5\r\nhello\r\n0\r\n\r\n", 16);
        fixture.feedAll();
        ByteBuffer dst = ByteBuffer.allocate(10);

        int read = fixture.conduit.read(dst);

        assertEquals(5, read);
        assertEquals("hello", contentOf(dst));
        // the chunk delimiter, the last-chunk header and the trailer terminator are pushed back
        assertEquals(1, fixture.wrapper.pushedBackContent.size());
        assertEquals("\r\n0\r\n\r\n", fixture.wrapper.pushedBackContent.get(0));
        assertEquals(1, fixture.wrapper.allocated.size());
        assertFalse(fixture.wrapper.allocated.get(0).closed,
                "a pushed back pooled buffer must not be closed");
        assertEquals(0, fixture.listener.count);
        assertEquals(0, fixture.closeable.closeCount);

        // the terminating chunk is already buffered, so this read reports the end of the stream
        ByteBuffer endDst = ByteBuffer.allocate(10);
        assertEquals(-1, fixture.conduit.read(endDst));
        assertEquals(0, endDst.position(), "no bytes may be written for the end of stream");
        assertEquals(1, fixture.listener.count);
        assertSame(fixture.conduit, fixture.listener.lastConduit);
        assertEquals(2, fixture.wrapper.allocated.size());
        assertTrue(fixture.wrapper.allocated.get(1).closed);

        // once the end of the stream was reported the listener must not fire again
        assertEquals(-1, fixture.conduit.read(ByteBuffer.allocate(10)));
        assertEquals(1, fixture.listener.count, "finish listener must only be invoked once");
        assertEquals(2, fixture.wrapper.allocated.size(),
                "no buffer may be allocated once the stream is finished");
    }

    @Test
    public void emptyChunkedStreamReportsEndOfStreamImmediately() throws IOException {
        Fixture fixture = new Fixture("0\r\n\r\n", 16);
        fixture.feedAll();

        ByteBuffer dst = ByteBuffer.allocate(10);
        assertEquals(-1, fixture.conduit.read(dst));
        assertEquals(0, dst.position());
        assertEquals(1, fixture.listener.count);
        assertEquals(0, fixture.closeable.closeCount);

        assertEquals(-1, fixture.conduit.read(ByteBuffer.allocate(10)));
        assertEquals(1, fixture.listener.count);
    }

    @Test
    public void readsMultipleChunksAcrossChunkBoundaries() throws IOException {
        Fixture fixture = new Fixture("3\r\nabc\r\n3\r\ndef\r\n0\r\n\r\n", 32);
        fixture.feedAll();

        assertEquals("abcdef", readUntilEndOfStream(fixture, 32, 10));
        assertEquals(1, fixture.listener.count);
        assertEquals(0, fixture.closeable.closeCount);
    }

    @Test
    public void splitsPayloadWhenDestinationIsSmallerThanChunk() throws IOException {
        Fixture fixture = new Fixture("5\r\nhello\r\n0\r\n\r\n", 16);
        fixture.feedAll();

        ByteBuffer dst = ByteBuffer.allocate(3);
        assertEquals(3, fixture.conduit.read(dst));
        assertEquals("hel", contentOf(dst));
        // the rest of the chunk (plus the following chunk framing) is pushed back for later reads
        assertFalse(fixture.wrapper.pushedBackContent.isEmpty());
        assertEquals("lo\r\n0\r\n\r\n", fixture.wrapper.pushedBackContent.get(0));

        // only the remaining two payload bytes of the chunk are left
        assertEquals("lo", readUntilEndOfStream(fixture, 3, 10));
        assertEquals(1, fixture.listener.count);
    }

    @Test
    public void doesNotConsumeDataWhenDestinationHasNoRemainingSpace() throws IOException {
        Fixture fixture = new Fixture("5\r\nhello\r\n", 16);
        fixture.feedAll();

        ByteBuffer dst = ByteBuffer.allocate(5);
        dst.position(5); // no space left in the destination

        assertEquals(0, fixture.conduit.read(dst));
        assertEquals(0, dst.remaining(), "nothing may be written into a full destination");
        assertEquals(1, fixture.wrapper.pushedBackContent.size());
        assertEquals("hello\r\n", fixture.wrapper.pushedBackContent.get(0),
                "the whole chunk payload must be kept for the next read");
        assertEquals(0, fixture.listener.count);

        // once space is available the very same payload is returned, nothing was lost
        dst.position(0);
        assertEquals(5, fixture.conduit.read(dst));
        assertEquals("hello", contentOf(dst));
    }

    @Test
    public void readsDirectlyFromSourceWhenPooledBufferIsExhausted() throws IOException {
        Fixture fixture = new Fixture("10\r\n0123456789abcdef\r\n0\r\n\r\n", 8);
        StringBuilder payload = new StringBuilder();

        // header plus four payload bytes; the rest of the chunk is read directly into the destination
        fixture.feed(11);
        ByteBuffer dst = ByteBuffer.allocate(32);
        assertEquals(7, fixture.conduit.read(dst));
        assertEquals("0123456", contentOf(dst));
        assertEquals(32, dst.limit(), "the destination limit must be restored");
        payload.append(contentOf(dst));

        fixture.feed(8);
        dst.clear();
        assertEquals(8, fixture.conduit.read(dst));
        assertEquals("789abcde", contentOf(dst));
        assertEquals(32, dst.limit());
        payload.append(contentOf(dst));

        fixture.feed(1);
        dst.clear();
        assertEquals(1, fixture.conduit.read(dst));
        assertEquals("f", contentOf(dst));
        payload.append(contentOf(dst));

        fixture.feedAll();
        payload.append(readUntilEndOfStream(fixture, 32, 10));
        assertEquals("0123456789abcdef", payload.toString());
        assertEquals(1, fixture.listener.count);
    }

    @Test
    public void returnsZeroWhileSourceHasNoDataAvailable() throws IOException {
        Fixture fixture = new Fixture("5\r\nhello\r\n0\r\n\r\n", 8);
        ByteBuffer dst = ByteBuffer.allocate(16);

        assertEquals(0, fixture.conduit.read(dst));
        assertEquals(0, dst.position());
        assertEquals(1, fixture.wrapper.allocated.size());
        assertTrue(fixture.wrapper.allocated.get(0).closed,
                "the buffer must be released when no data was read");
        assertEquals(0, fixture.listener.count);

        fixture.feed(8);
        assertEquals(5, fixture.conduit.read(dst));
        assertEquals("hello", contentOf(dst));

        fixture.feed(7);
        dst.clear();
        assertEquals(-1, fixture.conduit.read(dst));
        assertEquals(0, dst.position());
        assertEquals(1, fixture.listener.count);
    }

    @Test
    public void attachesTrailersAndReportsEndOfStream() throws IOException {
        MapAttachable attachable = new MapAttachable();
        Fixture fixture = new Fixture("5\r\nhello\r\n0\r\nX-Foo: bar\r\n\r\n", 32, attachable);
        fixture.feedAll();

        ByteBuffer dst = ByteBuffer.allocate(16);
        assertEquals(5, fixture.conduit.read(dst));
        assertEquals("hello", contentOf(dst));
        assertEquals(0, fixture.listener.count);

        dst.clear();
        assertEquals(-1, fixture.conduit.read(dst));
        assertEquals(0, dst.position());
        assertEquals(1, fixture.listener.count);

        HeaderMap trailers = attachable.getAttachment(HttpAttachments.REQUEST_TRAILERS);
        assertNotNull(trailers, "the trailers must be attached to the exchange");
        assertEquals("bar", trailers.getFirst("X-Foo"));
    }

    @Test
    public void throwsClosedChannelExceptionWhenSourceReportsEof() throws IOException {
        Fixture fixture = new Fixture("5\r\nhello\r\n0\r\n\r\n", 16);
        fixture.next.setEof(true);

        assertThrows(ClosedChannelException.class, () -> fixture.conduit.read(ByteBuffer.allocate(16)));
        assertEquals(1, fixture.closeable.closeCount, "the channel must be closed on failure");
        assertEquals(1, fixture.wrapper.allocated.size());
        assertTrue(fixture.wrapper.allocated.get(0).closed);
        assertEquals(0, fixture.listener.count);
    }

    @Test
    public void throwsClosedChannelExceptionWhenSourceReportsEofMidChunk() throws IOException {
        Fixture fixture = new Fixture("5\r\nhel", 8);
        fixture.feed(6);
        fixture.next.setEof(true);

        ByteBuffer dst = ByteBuffer.allocate(32);
        assertThrows(ClosedChannelException.class, () -> fixture.conduit.read(dst));
        assertEquals("hel", contentOf(dst), "bytes read before the failure remain in the destination");
        assertEquals(1, fixture.closeable.closeCount);
    }

    @Test
    public void closesChannelWhenMaxEntitySizeIsExceeded() throws IOException {
        Fixture fixture = new Fixture("10\r\n0123456789abcdef\r\n0\r\n\r\n", 32, 5L);
        fixture.feedAll();

        IOException thrown = assertThrows(IOException.class,
                () -> fixture.conduit.read(ByteBuffer.allocate(32)));
        assertTrue(thrown instanceof RequestTooBigException,
                "expected a RequestTooBigException but got " + thrown);
        assertTrue(thrown.getMessage().contains("5"), thrown.getMessage());
        assertEquals(1, fixture.closeable.closeCount);
        assertEquals(1, fixture.listener.count);
    }

    @Test
    public void throwsClosedChannelExceptionWhenReadAfterChannelWasClosed() throws IOException {
        Fixture fixture = new Fixture("10\r\n0123456789abcdef\r\n0\r\n\r\n", 32, 5L);
        fixture.feedAll();
        assertThrows(IOException.class, () -> fixture.conduit.read(ByteBuffer.allocate(32)));
        int allocationsAfterFailure = fixture.wrapper.allocated.size();

        assertThrows(ClosedChannelException.class,
                () -> fixture.conduit.read(ByteBuffer.allocate(32)));
        assertEquals(allocationsAfterFailure, fixture.wrapper.allocated.size(),
                "a closed conduit must not allocate buffers");
        assertEquals(1, fixture.listener.count, "the finish listener must not fire a second time");
        // the failing read closes the underlying resource, the read on the closed conduit closes it
        // once more
        assertEquals(2, fixture.closeable.closeCount);
    }

    private static String readUntilEndOfStream(Fixture fixture, int destinationSize, int maxReads)
            throws IOException {
        StringBuilder result = new StringBuilder();
        ByteBuffer dst = ByteBuffer.allocate(destinationSize);
        for (int i = 0; i < maxReads; i++) {
            dst.clear();
            int read = fixture.conduit.read(dst);
            if (read == -1) {
                return result.toString();
            }
            assertTrue(read >= 0, "read must never return a negative value other than -1");
            result.append(contentOf(dst));
        }
        fail("end of stream was not reported within " + maxReads + " reads");
        return null;
    }

    private static String contentOf(ByteBuffer buffer) {
        ByteBuffer copy = buffer.duplicate();
        copy.flip();
        byte[] bytes = new byte[copy.remaining()];
        copy.get(bytes);
        return new String(bytes, StandardCharsets.ISO_8859_1);
    }

    private static String remainingOf(ByteBuffer buffer) {
        ByteBuffer copy = buffer.duplicate();
        byte[] bytes = new byte[copy.remaining()];
        copy.get(bytes);
        return new String(bytes, StandardCharsets.ISO_8859_1);
    }

    /**
     * Creates a conduit together with its fakes. The chunked data is only handed to the source
     * conduit once {@link #feed(int)} has been called, which models data arriving from the socket.
     */
    private static final class Fixture {

        private final RecordingBufferWrapper wrapper;
        private final FakeSourceConduit next;
        private final RecordingConduitListener listener = new RecordingConduitListener();
        private final RecordingCloseable closeable = new RecordingCloseable();
        private final ChunkedStreamSourceConduit conduit;

        Fixture(String chunkedData, int bufferSize) {
            this(chunkedData, bufferSize, (Attachable) null);
        }

        Fixture(String chunkedData, int bufferSize, Attachable attachable) {
            this(chunkedData, bufferSize, attachable, -1L);
        }

        Fixture(String chunkedData, int bufferSize, long maxEntitySize) {
            this(chunkedData, bufferSize, null, maxEntitySize);
        }

        Fixture(String chunkedData, int bufferSize, Attachable attachable, long maxEntitySize) {
            byte[] data = chunkedData.getBytes(StandardCharsets.ISO_8859_1);
            this.wrapper = new RecordingBufferWrapper(bufferSize);
            this.next = new FakeSourceConduit(data, wrapper.pushBackQueue);
            HttpServerExchange exchange = maxEntitySize > 0 ? new HttpServerExchange(null, maxEntitySize) : null;
            this.conduit = new ChunkedStreamSourceConduit(next, wrapper, listener, attachable, exchange,
                    closeable, null);
        }

        void feed(int count) {
            next.feed(count);
        }

        void feedAll() {
            next.feed(Integer.MAX_VALUE);
        }
    }

    private static final class RecordingBufferWrapper implements ChunkedStreamSourceConduit.BufferWrapper {

        private final int bufferSize;
        private final Deque<ByteBuffer> pushBackQueue = new ArrayDeque<>();
        private final List<TestPooledBuffer> allocated = new ArrayList<>();
        private final List<String> pushedBackContent = new ArrayList<>();

        RecordingBufferWrapper(int bufferSize) {
            this.bufferSize = bufferSize;
        }

        @Override
        public PooledByteBuffer allocate() {
            TestPooledBuffer pooled = new TestPooledBuffer(bufferSize);
            allocated.add(pooled);
            return pooled;
        }

        @Override
        public void pushBack(PooledByteBuffer pooled) {
            TestPooledBuffer testPooled = (TestPooledBuffer) pooled;
            pushedBackContent.add(remainingOf(testPooled.buffer));
            pushBackQueue.addLast(testPooled.buffer);
        }
    }

    private static final class TestPooledBuffer implements PooledByteBuffer {

        private final ByteBuffer buffer;
        private boolean closed;

        TestPooledBuffer(int bufferSize) {
            this.buffer = ByteBuffer.allocate(bufferSize);
        }

        @Override
        public ByteBuffer getBuffer() {
            return buffer;
        }

        @Override
        public void close() {
            closed = true;
        }

        @Override
        public boolean isOpen() {
            return !closed;
        }
    }

    /**
     * A stream source conduit that behaves like a socket: it first drains buffers that were pushed
     * back and then hands out the bytes that have been "fed" so far.
     */
    private static final class FakeSourceConduit implements StreamSourceConduit {

        private final byte[] data;
        private final Deque<ByteBuffer> pushBackQueue;
        private int position;
        private int available;
        private boolean eof;

        FakeSourceConduit(byte[] data, Deque<ByteBuffer> pushBackQueue) {
            this.data = data;
            this.pushBackQueue = pushBackQueue;
        }

        void feed(int count) {
            available = (int) Math.min(data.length, (long) available + count);
        }

        void setEof(boolean eof) {
            this.eof = eof;
        }

        @Override
        public int read(ByteBuffer dst) throws IOException {
            int total = 0;
            while (!pushBackQueue.isEmpty() && dst.hasRemaining()) {
                ByteBuffer pushed = pushBackQueue.peekFirst();
                int count = Math.min(pushed.remaining(), dst.remaining());
                ByteBuffer copy = pushed.duplicate();
                copy.limit(copy.position() + count);
                dst.put(copy);
                pushed.position(pushed.position() + count);
                total += count;
                if (!pushed.hasRemaining()) {
                    pushBackQueue.pollFirst();
                }
            }
            if (dst.hasRemaining() && position < available) {
                int count = Math.min(dst.remaining(), available - position);
                dst.put(data, position, count);
                position += count;
                total += count;
            }
            if (total == 0 && eof) {
                return -1;
            }
            return total;
        }

        @Override
        public long read(ByteBuffer[] dsts, int offset, int length) throws IOException {
            for (int i = offset; i < offset + length; i++) {
                if (dsts[i].hasRemaining()) {
                    return read(dsts[i]);
                }
            }
            return 0;
        }

        @Override
        public long transferTo(long position, long count, FileChannel target) throws IOException {
            throw new UnsupportedOperationException("not used by these tests");
        }

        @Override
        public long transferTo(long count, ByteBuffer throughBuffer, StreamSinkChannel target)
                throws IOException {
            throw new UnsupportedOperationException("not used by these tests");
        }

        @Override
        public void terminateReads() throws IOException {
            // nothing to do
        }

        @Override
        public boolean isReadShutdown() {
            return false;
        }

        @Override
        public void resumeReads() {
            // nothing to do
        }

        @Override
        public void suspendReads() {
            // nothing to do
        }

        @Override
        public void wakeupReads() {
            // nothing to do
        }

        @Override
        public boolean isReadResumed() {
            return false;
        }

        @Override
        public void awaitReadable() throws IOException {
            // nothing to do
        }

        @Override
        public void awaitReadable(long time, TimeUnit unit) throws IOException {
            // nothing to do
        }

        @Override
        public XnioIoThread getReadThread() {
            return null;
        }

        @Override
        public void setReadReadyHandler(ReadReadyHandler handler) {
            // nothing to do
        }

        @Override
        public XnioWorker getWorker() {
            return null;
        }
    }

    private static final class RecordingConduitListener implements ConduitListener<ChunkedStreamSourceConduit> {

        private int count;
        private ChunkedStreamSourceConduit lastConduit;

        @Override
        public void handleEvent(ChunkedStreamSourceConduit channel) {
            count++;
            lastConduit = channel;
        }
    }

    private static final class RecordingCloseable implements Closeable {

        private int closeCount;

        @Override
        public void close() {
            closeCount++;
        }
    }

    private static final class MapAttachable implements Attachable {

        private final Map<AttachmentKey<?>, Object> attachments = new HashMap<>();

        @Override
        @SuppressWarnings("unchecked")
        public <T> T getAttachment(AttachmentKey<T> key) {
            return (T) attachments.get(key);
        }

        @Override
        public <T> List<T> getAttachmentList(AttachmentKey<? extends List<T>> key) {
            throw new UnsupportedOperationException("not used by these tests");
        }

        @Override
        @SuppressWarnings("unchecked")
        public <T> T putAttachment(AttachmentKey<T> key, T value) {
            return (T) attachments.put(key, value);
        }

        @Override
        @SuppressWarnings("unchecked")
        public <T> T removeAttachment(AttachmentKey<T> key) {
            return (T) attachments.remove(key);
        }

        @Override
        public <T> void addToAttachmentList(AttachmentKey<AttachmentList<T>> key, T value) {
            throw new UnsupportedOperationException("not used by these tests");
        }
    }
