    /**
     * A controllable next conduit that records everything written to it.
     */
    private static final class RecordingSinkConduit implements StreamSinkConduit {

        private final ByteArrayOutputStream data = new ByteArrayOutputStream();
        private final List<String> events = new ArrayList<>();
        private int writeCalls;
        private int allowedWrites = Integer.MAX_VALUE;
        private boolean flushResult = true;
        private int flushCalls;
        private int terminateWritesCalls;
        private int resumeWritesCalls;
        private IOException writeException;
        private RuntimeException runtimeException;
        private Error writeError;
        private RuntimeException resumeWritesException;

        private byte[] writtenBytes() {
            return data.toByteArray();
        }

        private void checkFailures() throws IOException {
            if (writeException != null) {
                throw writeException;
            }
            if (runtimeException != null) {
                throw runtimeException;
            }
            if (writeError != null) {
                throw writeError;
            }
        }

        @Override
        public int write(ByteBuffer src) throws IOException {
            events.add("write");
            writeCalls++;
            checkFailures();
            if (writeCalls > allowedWrites) {
                return 0;
            }
            return copy(src);
        }

        @Override
        public long write(ByteBuffer[] srcs, int offset, int length) throws IOException {
            events.add("write");
            writeCalls++;
            checkFailures();
            if (writeCalls > allowedWrites) {
                return 0;
            }
            long total = 0;
            for (int i = offset; i < offset + length; ++i) {
                total += copy(srcs[i]);
            }
            return total;
        }

        private int copy(ByteBuffer src) {
            int remaining = src.remaining();
            byte[] buffer = new byte[remaining];
            src.get(buffer);
            data.write(buffer, 0, remaining);
            return remaining;
        }

        @Override
        public boolean flush() {
            events.add("flush");
            flushCalls++;
            return flushResult;
        }

        @Override
        public void terminateWrites() {
            events.add("terminateWrites");
            terminateWritesCalls++;
        }

        @Override
        public void truncateWrites() {
        }

        @Override
        public boolean isWriteShutdown() {
            return terminateWritesCalls > 0;
        }

        @Override
        public void resumeWrites() {
            events.add("resumeWrites");
            resumeWritesCalls++;
            if (resumeWritesException != null) {
                throw resumeWritesException;
            }
        }

        @Override
        public void suspendWrites() {
        }

        @Override
        public void wakeupWrites() {
        }

        @Override
        public boolean isWriteResumed() {
            return resumeWritesCalls > 0;
        }

        @Override
        public void awaitWritable() {
        }

        @Override
        public void awaitWritable(long time, TimeUnit timeUnit) {
        }

        @Override
        public XnioIoThread getWriteThread() {
            return null;
        }

        @Override
        public void setWriteReadyHandler(WriteReadyHandler handler) {
        }

        @Override
        public XnioWorker getWorker() {
            return null;
