        source.shutdown = true;
        InflatingStreamSourceConduit conduit = new InflatingStreamSourceConduit(exchange, source);

        assertThrows(ClosedChannelException.class, () -> conduit.read(ByteBuffer.allocate(32)));
        assertEquals(0, source.attemptedReads);
    }

    @Test
    void readReturnsZeroWithoutConsumingFollowingDataWhenSourceWouldBlock() throws Exception {
        byte[] original = "deferred compressed payload".getBytes(StandardCharsets.UTF_8);
        TestSourceConduit source = new TestSourceConduit();
        source.zeroReads = 1;
        source.addChunk(rawDeflate(original));
        InflatingStreamSourceConduit conduit = new InflatingStreamSourceConduit(exchange, source);
        ByteBuffer destination = ByteBuffer.allocate(128);

        assertEquals(0, conduit.read(destination));
        assertEquals(0, destination.position());

        int read = conduit.read(destination);
        assertEquals(original.length, read);
        destination.flip();
        assertArrayEquals(original, bytes(destination));
