    @Test
    void readRejectsCompressedChunkTooShortToIdentifyAHeader() throws Exception {
        TestSourceConduit source = new TestSourceConduit();
        source.addChunk(new byte[] { 0x78 });
        source.addChunk(rawDeflate("remaining".getBytes(StandardCharsets.UTF_8)));
        InflatingStreamSourceConduit conduit = new InflatingStreamSourceConduit(exchange, source);

        assertThrows(IOException.class, () -> conduit.read(ByteBuffer.allocate(32)));
    }

    private static byte[] readFully(InflatingStreamSourceConduit conduit, ByteBuffer destination,
            int expectedLength, int maxReads) throws IOException {
        ByteArrayOutputStream output = new ByteArrayOutputStream(expectedLength);
        int zeroReads = 0;
        for (int i = 0; i < maxReads && output.size() < expectedLength; i++) {
            destination.clear();
            int read = conduit.read(destination);
            if (read < 0) {
                throw new AssertionError("Unexpected end of stream after " + output.size() + " bytes");
            }
            if (read == 0) {
                zeroReads++;
                if (zeroReads > 10) {
                    throw new AssertionError("Conduit repeatedly returned zero before producing all data");
                }
                continue;
            }
            zeroReads = 0;
            destination.flip();
            output.write(bytes(destination));
        }
        byte[] result = output.toByteArray();
        assertEquals(expectedLength, result.length);
        return result;
    }

    private static byte[] rawDeflate(byte[] data) {
        return deflate(data, true);
    }

    private static byte[] zlibDeflate(byte[] data) {
        return deflate(data, false);
    }

    private static byte[] deflate(byte[] data, boolean nowrap) {
        Deflater deflater = new Deflater(Deflater.BEST_COMPRESSION, nowrap);
        try {
            deflater.setInput(data);
            deflater.finish();
            ByteArrayOutputStream output = new ByteArrayOutputStream();
            byte[] buffer = new byte[128];
            while (!deflater.finished()) {
                int count = deflater.deflate(buffer);
                output.write(buffer, 0, count);
            }
            return output.toByteArray();
        } finally {
            deflater.end();
        }
    }

    private static byte[] bytes(ByteBuffer buffer) {
        byte[] result = new byte[buffer.remaining()];
        buffer.get(result);
        return result;
    }

    private static final class TestSourceConduit implements StreamSourceConduit {

        private final Deque<byte[]> chunks = new ArrayDeque<>();
        private int zeroReads;
        private int zeroReadsAfterChunks;
        private boolean eof = true;
        private boolean shutdown;
        private int attemptedReads;

        void addChunk(byte[] chunk) {
            chunks.add(chunk);
        }

        @Override
        public int read(ByteBuffer destination) throws IOException {
            attemptedReads++;
            if (shutdown) {
                throw new ClosedChannelException();
            }
            if (zeroReads > 0) {
                zeroReads--;
                return 0;
            }
            byte[] chunk = chunks.poll();
            if (chunk == null) {
                if (zeroReadsAfterChunks > 0) {
                    zeroReadsAfterChunks--;
                    return 0;
                }
                return eof ? -1 : 0;
            }
            int count = Math.min(destination.remaining(), chunk.length);
            destination.put(chunk, 0, count);
            if (count < chunk.length) {
                chunks.addFirst(Arrays.copyOfRange(chunk, count, chunk.length));
            }
            return count;
        }

        @Override
        public long read(ByteBuffer[] destinations, int offset, int length) throws IOException {
            for (int i = offset; i < offset + length; i++) {
                if (destinations[i].hasRemaining()) {
                    return read(destinations[i]);
                }
            }
            return 0;
        }

        @Override
        public long transferTo(long position, long count, FileChannel target) {
            return 0;
        }

        @Override
        public long transferTo(long count, ByteBuffer throughBuffer, StreamSinkChannel target) {
            return 0;
        }

        @Override
        public void terminateReads() {
            shutdown = true;
        }

        @Override
        public boolean isReadShutdown() {
            return shutdown;
        }

        @Override
        public void resumeReads() {
        }

        @Override
        public void suspendReads() {
