public class PreChunkedStreamSinkConduitDoWriteTests {

    private static final int FLAG_WRITES_SHUTDOWN = 1;
    private static final String EXTRA_DATA_MESSAGE = "Attempted to write additional data after the last chunk";

    private static ByteBuffer buffer(final String data) {
        return ByteBuffer.wrap(data.getBytes(StandardCharsets.US_ASCII));
    }

    private static String drainToString(final ByteBuffer buffer) {
        ByteBuffer duplicate = buffer.duplicate();
        byte[] bytes = new byte[duplicate.remaining()];
        duplicate.get(bytes);
        return new String(bytes, StandardCharsets.US_ASCII);
    }

    private static PreChunkedStreamSinkConduit createConduit(final RecordingSinkConduit next,
                                                             final SimpleAttachable attachable) {
        return new PreChunkedStreamSinkConduit(next, null, attachable);
    }

    @Test
    public void doWriteThrowsClosedChannelExceptionWhenWritesAreShutdown() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());
        conduit.state = FLAG_WRITES_SHUTDOWN;

        ByteBuffer src = buffer("5\r\nhello\r\n");

        assertThrows(ClosedChannelException.class, () -> conduit.doWrite(src));

        assertEquals(0, next.writeCalls, "underlying conduit must not be invoked after shutdown");
        assertEquals(0, src.position(), "source buffer must be left untouched");
        assertEquals(10, src.limit());
        assertEquals(0L, conduit.chunkReader.getChunkRemaining());
    }

    @Test
    public void doWriteThrowsClosedChannelExceptionEvenWhenChunkStreamIsFinished() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());
        conduit.state = FLAG_WRITES_SHUTDOWN;
        // drive the chunk reader into the "finished" state as well
        assertEquals(-1L, conduit.chunkReader.readChunk(buffer("0\r\n\r\n")));
        assertEquals(-1L, conduit.chunkReader.getChunkRemaining());

        assertThrows(ClosedChannelException.class, () -> conduit.doWrite(buffer("x")));
        assertEquals(0, next.writeCalls);
    }

    @Test
    public void doWriteThrowsExtraDataExceptionWhenChunkStreamAlreadyFinished() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());
        assertEquals(-1L, conduit.chunkReader.readChunk(buffer("0\r\n\r\n")));
        assertEquals(-1L, conduit.chunkReader.getChunkRemaining());

        // the "finished" check happens before the empty buffer check, so even an empty write fails
        ByteBuffer src = ByteBuffer.allocate(0);
        IOException exception = assertThrows(IOException.class, () -> conduit.doWrite(src));
        assertTrue(exception.getMessage().contains(EXTRA_DATA_MESSAGE),
                "unexpected message: " + exception.getMessage());
        assertEquals(0, next.writeCalls);
    }

