    public void doWriteReturnsZeroForEmptySourceWithoutCallingUnderlyingConduit() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());

        ByteBuffer src = ByteBuffer.allocate(8);
        src.position(3);
        src.limit(3);

        assertEquals(0, conduit.doWrite(src));
        assertEquals(0, next.writeCalls, "no write should be attempted for an empty buffer");
        assertEquals(3, src.position());
        assertEquals(3, src.limit());
        assertEquals("", next.writtenText());
