    @Test
    public void doWriteWritesSingleChunkAndReturnsNumberOfBytesWritten() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        PreChunkedStreamSinkConduit conduit = createConduit(next, new SimpleAttachable());

        String payload = "5\r\nhello\r\n";
        ByteBuffer src = buffer(payload);

        int ret = conduit.doWrite(src);

        assertEquals(payload.length(), ret);
        assertEquals(1, next.writeCalls);
        assertEquals(payload, next.writtenText(), "the whole buffer must be passed through to the underlying conduit");
        assertEquals(payload.length(), src.position(), "buffer must be fully consumed on success");
        assertEquals(payload.length(), src.limit(), "buffer limit must be restored on success");
        assertEquals(0L, conduit.chunkReader.getChunkRemaining(), "chunk data was fully consumed");
    }

    @Test
    public void doWriteParsesMultipleChunksIncludingTerminatingChunk() throws Exception {
        RecordingSinkConduit next = new RecordingSinkConduit();
        SimpleAttachable attachable = new SimpleAttachable();
        PreChunkedStreamSinkConduit conduit = createConduit(next, attachable);

        String payload = "1\r\na\r\n2\r\nbc\r\n0\r\n\r\n";
        ByteBuffer src = buffer(payload);

        int ret = conduit.doWrite(src);

        assertEquals(payload.length(), ret);
        assertEquals(payload, next.writtenText());
        assertEquals(payload.length(), src.position());
        assertEquals(payload.length(), src.limit());
        assertEquals(-1L, conduit.chunkReader.getChunkRemaining(), "the terminating chunk must be recognized");
        assertNull(attachable.getAttachment(HttpAttachments.RESPONSE_TRAILERS),
