            throw new UnsupportedOperationException();
        }
    }

    /**
     * Recording {@link StreamSinkConduit} that consumes (at most {@link #maxBytesPerWrite}) bytes from the
     * source buffer and remembers everything it was given.
     */
    private static final class RecordingSinkConduit implements StreamSinkConduit {

        private final ByteArrayOutputStream written = new ByteArrayOutputStream();
        int writeCalls;
        int maxBytesPerWrite = Integer.MAX_VALUE;
        boolean writeReturnsZero;
        IOException failure;
        private boolean writeShutdown;

        String writtenText() {
            return new String(written.toByteArray(), StandardCharsets.US_ASCII);
        }

        @Override
        public int write(final ByteBuffer src) throws IOException {
            writeCalls++;
            if (failure != null) {
                throw failure;
            }
            if (writeReturnsZero) {
                return 0;
            }
            int count = Math.min(src.remaining(), maxBytesPerWrite);
            if (count <= 0) {
                return 0;
            }
            byte[] bytes = new byte[count];
            src.get(bytes);
            written.write(bytes, 0, count);
            return count;
        }

