    /**
     * Creates a channel whose single-buffer write consumes at most {@code chunkSize} bytes.
     */
    private static StreamSinkChannel channelConsumingAtMost(final int chunkSize, final AtomicInteger writeCalls)
            throws IOException {
        final StreamSinkChannel channel = mock(StreamSinkChannel.class);
        when(channel.write(any(ByteBuffer.class))).thenAnswer(invocation -> {
            writeCalls.incrementAndGet();
            final ByteBuffer buffer = invocation.getArgument(0);
            final int written = Math.min(chunkSize, buffer.remaining());
            buffer.position(buffer.position() + written);
            return written;
        });
        return channel;
    }

    private static void stubWriteSetter(final StreamSinkChannel channel,
            final ChannelListener.Setter<? extends StreamSinkChannel> writeSetter) {
        doReturn(writeSetter).when(channel).getWriteSetter();
