    private static void stubArrayWriteConsumesAll(final StreamSinkChannel channel,
            final AtomicInteger writeCalls) throws IOException {
        when(channel.write(any(ByteBuffer[].class))).thenAnswer(invocation -> {
            writeCalls.incrementAndGet();
            final ByteBuffer[] buffers = invocation.getArgument(0);
            long total = 0;
            for (ByteBuffer buffer : buffers) {
                total += buffer.remaining();
                buffer.position(buffer.limit());
            }
            return total;
        });
    }

    private static void stubGatheringWriteConsumesAll(final StreamSinkChannel channel,
            final AtomicInteger writeCalls) throws IOException {
        when(channel.write(any(ByteBuffer[].class), anyInt(), anyInt())).thenAnswer(invocation -> {
            writeCalls.incrementAndGet();
            final ByteBuffer[] buffers = invocation.getArgument(0);
            final int offset = invocation.getArgument(1);
            final int length = invocation.getArgument(2);
            long total = 0;
            for (int i = offset; i < offset + length; i++) {
                final ByteBuffer buffer = buffers[i];
                total += buffer.remaining();
                buffer.position(buffer.limit());
            }
            return total;
        });
    }

