    private static final class TestSinkChannel implements StreamSinkChannel {

        private final ByteArrayOutputStream written = new ByteArrayOutputStream();
        private long maxBytesPerWrite = Long.MAX_VALUE;
        private long zeroWritesAfterTotalBytes = Long.MAX_VALUE;
        private long totalWritten;
        private int writeInvocations;
        private int failOnWriteInvocation = 1;
        private IOException failure;
        private boolean writeResumed;
        private int resumeWritesInvocations;
        private ChannelListener<? super StreamSinkChannel> writeListener;

        private final ChannelListener.Setter<StreamSinkChannel> writeSetter = new ChannelListener.Setter<StreamSinkChannel>() {
