    private static final class CountingInputStream extends InputStream {
        private final byte[] data;
        private int position;
        int readCalls;

        CountingInputStream(String value) {
            this.data = value.getBytes(StandardCharsets.ISO_8859_1);
        }

        @Override
        public int read() {
            readCalls++;
            if (position == data.length) {
                return -1;
            }
            return data[position++] & 0xFF;
        }

        @Override
        public int read(byte[] b, int off, int len) {
            readCalls++;
            if (position == data.length) {
                return -1;
            }
            int count = Math.min(len, data.length - position);
            System.arraycopy(data, position, b, off, count);
            position += count;
            return count;
        }
    }

    /**
     * A byte buffer pool that can be configured to fail allocations and that tracks allocation/close counts.
