    private static final class TrackingByteBufferPool implements ByteBufferPool {

        private final DefaultByteBufferPool delegate;
        int allocations;
        int closes;
        boolean returnNullBuffer;

        TrackingByteBufferPool(int bufferSize) {
            this.delegate = new DefaultByteBufferPool(false, bufferSize);
        }

        @Override
        public PooledByteBuffer allocate() {
            allocations++;
            if (returnNullBuffer) {
                return null;
            }
            final PooledByteBuffer pooled = delegate.allocate();
            return new PooledByteBuffer() {
                @Override
                public ByteBuffer getBuffer() {
                    return pooled.getBuffer();
                }

                @Override
                public void close() {
                    closes++;
                    pooled.close();
                }

                @Override
                public boolean isOpen() {
                    return pooled.isOpen();
                }
            };
        }

        @Override
        public ByteBufferPool getArrayBackedPool() {
            return this;
        }

        @Override
        public void close() {
            delegate.close();
        }

        @Override
        public int getBufferSize() {
            return delegate.getBufferSize();
        }

        @Override
        public boolean isDirect() {
            return false;
        }
    }

