    private static final class RecordingStringCallback implements Receiver.PartialStringCallback {

        private final List<String> messages = new ArrayList<>();
        private final List<Boolean> lastFlags = new ArrayList<>();
        private final List<HttpServerExchange> exchanges = new ArrayList<>();

        @Override
        public void handle(final HttpServerExchange exchange, final String message, final boolean last) {
            exchanges.add(exchange);
            messages.add(message);
            lastFlags.add(last);
        }

        int size() {
            return messages.size();
        }

        String joined() {
            final StringBuilder builder = new StringBuilder();
            for (final String message : messages) {
                builder.append(message);
            }
            return builder.toString();
        }

        String lastMessage() {
            assertFalse(messages.isEmpty(), "callback was never invoked");
            return messages.get(messages.size() - 1);
        }

        int finalCallCount() {
            int count = 0;
            for (final Boolean flag : lastFlags) {
                if (flag) {
                    count++;
                }
            }
            return count;
        }

        int lastFlagIndex() {
            return lastFlags.indexOf(Boolean.TRUE);
        }
    }

    private static final class RecordingErrorCallback implements Receiver.ErrorCallback {

        private final List<IOException> errors = new ArrayList<>();
        private final List<HttpServerExchange> exchanges = new ArrayList<>();

        @Override
        public void error(final HttpServerExchange exchange, final IOException e) {
            exchanges.add(exchange);
            errors.add(e);
        }
    }

    private static final class ThrowingInputStream extends InputStream {

        @Override
        public int read() {
            throw new AssertionError("the request body must not be read");
        }

        @Override
        public int read(final byte[] b, final int off, final int len) {
            throw new AssertionError("the request body must not be read");
        }
    }

    private static final class FailingInputStream extends InputStream {

        private final IOException failure;

        FailingInputStream(final IOException failure) {
            this.failure = failure;
        }

        @Override
        public int read() throws IOException {
            throw failure;
        }

        @Override
        public int read(final byte[] b, final int off, final int len) throws IOException {
            throw failure;
        }
    }
}

