import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;

/**
 * Tests for {@link BlockingReceiverImpl#receiveFullBytes(Receiver.FullBytesCallback, Receiver.ErrorCallback)}.
 */
public class BlockingReceiverImplReceiveFullBytesTests {

    private static final byte[] BODY = "hello undertow body".getBytes(StandardCharsets.UTF_8);

    private ServerConnection connection;
    private ByteBufferPool bufferPool;
    private HttpServerExchange exchange;
    private HeaderMap requestHeaders;

    @BeforeEach
    public void setUp() {
        requestHeaders = new HeaderMap();

        connection = mock(ServerConnection.class);
        bufferPool = mock(ByteBufferPool.class);
        when(connection.getByteBufferPool()).thenReturn(bufferPool);
        when(bufferPool.getArrayBackedPool()).thenReturn(bufferPool);

        exchange = mock(HttpServerExchange.class);
        when(exchange.getRequestHeaders()).thenReturn(requestHeaders);
        when(exchange.getConnection()).thenReturn(connection);
        when(exchange.isRequestComplete()).thenReturn(false);
        when(exchange.isResponseStarted()).thenReturn(false);
        when(exchange.endExchange()).thenReturn(exchange);
    }

    private PooledByteBuffer allocatingBuffersOfSize(final int size) {
        PooledByteBuffer pooled = mock(PooledByteBuffer.class);
        when(pooled.getBuffer()).thenReturn(ByteBuffer.allocate(size));
        when(bufferPool.allocate()).thenReturn(pooled);
        return pooled;
    }

    private BlockingReceiverImpl receiver(final InputStream inputStream) {
        return new BlockingReceiverImpl(exchange, inputStream);
    }

    @Test
    public void requestCompleteDeliversEmptyArrayWithoutReadingAnything() {
        when(exchange.isRequestComplete()).thenReturn(true);
        FullBytesCallback callback = mock(FullBytesCallback.class);
        ErrorCallback errorCallback = mock(ErrorCallback.class);

        receiver(new InputStream() {
            @Override
            public int read() throws IOException {
                throw new AssertionError("The request body must not be read when the request is complete");
            }
        }).receiveFullBytes(callback, errorCallback);

        ArgumentCaptor<byte[]> bodyCaptor = ArgumentCaptor.forClass(byte[].class);
        verify(callback).handle(same(exchange), bodyCaptor.capture());
        assertEquals(0, bodyCaptor.getValue().length);
        verifyNoInteractions(errorCallback);
        verify(bufferPool, never()).allocate();
    }

    @Test
    public void bodyIsDeliveredToCallbackAndBufferIsReleased() {
        requestHeaders.put(Headers.CONTENT_LENGTH, BODY.length);
        PooledByteBuffer pooled = allocatingBuffersOfSize(BODY.length);
        FullBytesCallback callback = mock(FullBytesCallback.class);
        ErrorCallback errorCallback = mock(ErrorCallback.class);

        receiver(new ByteArrayInputStream(BODY)).receiveFullBytes(callback, errorCallback);

        ArgumentCaptor<byte[]> bodyCaptor = ArgumentCaptor.forClass(byte[].class);
        verify(callback).handle(same(exchange), bodyCaptor.capture());
        assertArrayEquals(BODY, bodyCaptor.getValue());
        verify(pooled, times(1)).close();
        verify(bufferPool, times(1)).getArrayBackedPool();
        verifyNoInteractions(errorCallback);
    }

    @Test
    public void bodyLargerThanBufferIsDeliveredCompletelyInMultipleReads() {
        requestHeaders.put(Headers.CONTENT_LENGTH, BODY.length);
        allocatingBuffersOfSize(4);
        FullBytesCallback callback = mock(FullBytesCallback.class);

        receiver(new ByteArrayInputStream(BODY)).receiveFullBytes(callback, mock(ErrorCallback.class));

        ArgumentCaptor<byte[]> bodyCaptor = ArgumentCaptor.forClass(byte[].class);
        verify(callback).handle(same(exchange), bodyCaptor.capture());
        assertArrayEquals(BODY, bodyCaptor.getValue());
    }

    @Test
    public void bodyWithoutContentLengthHeadersIsReadUntilEndOfStream() {
        FullBytesCallback callback = mock(FullBytesCallback.class);
        allocatingBuffersOfSize(8);

        receiver(new ByteArrayInputStream(BODY)).receiveFullBytes(callback, mock(ErrorCallback.class));

        ArgumentCaptor<byte[]> bodyCaptor = ArgumentCaptor.forClass(byte[].class);
        verify(callback).handle(same(exchange), bodyCaptor.capture());
        assertArrayEquals(BODY, bodyCaptor.getValue());
        assertFalse(requestHeaders.contains(Headers.CONTENT_LENGTH),
                "CONTENT_LENGTH must only be synthesized when X-Content-Length was the only length header");
    }

    @Test
    public void emptyStreamWithoutContentLengthDeliversEmptyArray() {
        FullBytesCallback callback = mock(FullBytesCallback.class);
        allocatingBuffersOfSize(8);

        receiver(new ByteArrayInputStream(new byte[0])).receiveFullBytes(callback, mock(ErrorCallback.class));

        ArgumentCaptor<byte[]> bodyCaptor = ArgumentCaptor.forClass(byte[].class);
        verify(callback).handle(same(exchange), bodyCaptor.capture());
        assertEquals(0, bodyCaptor.getValue().length);
    }

    @Test
    public void contentLengthIsOnlyAHintAndAllBytesAreRead() {
        requestHeaders.put(Headers.CONTENT_LENGTH, 3); // smaller than the real body
        allocatingBuffersOfSize(8);
        FullBytesCallback callback = mock(FullBytesCallback.class);

        receiver(new ByteArrayInputStream(BODY)).receiveFullBytes(callback, mock(ErrorCallback.class));

        ArgumentCaptor<byte[]> bodyCaptor = ArgumentCaptor.forClass(byte[].class);
        verify(callback).handle(same(exchange), bodyCaptor.capture());
        assertArrayEquals(BODY, bodyCaptor.getValue());
    }

    @Test
    public void xContentLengthIsPromotedToContentLengthWithActualSize() {
        requestHeaders.put(Headers.X_CONTENT_LENGTH, "999");
        allocatingBuffersOfSize(BODY.length);
        FullBytesCallback callback = mock(FullBytesCallback.class);

        receiver(new ByteArrayInputStream(BODY)).receiveFullBytes(callback, mock(ErrorCallback.class));

        ArgumentCaptor<byte[]> bodyCaptor = ArgumentCaptor.forClass(byte[].class);
        verify(callback).handle(same(exchange), bodyCaptor.capture());
        assertArrayEquals(BODY, bodyCaptor.getValue());
        assertEquals(String.valueOf(BODY.length), requestHeaders.getFirst(Headers.CONTENT_LENGTH));
    }

    @Test
    public void contentLengthIsNotPromotedWhenBothLengthHeadersArePresent() {
        requestHeaders.put(Headers.X_CONTENT_LENGTH, "999");
        requestHeaders.put(Headers.CONTENT_LENGTH, "5");
        allocatingBuffersOfSize(BODY.length);
        FullBytesCallback callback = mock(FullBytesCallback.class);

        receiver(new ByteArrayInputStream(BODY)).receiveFullBytes(callback, mock(ErrorCallback.class));

        ArgumentCaptor<byte[]> bodyCaptor = ArgumentCaptor.forClass(byte[].class);
        verify(callback).handle(same(exchange), bodyCaptor.capture());
        assertArrayEquals(BODY, bodyCaptor.getValue());
        assertEquals("5", requestHeaders.getFirst(Headers.CONTENT_LENGTH));
    }

    @Test
    public void nullCallbackIsRejected() {
        ErrorCallback errorCallback = mock(ErrorCallback.class);

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> receiver(new ByteArrayInputStream(BODY)).receiveFullBytes(null, errorCallback));

        assertTrue(exception.getMessage().contains("callback"), "Unexpected message: " + exception.getMessage());
        verifyNoInteractions(errorCallback);
        verify(bufferPool, never()).allocate();
    }

    @Test
    public void nullCallbackIsRejectedBySingleArgumentOverload() {
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> receiver(new ByteArrayInputStream(BODY)).receiveFullBytes(null));

        assertTrue(exception.getMessage().contains("callback"), "Unexpected message: " + exception.getMessage());
    }

    @Test
    public void contentLengthAboveIntegerMaxValueInvokesErrorCallback() {
        requestHeaders.put(Headers.CONTENT_LENGTH, (long) Integer.MAX_VALUE + 1L);
        FullBytesCallback callback = mock(FullBytesCallback.class);
        ErrorCallback errorCallback = mock(ErrorCallback.class);

        receiver(new ByteArrayInputStream(BODY)).receiveFullBytes(callback, errorCallback);

        ArgumentCaptor<IOException> errorCaptor = ArgumentCaptor.forClass(IOException.class);
        verify(errorCallback).error(same(exchange), errorCaptor.capture());
        assertInstanceOf(RequestToLargeException.class, errorCaptor.getValue());
        verifyNoInteractions(callback);
        verify(bufferPool, never()).allocate();
    }

    @Test
    public void contentLengthEqualToMaxBufferSizeIsAccepted() {
        requestHeaders.put(Headers.CONTENT_LENGTH, BODY.length);
        allocatingBuffersOfSize(BODY.length);
        FullBytesCallback callback = mock(FullBytesCallback.class);
        ErrorCallback errorCallback = mock(ErrorCallback.class);
        BlockingReceiverImpl receiver = receiver(new ByteArrayInputStream(BODY));
        receiver.setMaxBufferSize(BODY.length);

        receiver.receiveFullBytes(callback, errorCallback);

        ArgumentCaptor<byte[]> bodyCaptor = ArgumentCaptor.forClass(byte[].class);
        verify(callback).handle(same(exchange), bodyCaptor.capture());
        assertArrayEquals(BODY, bodyCaptor.getValue());
        verifyNoInteractions(errorCallback);
    }

    @Test
    public void contentLengthAboveMaxBufferSizeInvokesErrorCallback() {
        requestHeaders.put(Headers.CONTENT_LENGTH, BODY.length);
        FullBytesCallback callback = mock(FullBytesCallback.class);
        ErrorCallback errorCallback = mock(ErrorCallback.class);
        BlockingReceiverImpl receiver = receiver(new ByteArrayInputStream(BODY));
        receiver.setMaxBufferSize(BODY.length - 1);

        receiver.receiveFullBytes(callback, errorCallback);

        ArgumentCaptor<IOException> errorCaptor = ArgumentCaptor.forClass(IOException.class);
        verify(errorCallback).error(same(exchange), errorCaptor.capture());
        assertInstanceOf(RequestToLargeException.class, errorCaptor.getValue());
        verifyNoInteractions(callback);
        verify(bufferPool, never()).allocate();
    }

    @Test
    public void maxBufferSizeIsIgnoredWhenContentLengthIsUnknown() {
        allocatingBuffersOfSize(BODY.length);
        FullBytesCallback callback = mock(FullBytesCallback.class);
        ErrorCallback errorCallback = mock(ErrorCallback.class);
        BlockingReceiverImpl receiver = receiver(new ByteArrayInputStream(BODY));
        receiver.setMaxBufferSize(1);

        receiver.receiveFullBytes(callback, errorCallback);

        ArgumentCaptor<byte[]> bodyCaptor = ArgumentCaptor.forClass(byte[].class);
        verify(callback).handle(same(exchange), bodyCaptor.capture());
        assertArrayEquals(BODY, bodyCaptor.getValue());
        verifyNoInteractions(errorCallback);
    }

    @Test
    public void ioExceptionWhileReadingInvokesErrorCallback() {
        requestHeaders.put(Headers.CONTENT_LENGTH, BODY.length);
        PooledByteBuffer pooled = allocatingBuffersOfSize(8);
        IOException failure = new IOException("broken stream");
        FullBytesCallback callback = mock(FullBytesCallback.class);
        ErrorCallback errorCallback = mock(ErrorCallback.class);

        InputStream failingStream = new InputStream() {
            @Override
            public int read() throws IOException {
                throw failure;
            }

            @Override
            public int read(byte[] b, int off, int len) throws IOException {
                throw failure;
            }
        };

        receiver(failingStream).receiveFullBytes(callback, errorCallback);

        ArgumentCaptor<IOException> errorCaptor = ArgumentCaptor.forClass(IOException.class);
        verify(errorCallback).error(same(exchange), errorCaptor.capture());
        assertSame(failure, errorCaptor.getValue());
        verifyNoInteractions(callback);
        verify(pooled, times(1)).close();
    }

    @Test
    public void contentLengthAboveIntegerMaxValueWithoutExplicitErrorCallbackEndsExchange() {
        requestHeaders.put(Headers.CONTENT_LENGTH, (long) Integer.MAX_VALUE + 1L);
        FullBytesCallback callback = mock(FullBytesCallback.class);

        receiver(new ByteArrayInputStream(BODY)).receiveFullBytes(callback);

        verify(exchange).setStatusCode(StatusCodes.INTERNAL_SERVER_ERROR);
        verify(exchange).setPersistent(false);
        verify(exchange).endExchange();
        verifyNoInteractions(callback);
    }

    @Test
    public void unallocatableBufferIsReportedThroughErrorCallback() {
        requestHeaders.put(Headers.CONTENT_LENGTH, BODY.length);
        when(bufferPool.allocate()).thenReturn(null);
        FullBytesCallback callback = mock(FullBytesCallback.class);
        ErrorCallback errorCallback = mock(ErrorCallback.class);

        receiver(new ByteArrayInputStream(BODY)).receiveFullBytes(callback, errorCallback);

        ArgumentCaptor<IOException> errorCaptor = ArgumentCaptor.forClass(IOException.class);
        verify(errorCallback).error(same(exchange), errorCaptor.capture());
        assertTrue(errorCaptor.getValue().getMessage().contains("allocate"),
                "Unexpected message: " + errorCaptor.getValue().getMessage());
        verifyNoInteractions(callback);
    }

    @Test
    public void unallocatableBufferWithoutExplicitErrorCallbackEndsExchange() {
        requestHeaders.put(Headers.CONTENT_LENGTH, BODY.length);
        when(bufferPool.allocate()).thenReturn(null);
        FullBytesCallback callback = mock(FullBytesCallback.class);

        receiver(new ByteArrayInputStream(BODY)).receiveFullBytes(callback);

        verify(exchange).setStatusCode(StatusCodes.INTERNAL_SERVER_ERROR);
        verify(exchange).setPersistent(false);
        verify(exchange).endExchange();
        verifyNoInteractions(callback);
    }

    @Test
    public void invalidContentLengthPropagatesNumberFormatException() {
        requestHeaders.put(Headers.CONTENT_LENGTH, "not-a-number");
        FullBytesCallback callback = mock(FullBytesCallback.class);
        ErrorCallback errorCallback = mock(ErrorCallback.class);

        assertThrows(NumberFormatException.class,
                () -> receiver(new ByteArrayInputStream(BODY)).receiveFullBytes(callback, errorCallback));

        verifyNoInteractions(callback);
        verifyNoInteractions(errorCallback);
    }

    @Test
    public void receiveAfterBodyWasAlreadyReadThrows() throws Exception {
        FullBytesCallback callback = mock(FullBytesCallback.class);
        BlockingReceiverImpl receiver = receiver(new ByteArrayInputStream(BODY));
        Field done = BlockingReceiverImpl.class.getDeclaredField("done");
        done.setAccessible(true);
        done.setBoolean(receiver, true);

        IllegalStateException exception = assertThrows(IllegalStateException.class,
                () -> receiver.receiveFullBytes(callback, mock(ErrorCallback.class)));

        assertTrue(exception.getMessage().toLowerCase().contains("already"),
                "Unexpected message: " + exception.getMessage());
        verifyNoInteractions(callback);
        verify(bufferPool, never()).allocate();
    }

    @Test
    public void readExceptionWithoutExplicitErrorCallbackEndsExchange() {
        requestHeaders.put(Headers.CONTENT_LENGTH, BODY.length);
        allocatingBuffersOfSize(8);
        FullBytesCallback callback = mock(FullBytesCallback.class);

        InputStream failingStream = new InputStream() {
            @Override
