/**
 * Unit tests for {@link UndertowOutputStream#write(byte[], int, int)}.
 *
 * <p>The stream is driven through a real {@link HttpServerExchange} whose connection hands out an
 * in memory {@link ByteBufferPool} and a sink channel backed by a {@link RecordingConduit}, which
 * makes all the bytes that reach the network observable.</p>
 */
@Timeout(30)
class UndertowOutputStreamWriteTests {

    private static final int BUFFER_SIZE = 16;

    /** A zero length write is a no-op and must not touch the exchange or the buffers. */
    @Test
    void writeWithZeroLengthIsIgnored() throws IOException {
        Environment env = new Environment(-1, BUFFER_SIZE);

        env.stream.write(new byte[] { 1, 2, 3, 4 }, 1, 0);

        assertEquals(0, env.stream.getBytesWritten());
        assertTrue(env.pool.allocated.isEmpty(), "no buffer may be allocated for an empty write");
        assertEquals(0, env.conduit.receivedBytes().length);
        assertFalse(env.conduit.shutdown);
    }

    /** A negative length is a no-op as well. */
    @Test
    void writeWithNegativeLengthIsIgnored() throws IOException {
        Environment env = new Environment(10, BUFFER_SIZE);

        env.stream.write(new byte[] { 1, 2, 3, 4 }, 0, -3);

        assertEquals(0, env.stream.getBytesWritten());
        assertTrue(env.pool.allocated.isEmpty(), "no buffer may be allocated for an empty write");
        assertEquals(0, env.conduit.receivedBytes().length);
    }

    /** Blocking IO from an IO thread is rejected before anything is buffered. */
    @Test
    void writeFromIoThreadIsRejected() throws InterruptedException {
        TestIoThread runner = new TestIoThread();
        Environment env = new Environment(-1, BUFFER_SIZE, runner);
        runner.body = () -> env.stream.write(payload(4, 0), 0, 4);

        runner.start();
        runner.join(TimeUnit.SECONDS.toMillis(15));

        assertFalse(runner.isAlive(), "the write did not finish");
        Throwable failure = runner.failure;
        assertNotNull(failure, "writing from the IO thread must fail");
        IllegalStateException exception = assertInstanceOf(IllegalStateException.class, failure);
        assertTrue(exception.getMessage().contains("UT000126"), exception.getMessage());
        assertTrue(exception.getMessage().contains("blocking IO from the IO thread"), exception.getMessage());
        assertEquals(0, env.stream.getBytesWritten());
        assertTrue(env.pool.allocated.isEmpty(), "no buffer may be allocated when the write is rejected");
        assertEquals(0, env.conduit.receivedBytes().length);
    }

    /** Once the stream is closed every write is rejected. */
    @Test
    void writeOnClosedStreamIsRejected() throws IOException {
        Environment env = new Environment(-1, BUFFER_SIZE);
        byte[] data = payload(5, 7);
        env.stream.write(data, 0, 5);
        env.stream.close();
        assertEquals(5, env.stream.getBytesWritten());
        assertEquals(5, env.conduit.receivedBytes().length);

        IOException exception = assertThrows(IOException.class, () -> env.stream.write(payload(2, 0), 0, 2));

        assertTrue(exception.getMessage().contains("UT000034"), exception.getMessage());
        assertEquals(5, env.stream.getBytesWritten(), "a rejected write must not be counted");
        assertEquals(5, env.conduit.receivedBytes().length, "a rejected write must not reach the channel");
    }

    /** Data that fits into the buffer stays buffered and only the requested slice is copied. */
    @Test
    void writeThatFitsIsBufferedAndHonoursOffsetAndLength() throws IOException {
        Environment env = new Environment(-1, BUFFER_SIZE);
        byte[] data = payload(10, 3);

        env.stream.write(data, 2, 5);

        assertEquals(5, env.stream.getBytesWritten());
        assertEquals(0, env.conduit.receivedBytes().length, "the data must stay in the stream buffer");
        assertEquals(1, env.pool.allocated.size(), "a single buffer is allocated for the stream");

        env.stream.close();

        assertArrayEquals(Arrays.copyOfRange(data, 2, 7), env.conduit.receivedBytes());
        assertTrue(env.conduit.shutdown, "the channel is shut down when the stream is closed");
        assertAllPooledBuffersClosed(env.pool);
    }

    /** A write that fills the buffer up completely flushes it to the channel. */
    @Test
    void writeThatFillsTheBufferFlushesIt() throws IOException {
        Environment env = new Environment(-1, BUFFER_SIZE);
        byte[] first = payload(BUFFER_SIZE, 0);
        byte[] second = payload(4, 90);

        env.stream.write(first, 0, BUFFER_SIZE);

        assertArrayEquals(first, env.conduit.receivedBytes());
        assertFalse(env.conduit.shutdown, "a full buffer must not shut the channel down");
        assertEquals(BUFFER_SIZE, env.stream.getBytesWritten());

        env.stream.write(second, 0, 4);

        assertEquals(BUFFER_SIZE, env.conduit.receivedBytes().length, "the second write must still be buffered");
        assertEquals(BUFFER_SIZE + 4, env.stream.getBytesWritten());

        env.stream.close();

        assertArrayEquals(concatenate(first, second), env.conduit.receivedBytes());
        assertTrue(env.conduit.shutdown);
        assertAllPooledBuffersClosed(env.pool);
    }

    /** Closing a stream that only holds buffered data publishes the buffered length. */
    @Test
    void closePublishesTheBufferedContentLength() throws IOException {
        Environment env = new Environment(-1, BUFFER_SIZE);
        env.stream.write(payload(3, 1), 0, 3);

        env.stream.close();

        assertEquals("3", env.exchange.getResponseHeaders().getFirst(Headers.CONTENT_LENGTH));
        assertEquals(3, env.conduit.receivedBytes().length);
    }

    /** Writing the final content-length sized chunk flushes and closes the stream. */
    @Test
    void writeOfLastChunkWithContentLengthClosesTheStream() throws IOException {
        Environment env = new Environment(4, BUFFER_SIZE);
        byte[] data = payload(4, 11);

        env.stream.write(data, 0, 4);

        assertArrayEquals(data, env.conduit.receivedBytes());
        assertTrue(env.conduit.shutdown, "the stream closes itself once the content length is written");
        assertEquals(4, env.stream.getBytesWritten());
        assertEquals("4", env.exchange.getResponseHeaders().getFirst(Headers.CONTENT_LENGTH),
                "the configured content length must not be replaced by the buffer position");

        IOException exception = assertThrows(IOException.class, () -> env.stream.write(payload(1, 0), 0, 1));
        assertTrue(exception.getMessage().contains("UT000034"), exception.getMessage());
        assertAllPooledBuffersClosed(env.pool);
    }

    /** A non final chunk of a content-length response is buffered without closing the stream. */
    @Test
    void intermediateChunkWithContentLengthStaysBuffered() throws IOException {
        Environment env = new Environment(10, BUFFER_SIZE);
        byte[] data = payload(10, 21);

        env.stream.write(data, 0, 4);

        assertEquals(4, env.stream.getBytesWritten());
        assertEquals(0, env.conduit.receivedBytes().length);
        assertFalse(env.conduit.shutdown);

        env.stream.write(data, 4, 6);

        assertArrayEquals(data, env.conduit.receivedBytes());
        assertTrue(env.conduit.shutdown);
        assertEquals(10, env.stream.getBytesWritten());
    }

    /** A write larger than the buffer is spread over several buffers and written at once. */
    @Test
    void writeLargerThanTheBufferUsesAdditionalBuffers() throws IOException {
        Environment env = new Environment(-1, BUFFER_SIZE);
        byte[] data = payload(100, 0);

        env.stream.write(data, 0, 100);

        assertArrayEquals(data, env.conduit.receivedBytes());
        assertEquals(100, env.stream.getBytesWritten());
        assertFalse(env.conduit.shutdown, "an unknown content length must not close the stream");
        assertTrue(env.pool.allocated.size() > 1, "the payload does not fit into a single buffer");
        assertTrue(env.pool.allocated.size() <= 11,
                "at most MAX_BUFFERS_TO_ALLOCATE scratch buffers may be used, allocated: "
                        + env.pool.allocated.size());
        assertScratchBuffersClosed(env.pool);
    }

    /** Payloads larger than all scratch buffers are written by re-using the buffers. */
    @Test
    void writeMuchLargerThanTheBuffersReusesThem() throws IOException {
        Environment env = new Environment(-1, BUFFER_SIZE);
        byte[] data = payload(400, 5);

        env.stream.write(data, 0, 400);

        assertArrayEquals(data, env.conduit.receivedBytes());
        assertEquals(400, env.stream.getBytesWritten());
        assertTrue(env.pool.allocated.size() <= 11,
                "buffers are re-used instead of allocating one buffer per chunk, allocated: "
                        + env.pool.allocated.size());
        assertScratchBuffersClosed(env.pool);
    }

    /** Consecutive large writes send every byte exactly once. */
    @Test
    void consecutiveLargeWritesSendEveryByteOnce() throws IOException {
        Environment env = new Environment(-1, BUFFER_SIZE);
        byte[] first = payload(50, 0);
        byte[] second = payload(50, 100);

        env.stream.write(first, 0, 50);
        env.stream.write(second, 0, 50);

        assertArrayEquals(concatenate(first, second), env.conduit.receivedBytes());
        assertEquals(100, env.stream.getBytesWritten());
    }

    /** The final content-length chunk is written together with the still buffered data. */
    @Test
    void writeOfLastChunkLargerThanTheBufferFlushesPreviousDataToo() throws IOException {
        Environment env = new Environment(100, BUFFER_SIZE);
        byte[] data = payload(100, 0);

        env.stream.write(data, 0, 10);
        assertEquals(0, env.conduit.receivedBytes().length, "the first chunk must stay buffered");

        env.stream.write(data, 10, 90);

        assertArrayEquals(data, env.conduit.receivedBytes());
        assertTrue(env.conduit.shutdown, "the response is complete after the last chunk");
        assertEquals(100, env.stream.getBytesWritten());
        assertAllPooledBuffersClosed(env.pool);
    }

    /** A final chunk that exactly fills the buffer is flushed and the stream is closed. */
    @Test
    void writeOfLastChunkThatExactlyFillsTheBufferClosesTheStream() throws IOException {
        Environment env = new Environment(BUFFER_SIZE, BUFFER_SIZE);
        byte[] data = payload(BUFFER_SIZE, 33);

        env.stream.write(data, 0, BUFFER_SIZE);

        assertArrayEquals(data, env.conduit.receivedBytes());
        assertTrue(env.conduit.shutdown, "the response is complete after the last chunk");
        assertEquals(BUFFER_SIZE, env.stream.getBytesWritten());
        assertAllPooledBuffersClosed(env.pool);
    }

    /** A failing channel is reported to the caller and no byte is accounted for. */
    @Test
    void channelFailureIsPropagated() {
        Environment env = new Environment(-1, BUFFER_SIZE);
        env.conduit.failure = new IOException("write failed");

        IOException exception = assertThrows(IOException.class,
                () -> env.stream.write(payload(BUFFER_SIZE, 0), 0, BUFFER_SIZE));

        assertEquals("write failed", exception.getMessage());
        assertEquals(0, env.stream.getBytesWritten(), "a failed write must not be counted");
    }

    /** The single byte convenience method funnels through the array based write. */
    @Test
    void singleByteWriteReachesTheChannel() throws IOException {
        Environment env = new Environment(-1, BUFFER_SIZE);

        env.stream.write(0x41);

        assertEquals(1, env.stream.getBytesWritten());

        env.stream.close();

        assertArrayEquals(new byte[] { 0x41 }, env.conduit.receivedBytes());
    }

    private static void assertAllPooledBuffersClosed(TestByteBufferPool pool) {
        for (TestPooledBuffer pooled : pool.allocated) {
            assertFalse(pooled.isOpen(), "pooled buffer was not returned to the pool");
        }
    }

    private static void assertScratchBuffersClosed(TestByteBufferPool pool) {
        // the first allocated buffer belongs to the stream itself, the others are scratch buffers
        for (int i = 1; i < pool.allocated.size(); ++i) {
            assertFalse(pool.allocated.get(i).isOpen(), "scratch buffer " + i + " was not returned to the pool");
        }
    }

    private static byte[] payload(final int length, final int seed) {
        byte[] bytes = new byte[length];
        for (int i = 0; i < length; ++i) {
            bytes[i] = (byte) (seed + i);
        }
        return bytes;
    }

    private static byte[] concatenate(final byte[] first, final byte[] second) {
        byte[] result = Arrays.copyOf(first, first.length + second.length);
        System.arraycopy(second, 0, result, first.length, second.length);
        return result;
    }

    /**
     * Task executed by a {@link TestIoThread}.
     */
    private interface IoTask {
        void run() throws IOException;
    }

    /**
     * An {@link XnioIoThread} that runs a single task; used to exercise the IO thread check.
     *
     * <p>{@link HttpServerExchange#isInIoThread()} compares the IO thread of the connection with
     * the current thread, so the write under test has to run on an IO thread.</p>
     */
    private static final class TestIoThread extends XnioIoThread {

        private IoTask body;
        private volatile Throwable failure;

        private TestIoThread() {
            super(null, 0, "undertow-output-stream-test-io-thread");
        }

        @Override
        public void run() {
            try {
                body.run();
            } catch (Throwable t) {
                failure = t;
            }
        }

        @Override
        public void execute(final Runnable command) {
            command.run();
        }

        @Override
        public XnioExecutor.Key executeAfter(final Runnable command, final long delay, final TimeUnit timeUnit) {
            throw new UnsupportedOperationException("not used by the tests");
        }

        @Override
