    /**
     * Wires an {@link UndertowOutputStream} to an exchange, an in memory buffer pool and a
     * recording conduit.
     */
    private static final class Environment {

        private final TestByteBufferPool pool;
        private final RecordingConduit conduit;
        private final HttpServerExchange exchange;
        private final UndertowOutputStream stream;

        private Environment(final long contentLength, final int bufferSize) {
            this(contentLength, bufferSize, null);
        }

        private Environment(final long contentLength, final int bufferSize, final XnioIoThread ioThread) {
            this.pool = new TestByteBufferPool(bufferSize);
            this.conduit = new RecordingConduit();
            ConduitStreamSinkChannel sinkChannel = new ConduitStreamSinkChannel(Configurable.EMPTY, conduit);

            ServerConnection connection = createNiceMock(ServerConnection.class);
            expect(connection.getByteBufferPool()).andReturn(pool).anyTimes();
            if (ioThread != null) {
                expect(connection.getIoThread()).andReturn(ioThread).anyTimes();
            }
            this.exchange = new HttpServerExchange(connection);
            recordSinkChannel(connection, sinkChannel);
            recordSinkConduit(connection, exchange, conduit);
            replay(connection);

            if (contentLength != -1) {
                exchange.setResponseContentLength(contentLength);
            }
            exchange.setRequestMethod(Methods.POST);

            this.stream = new UndertowOutputStream(exchange);
        }

        /**
         * {@link ServerConnection#getSinkChannel()} is protected and therefore recorded reflectively.
         */
        private static void recordSinkChannel(final ServerConnection connection,
                final ConduitStreamSinkChannel sinkChannel) {
            try {
                Method method = ServerConnection.class.getDeclaredMethod("getSinkChannel");
                method.setAccessible(true);
                expect(method.invoke(connection)).andReturn(sinkChannel).anyTimes();
            } catch (ReflectiveOperationException e) {
                throw new AssertionError("unable to record getSinkChannel", e);
            }
        }

        /**
         * {@link ServerConnection#getSinkConduit(HttpServerExchange, StreamSinkConduit)} is protected
         * and therefore recorded reflectively; the conduit is passed through unchanged.
         */
        private static void recordSinkConduit(final ServerConnection connection, final HttpServerExchange exchange,
                final StreamSinkConduit conduit) {
            try {
                Method method = ServerConnection.class.getDeclaredMethod("getSinkConduit", HttpServerExchange.class,
                        StreamSinkConduit.class);
                method.setAccessible(true);
                expect(method.invoke(connection, exchange, conduit))
                        .andReturn(conduit).anyTimes();
            } catch (ReflectiveOperationException e) {
                throw new AssertionError("unable to record getSinkConduit", e);
            }
        }
    }

    /**
     * A {@link StreamSinkConduit} that records every byte handed to it.
     */
    private static final class RecordingConduit implements StreamSinkConduit {

        private final ByteArrayOutputStream received = new ByteArrayOutputStream();
        private volatile boolean shutdown;
        private volatile IOException failure;

        private byte[] receivedBytes() {
            return received.toByteArray();
        }

        @Override
        public long transferFrom(final FileChannel src, final long position, final long count) {
            return 0;
        }

        @Override
        public long transferFrom(final StreamSourceChannel source, final long count, final ByteBuffer throughBuffer) {
            return 0;
        }

        @Override
        public int write(final ByteBuffer src) throws IOException {
            checkFailure();
            return (int) drain(src);
        }

        @Override
        public long write(final ByteBuffer[] srcs, final int offs, final int len) throws IOException {
            checkFailure();
            long written = 0;
            for (int i = offs; i < offs + len; ++i) {
                written += drain(srcs[i]);
            }
            return written;
        }

        @Override
        public int writeFinal(final ByteBuffer src) throws IOException {
            checkFailure();
            int written = (int) drain(src);
            shutdown = true;
            return written;
        }

        @Override
        public long writeFinal(final ByteBuffer[] srcs, final int offs, final int len) throws IOException {
            checkFailure();
            long written = 0;
            for (int i = offs; i < offs + len; ++i) {
                written += drain(srcs[i]);
            }
            shutdown = true;
            return written;
        }

        @Override
        public void terminateWrites() {
            shutdown = true;
        }

        @Override
        public boolean isWriteShutdown() {
            return shutdown;
        }

        @Override
        public void resumeWrites() {
        }

        @Override
        public void suspendWrites() {
        }

        @Override
        public void wakeupWrites() {
        }

        @Override
        public boolean isWriteResumed() {
            return false;
        }

        @Override
        public void awaitWritable() {
            throw new AssertionError("the test must never need to wait for writability");
        }

        @Override
        public void awaitWritable(final long time, final TimeUnit timeUnit) {
            throw new AssertionError("the test must never need to wait for writability");
        }

        @Override
        public XnioIoThread getWriteThread() {
            return null;
        }

        @Override
        public void setWriteReadyHandler(final WriteReadyHandler handler) {
        }

        @Override
        public void truncateWrites() {
        }

        @Override
        public boolean flush() {
            return true;
        }

        @Override
        public XnioWorker getWorker() {
            return null;
        }

        private void checkFailure() throws IOException {
            if (failure != null) {
                throw failure;
            }
        }

        private long drain(final ByteBuffer buffer) {
            int remaining = buffer.remaining();
            byte[] bytes = new byte[remaining];
            buffer.get(bytes);
            received.write(bytes, 0, remaining);
            return remaining;
        }
    }

    private static final class TestByteBufferPool implements ByteBufferPool {

        private final int bufferSize;
        private final List<TestPooledBuffer> allocated = new ArrayList<>();

        private TestByteBufferPool(final int bufferSize) {
            this.bufferSize = bufferSize;
        }

        @Override
        public PooledByteBuffer allocate() {
            TestPooledBuffer pooled = new TestPooledBuffer(ByteBuffer.allocate(bufferSize));
            allocated.add(pooled);
