        }

        @Override
        public ByteBufferPool getArrayBackedPool() {
            return this;
        }

        @Override
        public void close() {
        }

        @Override
        public int getBufferSize() {
            return bufferSize;
        }

        @Override
        public boolean isDirect() {
            return false;
        }
    }

    private static final class TestPooledBuffer implements PooledByteBuffer {

        private final ByteBuffer buffer;
