        handler.addPredicatedHandler(pred("p0", false), rec("h0"));
        handler.addPredicatedHandler(pred("p1", true), rec("h1", exchange -> {
            if (restartRequests.getAndIncrement() == 0) {
                exchange.putAttachment(PredicatesHandler.RESTART, Boolean.TRUE);
            }
        }));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);

        assertLog("p0", "p1", "h1", "p0", "p1", "h1");
        assertEquals(Integer.valueOf(2), exchange.getAttachment(positionKey(handler)));
