        AtomicInteger restartRequests = new AtomicInteger();
        handler.addPredicatedHandler(pred("p0", true), rec("h0", exchange -> {
            if (restartRequests.incrementAndGet() <= 2) {
                exchange.putAttachment(PredicatesHandler.RESTART, Boolean.TRUE);
            }
        }));
        HttpServerExchange exchange = newExchange();

