        handler.addPredicatedHandler(exchange -> {
            log.add("p0");
            return !firstPass.get();
        }, rec("h0"), rec("else0", exchange -> {
            firstPass.set(false);
            exchange.putAttachment(PredicatesHandler.RESTART, Boolean.TRUE);
