    // ------------------------------------------------------------------
    // DONE marker handling and resumed invocations
    // ------------------------------------------------------------------

    @Test
    void doneMarkerOnReentrySkipsRemainingHandlersAndRunsNextHandler() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        handler.addPredicatedHandler(pred("p0", true), chain -> exchange -> {
            log.add("h0");
            exchange.putAttachment(PredicatesHandler.DONE, Boolean.TRUE);
            chain.handleRequest(exchange);
        });
        handler.addPredicatedHandler(pred("p1", true), rec("h1"));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);

        assertLog("p0", "h0", "next");
        assertNull(exchange.getAttachment(positionKey(handler)),
                "the position must be dropped once the chain is marked as done");
        assertNotNull(exchange.getAttachment(PredicatesHandler.DONE));

        // a second, independent invocation must resolve the chain from the very beginning again
        log.clear();
        handler.handleRequest(exchange);
        assertLog("p0", "h0", "next");
    }

    @Test
    void doneMarkerWithoutReentryDoesNotSkipFollowingHandlersForTheSamePass() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        handler.addPredicatedHandler(pred("p0", true), rec("h0",
                exchange -> exchange.putAttachment(PredicatesHandler.DONE, Boolean.TRUE)));
        handler.addPredicatedHandler(pred("p1", true), rec("h1"));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);

        // the done marker is only inspected when the chain is re-entered, so this pass simply stops
        assertLog("p0", "h0");
        assertEquals(Integer.valueOf(1), exchange.getAttachment(positionKey(handler)));
    }

    @Test
    void resumedInvocationContinuesAfterTheLastExecutedPredicate() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        handler.addPredicatedHandler(pred("p0", true), rec("h0"));
        handler.addPredicatedHandler(pred("p1", true), rec("h1"));
