        handler.handleRequest(exchange);

        assertLog("p1", "h1");
        assertEquals(Integer.valueOf(2), exchange.getAttachment(positionKey(handler)));
    }

    @Test
    void resumedInvocationRunsNextHandlerWhenNoPredicateMatchesAnymore() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        handler.addPredicatedHandler(pred("p0", true), rec("h0"));
        handler.addPredicatedHandler(pred("p1", false), rec("h1"));
