    }

    @Test
    void resumedInvocationWithEmptyRemainderRunsNextHandlerTwice() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        handler.addPredicatedHandler(pred("p0", true), rec("h0"));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);
        assertLog("p0", "h0");

        log.clear();
        handler.handleRequest(exchange);
        assertLog("next");

        // the position stays at the end of the chain, so further invocations run the next handler again
        log.clear();
        handler.handleRequest(exchange);
        assertLog("next");
    }

    // ------------------------------------------------------------------
    // fluent API
    // ------------------------------------------------------------------

    @Test
    void addPredicatedHandlerReturnsTheSameHandlerInstance() {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        assertSame(handler, handler.addPredicatedHandler(pred("p0", true), rec("h0")));
        assertSame(handler, handler.addPredicatedHandler(pred("p1", false), rec("h1"), rec("else1")));
    }

    @Test
    void handlerAddedAfterFirstInvocationIsUsedOnTheNextInvocation() throws Exception {
        PredicatesHandler handler = new PredicatesHandler(terminalNext());
        handler.addPredicatedHandler(pred("p0", false), rec("h0"));
        HttpServerExchange exchange = newExchange();

        handler.handleRequest(exchange);
        assertLog("p0", "next");

        handler.addPredicatedHandler(pred("p1", false), rec("h1"));
        log.clear();
        handler.handleRequest(exchange);
        assertLog("p0", "p1", "next");
        assertFalse(log.contains("h0"));
        assertFalse(log.contains("h1"));
    }
}

