    }

    @Test
    void returnsFalseAndLeavesBufferUntouchedWhenRemainingSpaceIsSmallerThanInputLength() {
        ByteBuffer buffer = ByteBuffer.allocate(2);
        assertFalse(HPackHuffman.encode(buffer, "abc", false));
        assertEquals(0, buffer.position());
        assertArrayEquals(new byte[2], wholeContent(buffer));
    }

    @Test
    void returnsFalseWithoutMovingPositionWhenNoSpaceIsRemaining() {
        ByteBuffer buffer = ByteBuffer.allocate(5);
        buffer.position(5);
        assertFalse(HPackHuffman.encode(buffer, "abc", false));
        assertEquals(5, buffer.position());
    }

    @Test
    void encodesLongStringWithSingleByteLengthPrefix() {
        // 201 '0' characters occupy 201 * 5 = 1005 bits -> 126 bytes, which still fits into the
        // 7 bit prefix of the header byte
        String value = repeat('0', 201);
        ByteBuffer buffer = ByteBuffer.allocate(1000);
        assertTrue(HPackHuffman.encode(buffer, value, false));
        assertEquals(127, buffer.position());
        byte[] content = writtenBytes(buffer);
        assertEquals((byte) 0xfe, content[0], "header byte should be 0x80 | 126");
        assertEquals((byte) 0x07, content[126], "the trailing byte holds 7 zero bits plus 1 EOS padding bit");
        for (int i = 1; i < 126; ++i) {
            assertEquals(0, content[i], "payload byte " + i + " should be zero");
        }
    }

    @Test
    void encodesLongStringWithMultiByteLengthPrefixFor127Bytes() {
        // 202 '0' characters occupy 1010 bits -> 127 bytes, the first value that needs a
        // continuation byte in the length prefix
        String value = repeat('0', 202);
        ByteBuffer buffer = ByteBuffer.allocate(1000);
        assertTrue(HPackHuffman.encode(buffer, value, false));
        assertEquals(129, buffer.position());
        byte[] content = writtenBytes(buffer);
        assertEquals((byte) 0xff, content[0], "header byte should be 0x80 | 127");
        assertEquals((byte) 0x00, content[1], "the length remainder is encoded in a continuation byte");
        assertEquals((byte) 0x3f, content[128], "the trailing byte holds 6 zero bits plus 2 EOS padding bits");
    }

    @Test
    void encodesLongStringWithMultiByteLengthPrefixFor128Bytes() {
        // 204 '0' characters occupy 1020 bits -> 128 bytes
        String value = repeat('0', 204);
        ByteBuffer buffer = ByteBuffer.allocate(1000);
        assertTrue(HPackHuffman.encode(buffer, value, false));
        assertEquals(130, buffer.position());
        byte[] content = writtenBytes(buffer);
        assertEquals((byte) 0xff, content[0], "header byte should be 0x80 | 127");
        assertEquals((byte) 0x01, content[1], "128 - 127 leaves a remainder of 1");
        assertEquals((byte) 0x0f, content[129], "the trailing byte holds 4 zero bits plus 4 EOS padding bits");
    }

    @ParameterizedTest
    @ValueSource(strings = { "", "a", "0123456789", "abc123", "www.example.com", "no-cache", "custom-value",
            "Mon, 21 Oct 2013 20:13:21 GMT", "https://www.example.com", "Hello, World! 123" })
    void encodedOutputDecodesBackToTheOriginalString(String value) throws Exception {
        assertEquals(value, decode(value, 1000));
    }

    @Test
    void encodedOutputDecodesBackToTheOriginalNonAsciiCharacters() throws Exception {
        String value = "\u00ff00000000";
        assertEquals(value, decode(value, 100));
    }

    @Test
    void truncatesCharactersToTheirLowByte() {
        byte[] expected = bytes(0x87, 0xff, 0xc0, 0x00, 0x00, 0x00, 0x00, 0x07);
        assertEncodesTo(expected, "\u000000000000", false);
        assertEncodesTo(expected, "\u010000000000", false);
        assertEncodesTo(expected, "\u020000000000", false);
    }

    @Test
    void forceLowercaseProducesTheSameBytesAsLowercaseInput() {
        ByteBuffer forced = ByteBuffer.allocate(100);
        assertTrue(HPackHuffman.encode(forced, "WWW.EXAMPLE.COM", true));
        ByteBuffer expected = ByteBuffer.allocate(100);
        assertTrue(HPackHuffman.encode(expected, WWW_EXAMPLE_COM, false));
        assertArrayEquals(writtenBytes(expected), writtenBytes(forced));
        assertArrayEquals(bytes(0x8c, 0xf1, 0xe3, 0xc2, 0xe5, 0xf2, 0x3a, 0x6b, 0xa0, 0xab, 0x90, 0xf4, 0xff),
                writtenBytes(forced), "lower casing must happen before the Huffman codes are looked up");
    }

    @Test
    void forceLowercaseChangesTheEncodingOfUpperCaseLetters() {
        ByteBuffer upper = ByteBuffer.allocate(100);
        assertTrue(HPackHuffman.encode(upper, "ABC", true));
        assertArrayEquals(bytes(0x82, 0x1c, 0x64), writtenBytes(upper), "'ABC' should be encoded like 'abc'");

        ByteBuffer notForced = ByteBuffer.allocate(100);
        assertTrue(HPackHuffman.encode(notForced, "ABC", false));
        assertArrayEquals(bytes(0x83, 0x86, 0xed, 0xef), writtenBytes(notForced));
        assertNotEquals(hex(writtenBytes(upper)), hex(writtenBytes(notForced)));
    }

    @Test
    void forceLowercaseDoesNotAlterNonAlphabeticCharacters() {
        String value = "0123456789!@#$";
        ByteBuffer forced = ByteBuffer.allocate(100);
        assertTrue(HPackHuffman.encode(forced, value, true));
        ByteBuffer notForced = ByteBuffer.allocate(100);
        assertTrue(HPackHuffman.encode(notForced, value, false));
        assertArrayEquals(writtenBytes(notForced), writtenBytes(forced));
    }

    @Test
    void forceLowercaseUsesTheRootLocaleBehaviourForAsciiOnly() {
        String value = "Hello, World! 123";
        ByteBuffer forced = ByteBuffer.allocate(100);
        assertTrue(HPackHuffman.encode(forced, value, true));
        ByteBuffer expected = ByteBuffer.allocate(100);
        assertTrue(HPackHuffman.encode(expected, value.toLowerCase(Locale.ROOT), false));
        assertArrayEquals(writtenBytes(expected), writtenBytes(forced));
    }

    @Test
    void returnsFalseAndRestoresPositionWhenEncodedFormIsLargerThanTheInput() {
        ByteBuffer buffer = ByteBuffer.allocate(100);
        buffer.put((byte) 0x11);
        buffer.put((byte) 0x22);
        int start = buffer.position();
        // the code for \u0001 is 23 bits long, so this can never be shorter than the input
        assertFalse(HPackHuffman.encode(buffer, "\u0001", false));
        assertEquals(start, buffer.position(), "the position must be restored to the start of the encoding");
        assertEquals((byte) 0x11, buffer.get(0));
        assertEquals((byte) 0x22, buffer.get(1));
    }

    @Test
    void returnsFalseAndRestoresPositionWhenBufferIsExhaustedWhileWritingACode() {
        // two bytes of space, but the header plus the huffman code need four bytes
        ByteBuffer buffer = ByteBuffer.allocate(2);
        assertFalse(HPackHuffman.encode(buffer, "\u0001", false));
        assertEquals(0, buffer.position());

        ByteBuffer withPrefix = ByteBuffer.allocate(6);
        withPrefix.put((byte) 0x33);
        withPrefix.put((byte) 0x44);
        assertFalse(HPackHuffman.encode(withPrefix, "\u0001", false));
        assertEquals(2, withPrefix.position());
        assertEquals((byte) 0x33, withPrefix.get(0));
        assertEquals((byte) 0x44, withPrefix.get(1));
    }

    @Test
    void requiresMoreSpaceThanTheInputLength() {
        // the encoding of 'www.example.com' is 13 bytes long, but the implementation refuses to
        // start when the remaining space does not exceed the input length
        ByteBuffer tooSmall = ByteBuffer.allocate(15);
        assertFalse(HPackHuffman.encode(tooSmall, WWW_EXAMPLE_COM, false));
        assertEquals(0, tooSmall.position());
        assertArrayEquals(new byte[15], wholeContent(tooSmall));

        ByteBuffer justEnough = ByteBuffer.allocate(16);
        assertTrue(HPackHuffman.encode(justEnough, WWW_EXAMPLE_COM, false));
        assertEquals(13, justEnough.position());
    }

    @Test
    void doesNotWritePastTheEndOfTheEncodedData() {
        ByteBuffer buffer = ByteBuffer.allocate(16);
        assertTrue(HPackHuffman.encode(buffer, WWW_EXAMPLE_COM, false));
        assertEquals(13, buffer.position());
        byte[] content = wholeContent(buffer);
        for (int i = 13; i < content.length; ++i) {
            assertEquals(0, content[i], "byte " + i + " is past the encoded data and must not be written");
        }
    }

    @Test
    void appendsToExistingBufferContentAndPreservesThePrefix() {
        ByteBuffer buffer = ByteBuffer.allocate(40);
        buffer.put((byte) 0x11);
        buffer.put((byte) 0x22);
        int start = buffer.position();
        assertTrue(HPackHuffman.encode(buffer, WWW_EXAMPLE_COM, false));
        assertEquals(start + 13, buffer.position());
        assertEquals((byte) 0x11, buffer.get(0));
        assertEquals((byte) 0x22, buffer.get(1));
        byte[] encoded = new byte[buffer.position() - start];
        for (int i = 0; i < encoded.length; ++i) {
            encoded[i] = buffer.get(start + i);
        }
        assertArrayEquals(bytes(0x8c, 0xf1, 0xe3, 0xc2, 0xe5, 0xf2, 0x3a, 0x6b, 0xa0, 0xab, 0x90, 0xf4, 0xff), encoded);
    }

    @Test
    void supportsSeveralConsecutiveEncodingsInTheSameBuffer() {
        ByteBuffer buffer = ByteBuffer.allocate(64);
        assertTrue(HPackHuffman.encode(buffer, "custom-key", true));
        assertTrue(HPackHuffman.encode(buffer, "custom-value", true));
        assertEquals(19, buffer.position());
        byte[] expected = bytes(0x88, 0x25, 0xa8, 0x49, 0xe9, 0x5b, 0xa9, 0x7d, 0x7f,
                0x89, 0x25, 0xa8, 0x49, 0xe9, 0x5b, 0xb8, 0xe8, 0xb4, 0xbf);
        assertArrayEquals(expected, writtenBytes(buffer));
    }

    @Test
    void rejectsNullInput() {
        ByteBuffer buffer = ByteBuffer.allocate(10);
        assertThrows(NullPointerException.class, () -> HPackHuffman.encode(buffer, null, false));
    }
}

