    @Test
    void zeroTableSizeUpdateClearsTheDynamicTable() throws Exception {
        decoder = newDecoder(100);
        decoder.decode(literal(0x40, "a", "b"), false);

        assertEquals(1, decoder.getFilledTableSlots());
        assertEquals(34, decoder.getCurrentMemorySize());

        decoder.decode(buffer(0x20), false); // zero with five-bit prefix

        assertEquals(0, decoder.getSpecifiedMemorySize());
        assertEquals(0, decoder.getFilledTableSlots());
        assertEquals(0, decoder.getCurrentMemorySize());
    }

    private HpackDecoder newDecoder(int maxAllowedMemorySize) {
        HpackDecoder result = new HpackDecoder(maxAllowedMemorySize);
        result.setHeaderEmitter((name, value, neverIndex) ->
                emitted.add(new EmittedHeader(name.toString(), value, neverIndex)));
        return result;
    }

    private void assertEmitted(int index, String expectedName, String expectedValue, boolean expectedNeverIndex) {
        EmittedHeader header = emitted.get(index);
        assertEquals(expectedName, header.name());
        assertEquals(expectedValue, header.value());
        assertEquals(expectedNeverIndex, header.neverIndex());
    }

    private static ByteBuffer literal(int representation, String name, String value) {
        return buffer(literalOctets(representation, name, value));
    }

    private static int[] literalOctets(int representation, String name, String value) {
        return concat(new int[] { representation }, encodedString(name), encodedString(value));
    }

    private static int[] encodedString(String value) {
        byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
        if (bytes.length >= 127) {
            throw new IllegalArgumentException("Test fixture only supports short strings");
        }
        int[] result = new int[bytes.length + 1];
        result[0] = bytes.length;
        for (int i = 0; i < bytes.length; i++) {
            result[i + 1] = bytes[i] & 0xff;
        }
        return result;
    }

    private static int[] concat(int[]... arrays) {
        int length = Arrays.stream(arrays).mapToInt(array -> array.length).sum();
        int[] result = new int[length];
        int offset = 0;
        for (int[] array : arrays) {
            System.arraycopy(array, 0, result, offset, array.length);
            offset += array.length;
        }
        return result;
    }

    private static ByteBuffer buffer(int... octets) {
        byte[] bytes = new byte[octets.length];
        for (int i = 0; i < octets.length; i++) {
            bytes[i] = (byte) octets[i];
        }
        return ByteBuffer.wrap(bytes);
    }

    private record EmittedHeader(String name, String value, boolean neverIndex) {
    }
}

