    private static final int DEFAULT_MAX_TABLE_SIZE = 4096;

    private static final byte[] LITERAL_X_FOO_BAR = bytes(0x40, 0x05, 'x', '-', 'f', 'o', 'o', 0x03, 'b', 'a', 'r');

    private static final HpackEncoder.HpackHeaderFunction NO_INDEXING_NO_HUFFMAN = function(false, false);

    private static final HpackEncoder.HpackHeaderFunction HUFFMAN_NO_INDEXING = function(false, true);

    @Test
    public void emptyHeaderMapProducesNoBytes() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        ByteBuffer target = ByteBuffer.allocate(64);

        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(new HeaderMap(), target));
        assertEquals(0, target.position());
