    @Test
    public void carriageReturnAndLineFeedInValuesAreReplacedWithSpaces() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE, NO_INDEXING_NO_HUFFMAN);
        assertEncoded(encoder, bytes(0x10, 0x06, 'x', '-', 'c', 'r', 'l', 'f', 0x04, 'a', ' ', ' ', 'b'),
