    @Test
    public void longValueIsHuffmanEncoded() {
        // the value length octet 0x87 has the huffman bit set and announces 7 bytes for
        // eleven 'a' characters (five bits each, padded with ones)
        assertEncoded(bytes(0x40, 0x06, 'x', '-', 'h', 'u', 'f', 'f', 0x87,
                0x18, 0xc6, 0x31, 0x8c, 0x63, 0x18, 0xc7), headers("x-huff", "aaaaaaaaaaa"));
    }

    @Test
    public void longHeaderNameIsHuffmanEncodedWhenEnabled() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE, HUFFMAN_NO_INDEXING);
        assertEncoded(encoder, bytes(0x10, 0x85, 0xf2, 0xb4, 0xf6, 0xcb, 0x2f, 0x87,
                0x18, 0xc6, 0x31, 0x8c, 0x63, 0x18, 0xc7), headers("x-huff", "aaaaaaaaaaa"));
    }

    @Test
    public void huffmanEncodedNameAndValueDecodeBackToTheOriginalHeader() throws Exception {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE, HUFFMAN_NO_INDEXING);
        ByteBuffer target = ByteBuffer.allocate(128);

