    @Test
    public void tableSizeUpdateAffectsTheIndexingDecision() {
        // x-foo: bar needs 32 + 5 + 3 = 40 octets of table space
        HpackEncoder tooSmall = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        tooSmall.setMaxTableSize(40);
        assertEncoded(tooSmall, bytes(0x3f, 0x09, 0x10, 0x05, 'x', '-', 'f', 'o', 'o', 0x03, 'b', 'a', 'r'),
                headers("x-foo", "bar"));

        HpackEncoder bigEnough = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        bigEnough.setMaxTableSize(41);
        assertEncoded(bigEnough, bytes(0x3f, 0x0a, 0x40, 0x05, 'x', '-', 'f', 'o', 'o', 0x03, 'b', 'a', 'r'),
                headers("x-foo", "bar"));
        assertEncoded(bigEnough, bytes(0xbe), headers("x-foo", "bar"));
    }

    @Test
    public void oldestDynamicTableEntryIsEvictedWhenTheTableIsFull() {
        // each entry needs 32 + 5 + 3 = 40 octets, so a 50 octet table can only hold one of them
        HpackEncoder encoder = new HpackEncoder(50);
        HeaderMap first = headers("x-aaa", "bbb");

        ByteBuffer firstTarget = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(first, firstTarget));
        assertArrayEquals(bytes(0x40, 0x05, 'x', '-', 'a', 'a', 'a', 0x03, 'b', 'b', 'b'),
                bytesOf(firstTarget), () -> "first encoding was " + hexOf(firstTarget));

        ByteBuffer secondTarget = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers("x-ccc", "ddd"), secondTarget));
        assertArrayEquals(bytes(0x40, 0x05, 'x', '-', 'c', 'c', 'c', 0x03, 'd', 'd', 'd'),
                bytesOf(secondTarget), () -> "second encoding was " + hexOf(secondTarget));

        // the first entry has been evicted, so it has to be sent literally again
        ByteBuffer thirdTarget = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(first, thirdTarget));
        assertArrayEquals(bytes(0x40, 0x05, 'x', '-', 'a', 'a', 'a', 0x03, 'b', 'b', 'b'),
                bytesOf(thirdTarget), () -> "third encoding was " + hexOf(thirdTarget));
    }

    @Test
    public void overflowIsReturnedOnlyWhenTheBufferIsSmallerThanTheRequiredSize() {
        // x-foo: bar requires 11 + 5 + 1 + 3 = 20 octets of room (the encoding itself needs 11)
        HeaderMap exact = headers("x-foo", "bar");
        HpackEncoder exactEncoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        ByteBuffer exactTarget = ByteBuffer.allocate(20);
        assertEquals(HpackEncoder.State.COMPLETE, exactEncoder.encode(exact, exactTarget));
        assertArrayEquals(LITERAL_X_FOO_BAR, bytesOf(exactTarget), () -> "encoding was " + hexOf(exactTarget));

        HeaderMap tooSmall = headers("x-foo", "bar");
        HpackEncoder overflowEncoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        ByteBuffer tooSmallTarget = ByteBuffer.allocate(19);
        assertEquals(HpackEncoder.State.OVERFLOW, overflowEncoder.encode(tooSmall, tooSmallTarget));
        assertEquals(0, tooSmallTarget.position());

        ByteBuffer resumeTarget = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, overflowEncoder.encode(tooSmall, resumeTarget));
        assertArrayEquals(LITERAL_X_FOO_BAR, bytesOf(resumeTarget), () -> "resumed encoding was " + hexOf(resumeTarget));
    }

    @Test
    public void overflowAfterPseudoHeadersIsResumedForTheRemainingHeaders() {
        HeaderMap headers = headers(":method", "GET");
        headers.put(new HttpString("x-very-long-header-name"), "value");

        HpackEncoder reference = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        ByteBuffer referenceTarget = ByteBuffer.allocate(256);
        assertEquals(HpackEncoder.State.COMPLETE, reference.encode(headers, referenceTarget));

        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        // large enough for the pseudo header (which is encoded first) but not for the regular header
        ByteBuffer firstTarget = ByteBuffer.allocate(30);
        assertEquals(HpackEncoder.State.OVERFLOW, encoder.encode(headers, firstTarget));
        assertArrayEquals(bytes(0x82), bytesOf(firstTarget), () -> "first encoding was " + hexOf(firstTarget));

        ByteBuffer secondTarget = ByteBuffer.allocate(256);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers, secondTarget));

        ByteBuffer combined = ByteBuffer.allocate(referenceTarget.position());
        ByteBuffer firstView = readView(firstTarget);
        combined.put(firstView);
        combined.put(readView(secondTarget));
        assertArrayEquals(bytesOf(referenceTarget), bytesOf(combined),
                () -> "split encoding was " + hexOf(combined) + " but the reference encoding was " + hexOf(referenceTarget));
    }

    @Test
    public void overflowIsResumedWhenRoomBecomesAvailable() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        HeaderMap headers = headers("x-foo", "bar");

        assertEquals(HpackEncoder.State.OVERFLOW, encoder.encode(headers, ByteBuffer.allocate(0)));
        assertEquals(HpackEncoder.State.OVERFLOW, encoder.encode(headers, ByteBuffer.allocate(0)));

        ByteBuffer target = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers, target));
        assertArrayEquals(LITERAL_X_FOO_BAR, bytesOf(target), () -> "resumed encoding was " + hexOf(target));
    }

    @Test
    public void overflowIsDrainedIncrementallyAcrossCalls() {
        HeaderMap headers = headers("x-multi", "a");
        headers.add(new HttpString("x-multi"), "bb");
        headers.add(new HttpString("x-multi"), "ccc");

        HpackEncoder reference = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        ByteBuffer referenceTarget = ByteBuffer.allocate(256);
        assertEquals(HpackEncoder.State.COMPLETE, reference.encode(headers, referenceTarget));

        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        ByteBuffer collected = ByteBuffer.allocate(256);
        HpackEncoder.State state;
        int calls = 0;
        do {
            ByteBuffer chunk = ByteBuffer.allocate(5);
            state = encoder.encode(headers, chunk);
            collected.put(readView(chunk));
            assertTrue(++calls < 100, "encoding did not complete");
        } while (state == HpackEncoder.State.OVERFLOW);

        assertArrayEquals(bytesOf(referenceTarget), bytesOf(collected),
                () -> "split encoding was " + hexOf(collected));
    }

    @Test
    public void overflowWithMultipleValuesResumesWithinTheSameHeader() {
        HeaderMap headers = headers("x-multi", "a");
        headers.add(new HttpString("x-multi"), "bb");
        headers.add(new HttpString("x-multi"), "ccc");

        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        ByteBuffer firstTarget = ByteBuffer.allocate(5);
        assertEquals(HpackEncoder.State.OVERFLOW, encoder.encode(headers, firstTarget));
        assertEquals(0, firstTarget.position());

        ByteBuffer secondTarget = ByteBuffer.allocate(256);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers, secondTarget));
        assertArrayEquals(bytes(
                0x40, 0x07, 'x', '-', 'm', 'u', 'l', 't', 'i', 0x01, 'a',
                0x40, 0x07, 'x', '-', 'm', 'u', 'l', 't', 'i', 0x02, 'b', 'b',
                0x40, 0x07, 'x', '-', 'm', 'u', 'l', 't', 'i', 0x03, 'c', 'c', 'c'),
                bytesOf(secondTarget), () -> "resumed encoding was " + hexOf(secondTarget));
    }

    @Test
    public void pendingOverflowRejectsADifferentHeaderMap() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        HeaderMap headers = headers("x-foo", "bar");

        assertEquals(HpackEncoder.State.OVERFLOW, encoder.encode(headers, ByteBuffer.allocate(0)));

        assertThrows(IllegalStateException.class, () -> encoder.encode(new HeaderMap(), ByteBuffer.allocate(128)));
    }

    @Test
    public void staticNameWithoutStaticValueUsesTheNameIndexAndALiteralValue() {
        // :authority has no value in the static table, 0x40 | 1 keeps the name index
        assertEncoded(bytes(0x41, 0x03, 'a', 'b', 'c'), headers(":authority", "abc"));
    }

    @Test
    public void duplicateStaticMatchesAreEachEncodedAsAnIndex() {
        HeaderMap headers = headers(":method", "GET");
        headers.add(new HttpString(":method"), "GET");

        assertEncoded(bytes(0x82, 0x82), headers);
    }

    private static void assertEncoded(byte[] expected, HeaderMap headers) {
        assertEncoded(new HpackEncoder(DEFAULT_MAX_TABLE_SIZE), expected, headers);
    }

    private static void assertEncoded(HpackEncoder encoder, byte[] expected, HeaderMap headers) {
        ByteBuffer target = ByteBuffer.allocate(256);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers, target));
        assertArrayEquals(expected, bytesOf(target), () -> "encoding was " + hexOf(target));
    }

    private static HeaderMap headers(String name, String value) {
        HeaderMap headers = new HeaderMap();
        headers.put(new HttpString(name), value);
        return headers;
    }

    private static HpackEncoder.HpackHeaderFunction function(final boolean index, final boolean huffman) {
        return new HpackEncoder.HpackHeaderFunction() {
            @Override
            public boolean shouldUseIndexing(HttpString header, String value) {
                return index;
            }

            @Override
            public boolean shouldUseHuffman(HttpString header, String value) {
                return huffman;
            }

            @Override
            public boolean shouldUseHuffman(HttpString header) {
                return huffman;
            }
        };
    }

    private static byte[] bytes(int... values) {
        byte[] result = new byte[values.length];
        for (int i = 0; i < values.length; i++) {
            result[i] = (byte) values[i];
        }
        return result;
    }

    private static byte[] bytesOf(ByteBuffer target) {
        byte[] result = new byte[target.position()];
        for (int i = 0; i < result.length; i++) {
            result[i] = target.get(i);
        }
        return result;
    }

    private static ByteBuffer readView(ByteBuffer target) {
        ByteBuffer view = target.duplicate();
        view.flip();
        return view;
    }

    private static String hexOf(ByteBuffer target) {
        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < target.position(); i++) {
            builder.append(String.format("%02x ", target.get(i) & 0xff));
        }
        return builder.toString();
    }

    private static String readString(ByteBuffer source) throws HpackException {
        int lengthOctet = source.get(source.position()) & 0xff;
        boolean huffman = (lengthOctet & 0x80) != 0;
        int length = Hpack.decodeInteger(source, 7);
        StringBuilder result = new StringBuilder();
        if (huffman) {
            HPackHuffman.decode(source, length, result);
        } else {
            for (int i = 0; i < length; i++) {
                result.append((char) (source.get() & 0xff));
            }
        }
        return result.toString();
    }
}

