        }
    }

    private TestHttp2Channel newChannel(int padding) throws Exception {
        ChannelPipe<StreamConnection, StreamConnection> pipe = worker.createFullDuplexPipeConnection();
        openConnections.add(pipe.getLeftSide());
        openConnections.add(pipe.getRightSide());
        return new TestHttp2Channel(pipe.getLeftSide(), padding);
