    private static void attachSession(final HttpServerExchange exchange, final Session session) {
        final SessionManager sessionManager = (SessionManager) Proxy.newProxyInstance(
                SessionManager.class.getClassLoader(), new Class<?>[]{SessionManager.class},
                (proxy, method, args) -> {
                    if (method.getName().equals("getSession")
                            && args != null && args.length == 2 && args[0] instanceof HttpServerExchange) {
                        return session;
                    }
                    return defaultValue(method.getReturnType());
                });
        final SessionConfig sessionConfig = (SessionConfig) Proxy.newProxyInstance(
                SessionConfig.class.getClassLoader(), new Class<?>[]{SessionConfig.class},
                (proxy, method, args) -> defaultValue(method.getReturnType()));
        exchange.putAttachment(SessionManager.ATTACHMENT_KEY, sessionManager);
        exchange.putAttachment(SessionConfig.ATTACHMENT_KEY, sessionConfig);
    }

    private static ConduitStreamSourceChannel emptySourceChannel() {
        final StreamSourceConduit conduit = (StreamSourceConduit) Proxy.newProxyInstance(
                StreamSourceConduit.class.getClassLoader(), new Class<?>[]{StreamSourceConduit.class},
                (proxy, method, args) -> {
                    if (method.getName().equals("read")) {
                        return method.getReturnType() == long.class ? -1L : -1;
                    }
                    if (method.getName().equals("transferTo")) {
                        return -1L;
                    }
                    return defaultValue(method.getReturnType());
                });
        return new ConduitStreamSourceChannel(Configurable.EMPTY, conduit);
    }

    private static Object defaultValue(final Class<?> type) {
        if (!type.isPrimitive() || type == void.class) {
            return null;
        }
        if (type == boolean.class) {
            return false;
        }
        if (type == char.class) {
            return (char) 0;
        }
        if (type == byte.class) {
            return (byte) 0;
        }
        if (type == short.class) {
            return (short) 0;
        }
        if (type == int.class) {
            return 0;
        }
        if (type == long.class) {
            return 0L;
        }
        if (type == float.class) {
            return 0F;
        }
        if (type == double.class) {
            return 0D;
        }
        return null;
    }

