    private static final class RecordingSecurityContext implements InvocationHandler {
        private IdentityManager identityManager;
        private int identityManagerLookups;
        private Account completedAccount;
        private String completedMechanismName;
        private Boolean cachingRequired;
        private String failedMessage;
        private String failedMechanismName;
        private RuntimeException authenticationCompleteFailure;
        private RuntimeException authenticationFailedFailure;

        private SecurityContext proxy() {
            return (SecurityContext) Proxy.newProxyInstance(
                    SecurityContext.class.getClassLoader(), new Class<?>[]{SecurityContext.class}, this);
        }

        @Override
        public Object invoke(final Object proxy, final Method method, final Object[] args) throws Throwable {
            final String methodName = method.getName();
            if (methodName.equals("getIdentityManager")) {
                identityManagerLookups++;
                return identityManager;
            }
            if (methodName.equals("authenticationComplete")) {
                completedAccount = (Account) args[0];
                completedMechanismName = (String) args[1];
                cachingRequired = (Boolean) args[2];
                if (authenticationCompleteFailure != null) {
                    throw authenticationCompleteFailure;
                }
                return null;
            }
            if (methodName.equals("authenticationFailed")) {
                failedMessage = (String) args[0];
                failedMechanismName = (String) args[1];
                if (authenticationFailedFailure != null) {
                    throw authenticationFailedFailure;
                }
                return null;
            }
            if (methodName.equals("toString")) {
                return "RecordingSecurityContext";
            }
            if (methodName.equals("hashCode")) {
                return System.identityHashCode(proxy);
            }
            if (methodName.equals("equals")) {
                return proxy == args[0];
            }
            return defaultValue(method.getReturnType());
        }
    }

    private static final class RecordingSession implements InvocationHandler {
        private final Map<String, Object> attributes = new HashMap<>();
        private int maxInactiveInterval;
        private int maxInactiveIntervalSetCalls;

        private Session proxy() {
            return (Session) Proxy.newProxyInstance(
                    Session.class.getClassLoader(), new Class<?>[]{Session.class}, this);
        }

        @Override
        public Object invoke(final Object proxy, final Method method, final Object[] args) {
            final String methodName = method.getName();
            if (methodName.equals("removeAttribute")) {
                return attributes.remove((String) args[0]);
            }
            if (methodName.equals("getAttribute")) {
                return attributes.get((String) args[0]);
            }
            if (methodName.equals("setAttribute")) {
                return attributes.put((String) args[0], args[1]);
            }
            if (methodName.equals("getAttributeNames")) {
                return new HashSet<>(attributes.keySet());
            }
            if (methodName.equals("setMaxInactiveInterval")) {
                maxInactiveIntervalSetCalls++;
                maxInactiveInterval = (Integer) args[0];
                return null;
            }
            if (methodName.equals("getMaxInactiveInterval")) {
                return maxInactiveInterval;
            }
            if (methodName.equals("getId")) {
                return "test-session";
            }
            if (methodName.equals("isInvalid")) {
                return false;
            }
            if (methodName.equals("toString")) {
                return "RecordingSession";
            }
            if (methodName.equals("hashCode")) {
                return System.identityHashCode(proxy);
            }
            if (methodName.equals("equals")) {
                return proxy == args[0];
            }
            return defaultValue(method.getReturnType());
        }
    }

