import java.nio.channels.FileChannel;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Executor;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Unit tests for {@link Connectors#executeRootHandler(HttpHandler, HttpServerExchange)}.
 */
class ConnectorsExecuteRootHandlerTests {

    private TestServerConnection connection;
    private RecordingSinkConduit sinkConduit;
    private RecordingSourceConduit sourceConduit;
    private HttpServerExchange exchange;
    private int endExchangeInvocations;

    @BeforeEach
    void setUp() {
        connection = new TestServerConnection();
        sinkConduit = new RecordingSinkConduit();
        connection.sinkChannel = new ConduitStreamSinkChannel(Configurable.EMPTY, sinkConduit);
        sourceConduit = new RecordingSourceConduit();
        connection.sourceChannel = new ConduitStreamSourceChannel(Configurable.EMPTY, sourceConduit);
        exchange = new HttpServerExchange(connection);
        endExchangeInvocations = 0;
        // A default response listener that claims the response and records that endExchange() was
        // reached. This makes the endExchange() invocations observable without requiring a fully
        // functional connection.
        exchange.addDefaultResponseListener(new DefaultResponseListener() {
            @Override
            public boolean handleDefaultResponse(HttpServerExchange exchange) {
                endExchangeInvocations++;
                return true;
            }
        });
    }

    @Test
    void handlerIsInvokedWithInCallFlagAndExchangeIsEnded() {
        final AtomicBoolean inCallInsideHandler = new AtomicBoolean(false);
        final AtomicReference<HttpServerExchange> passedExchange = new AtomicReference<>();

        Connectors.executeRootHandler(new HttpHandler() {
            @Override
            public void handleRequest(HttpServerExchange ex) {
                inCallInsideHandler.set(ex.isInCall());
                passedExchange.set(ex);
            }
        }, exchange);

        assertSame(exchange, passedExchange.get(), "the handler must receive the given exchange");
        assertTrue(inCallInsideHandler.get(), "the exchange must be marked in-call while the handler runs");
        assertFalse(exchange.isInCall(), "the exchange must no longer be in-call after executeRootHandler returns");
        assertEquals(1, endExchangeInvocations, "the exchange must be ended when the handler neither dispatched nor resumed");
        assertFalse(exchange.isDispatched());
        assertFalse(exchange.isResumed());
        assertEquals(StatusCodes.OK, exchange.getStatusCode(), "no status code must be set for a successful request");
        assertNull(exchange.getAttachment(DefaultResponseListener.EXCEPTION));
    }

    @Test
    void resumedExchangeResumesWritesInsteadOfEnding() {
        Connectors.executeRootHandler(new HttpHandler() {
            @Override
            public void handleRequest(HttpServerExchange ex) {
                ex.getResponseChannel().resumeWrites();
            }
        }, exchange);

        assertEquals(0, endExchangeInvocations, "a resumed exchange must not be ended");
        assertEquals(1, sinkConduit.resumeWritesCount, "the deferred write resume must be run");
        assertEquals(0, sinkConduit.wakeupWritesCount);
        assertFalse(exchange.isInCall());
        assertFalse(exchange.isDispatched());
    }

    @Test
    void resumedReadsAreWokenUpInsteadOfEndingTheExchange() {
        Connectors.executeRootHandler(new HttpHandler() {
            @Override
            public void handleRequest(HttpServerExchange ex) {
                ex.getRequestChannel().resumeReads();
            }
        }, exchange);

        assertEquals(0, endExchangeInvocations, "a resumed exchange must not be ended");
        assertEquals(1, sourceConduit.wakeupReadsCount, "the deferred read resume must be run");
        assertEquals(0, sourceConduit.resumeReadsCount);
        assertFalse(exchange.isInCall());
        assertFalse(exchange.isDispatched());
    }

    @Test
    void dispatchedTaskIsSubmittedToTheDispatchExecutor() {
        final List<Runnable> submitted = new ArrayList<>();
        final Executor executor = new Executor() {
            @Override
            public void execute(Runnable command) {
                submitted.add(command);
            }
        };
        final AtomicInteger taskRuns = new AtomicInteger();
        final AtomicReference<Runnable> dispatchedTask = new AtomicReference<>();

        Connectors.executeRootHandler(new HttpHandler() {
            @Override
            public void handleRequest(HttpServerExchange ex) {
                Runnable task = new Runnable() {
                    @Override
                    public void run() {
                        taskRuns.incrementAndGet();
                    }
                };
                dispatchedTask.set(task);
                ex.dispatch(executor, task);
            }
        }, exchange);

        assertEquals(1, submitted.size(), "the dispatch task must be handed to the dispatch executor");
        assertSame(dispatchedTask.get(), submitted.get(0), "the exact dispatch task must be submitted");
        assertEquals(0, taskRuns.get(), "the executor used by this test only records the task");
        assertFalse(exchange.isDispatched(), "the exchange must be un-dispatched before the task is submitted");
        assertNull(exchange.getDispatchExecutor(), "the dispatch executor must be cleared");
        assertNull(exchange.getDispatchTask());
        assertEquals(0, endExchangeInvocations, "a dispatched exchange must not be ended by executeRootHandler");
        assertFalse(exchange.isInCall());
    }

    @Test
    void dispatchedTaskWithoutExecutorIsSubmittedToTheConnectionWorker() {
        final XnioWorker worker = EasyMock.createMock(XnioWorker.class);
        final Runnable task = new Runnable() {
            @Override
            public void run() {
            }
        };
        worker.execute(task);
        EasyMock.expectLastCall().times(1);
        EasyMock.replay(worker);
        connection.worker = worker;

        try {
            Connectors.executeRootHandler(new HttpHandler() {
                @Override
                public void handleRequest(HttpServerExchange ex) {
                    ex.dispatch(task);
                }
            }, exchange);

            EasyMock.verify(worker);
        } finally {
            EasyMock.reset(worker);
        }

        assertFalse(exchange.isDispatched());
        assertNull(exchange.getDispatchTask());
        assertEquals(1, connection.workerRequests, "the connection worker must be consulted once");
        assertEquals(0, endExchangeInvocations);
    }

    @Test
    void rejectedDispatchEndsExchangeWithServiceUnavailable() {
        final Executor executor = new Executor() {
            @Override
            public void execute(Runnable command) {
                throw new RejectedExecutionException("rejected for test");
            }
        };
        final AtomicBoolean taskRan = new AtomicBoolean(false);

        Connectors.executeRootHandler(new HttpHandler() {
            @Override
            public void handleRequest(HttpServerExchange ex) {
                ex.dispatch(executor, new Runnable() {
                    @Override
                    public void run() {
                        taskRan.set(true);
                    }
                });
            }
        }, exchange);

        assertFalse(taskRan.get());
        assertEquals(StatusCodes.SERVICE_UNAVAILABLE, exchange.getStatusCode(),
                "a rejected dispatch must result in 503 Service Unavailable");
        assertEquals(1, endExchangeInvocations, "the exchange must be ended after a rejected dispatch");
        assertNull(exchange.getAttachment(DefaultResponseListener.EXCEPTION),
                "a rejected dispatch is handled, no exception must be recorded");
        assertFalse(exchange.isDispatched());
        assertFalse(exchange.isInCall());
    }

    @Test
    void dispatchWithoutRunnableDoesNotSubmitAnyTask() {
        Connectors.executeRootHandler(new HttpHandler() {
            @Override
            @SuppressWarnings("deprecation")
            public void handleRequest(HttpServerExchange ex) {
                ex.dispatch();
            }
        }, exchange);

        assertFalse(exchange.isDispatched(), "the exchange must be un-dispatched");
        assertNull(exchange.getDispatchTask());
        assertEquals(0, connection.workerRequests, "no worker must be used when there is no dispatch task");
        assertEquals(0, endExchangeInvocations, "a dispatched exchange must not be ended by executeRootHandler");
        assertFalse(exchange.isInCall());
    }

    @Test
    void resumedAndDispatchedExchangeEndsWithServerError() {
        Connectors.executeRootHandler(new HttpHandler() {
            @Override
            @SuppressWarnings("deprecation")
            public void handleRequest(HttpServerExchange ex) {
                ex.getRequestChannel().resumeReads();
                ex.dispatch();
            }
        }, exchange);

        assertEquals(StatusCodes.INTERNAL_SERVER_ERROR, exchange.getStatusCode(),
                "resumed and dispatched exchanges are an illegal state, 500 must be returned");
        assertEquals(1, endExchangeInvocations, "the exchange must be ended when it is both resumed and dispatched");
        assertEquals(0, sourceConduit.wakeupReadsCount, "the resumed reads must not be run when also dispatched");
        assertEquals(0, sourceConduit.resumeReadsCount);
        assertFalse(exchange.isInCall());
    }

    @Test
    void handlerRuntimeExceptionResultsInInternalServerError() {
        final RuntimeException boom = new RuntimeException("boom");

        Connectors.executeRootHandler(new HttpHandler() {
            @Override
            public void handleRequest(HttpServerExchange ex) {
                throw boom;
            }
        }, exchange);

        assertSame(boom, exchange.getAttachment(DefaultResponseListener.EXCEPTION),
                "the thrown exception must be attached to the exchange");
        assertEquals(StatusCodes.INTERNAL_SERVER_ERROR, exchange.getStatusCode());
        assertFalse(exchange.isInCall(), "the in-call flag must be cleared when an exception is thrown");
        assertEquals(1, endExchangeInvocations, "the exchange must be ended after an exception");
    }

    @Test
    void requestTooBigExceptionResultsInRequestEntityTooLarge() {
        final RequestTooBigException tooBig = new RequestTooBigException("too big");

        Connectors.executeRootHandler(new HttpHandler() {
            @Override
            public void handleRequest(HttpServerExchange ex) throws Exception {
                throw tooBig;
            }
        }, exchange);

        assertSame(tooBig, exchange.getAttachment(DefaultResponseListener.EXCEPTION));
        assertEquals(StatusCodes.REQUEST_ENTITY_TOO_LARGE, exchange.getStatusCode(),
                "a RequestTooBigException must result in 413 Request Entity Too Large");
        assertFalse(exchange.isInCall());
        assertEquals(1, endExchangeInvocations);
    }

    @Test
    void ioExceptionResultsInInternalServerError() {
        final IOException ioException = new IOException("connection reset");

        Connectors.executeRootHandler(new HttpHandler() {
            @Override
            public void handleRequest(HttpServerExchange ex) throws Exception {
                throw ioException;
            }
        }, exchange);

        assertSame(ioException, exchange.getAttachment(DefaultResponseListener.EXCEPTION));
        assertEquals(StatusCodes.INTERNAL_SERVER_ERROR, exchange.getStatusCode());
        assertFalse(exchange.isInCall());
        assertEquals(1, endExchangeInvocations);
    }

    @Test
    void handlerErrorResultsInInternalServerError() {
        final Error error = new Error("fatal");

        Connectors.executeRootHandler(new HttpHandler() {
            @Override
            public void handleRequest(HttpServerExchange ex) {
                throw error;
            }
        }, exchange);

        assertSame(error, exchange.getAttachment(DefaultResponseListener.EXCEPTION));
        assertEquals(StatusCodes.INTERNAL_SERVER_ERROR, exchange.getStatusCode());
        assertFalse(exchange.isInCall());
        assertEquals(1, endExchangeInvocations);
    }

    @Test
    void statusCodeSetByHandlerIsReplacedOnException() {
        Connectors.executeRootHandler(new HttpHandler() {
            @Override
            public void handleRequest(HttpServerExchange ex) {
                ex.setStatusCode(StatusCodes.ACCEPTED);
                throw new IllegalStateException("after status");
            }
        }, exchange);

        assertEquals(StatusCodes.INTERNAL_SERVER_ERROR, exchange.getStatusCode());
        assertNotNull(exchange.getAttachment(DefaultResponseListener.EXCEPTION));
    }

    @Test
    void exceptionAfterResponseStartedDoesNotChangeStatusCode() {
        Connectors.executeRootHandler(new HttpHandler() {
            @Override
            public void handleRequest(HttpServerExchange ex) {
                ex.getResponseChannel();
                throw new IllegalStateException("too late");
            }
        }, exchange);

        assertTrue(exchange.isResponseStarted(), "the response must have been started by the handler");
        assertEquals(StatusCodes.OK, exchange.getStatusCode(),
                "the status code must not be changed once the response was started");
        assertNotNull(exchange.getAttachment(DefaultResponseListener.EXCEPTION));
        assertFalse(exchange.isInCall());
        assertEquals(1, endExchangeInvocations);
    }

