@Tag("io.undertow.testutils.category.UnitTest")
class ConnectorsSetExchangeRequestPathTests {

    private static final int DEFAULT_MAX_PARAMETERS = 1000;

    @Test
    void plainPathIsStoredAsRequestPathRelativePathAndUri() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/foo/bar", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/foo/bar", exchange.getRequestPath());
        assertEquals("/foo/bar", exchange.getRelativePath());
        assertEquals("/foo/bar", exchange.getRequestURI());
        assertEquals("", exchange.getQueryString());
        assertEquals("", exchange.getDecodedQueryString());
        assertTrue(exchange.getQueryParameters().isEmpty());
        assertTrue(exchange.getPathParameters().isEmpty());
    }

    @Test
    void percentEncodedPathIsDecodedButRequestUriRemainsEncoded() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/a%20b/%2Fc%2Bd", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/a b/%2Fc+d", exchange.getRequestPath());
        assertEquals("/a b/%2Fc+d", exchange.getRelativePath());
        assertEquals("/a%20b/%2Fc%2Bd", exchange.getRequestURI());
    }

    @Test
    void encodedSlashIsDecodedOnlyWhenSlashDecodingIsEnabled() throws Exception {
        HttpServerExchange withoutSlashDecoding = exchangeWith(OptionMap.EMPTY);
        setPath(withoutSlashDecoding, "/a%2Fb", true, true, false, DEFAULT_MAX_PARAMETERS);
        assertEquals("/a%2Fb", withoutSlashDecoding.getRequestPath());

        HttpServerExchange withSlashDecoding = exchangeWith(OptionMap.EMPTY);
        setPath(withSlashDecoding, "/a%2Fb", true, true, true, DEFAULT_MAX_PARAMETERS);
        assertEquals("/a/b", withSlashDecoding.getRequestPath());
    }

    @Test
    void plusInPathIsKeptBecauseItIsNotFormEncoded() throws Exception {
        HttpServerExchange exchange = exchangeWith(OptionMap.EMPTY);

        setPath(exchange, "/a+b", true, true, false, DEFAULT_MAX_PARAMETERS);

        assertEquals("/a+b", exchange.getRequestPath());
        assertEquals("/a+b", exchange.getRequestURI());
    }

    @Test
