                .getMap();
    }

    private static void setPath(HttpServerExchange exchange, String encodedPath, boolean decode,
                                boolean decodeQueryString, boolean decodeSlash, int maxParameters)
            throws ParameterLimitException, BadRequestException {
        Connectors.setExchangeRequestPath(exchange, encodedPath, StandardCharsets.UTF_8.name(),
                decode, decodeQueryString, decodeSlash, new StringBuilder(), maxParameters);
    }

    private static void assertParam(Map<String, Deque<String>> parameters, String name, String... expected) {
        Deque<String> values = parameters.get(name);
        assertTrue(values != null, "Missing parameter: " + name);
        assertEquals(Arrays.asList(expected), Arrays.asList(values.toArray(new String[0])));
    }
