        cookie.setAttribute(COOKIE_SECURE_ATTR, "true", true);
        cookie.setAttribute(COOKIE_DISCARD_ATTR, "true", true);
        cookie.setAttribute(COOKIE_EXPIRES_ATTR, "Wed, 21 Oct 2015 07:28:00 GMT", true);

