                () -> cookie.setAttribute(COOKIE_HTTP_ONLY_ATTR, null, true),
                () -> cookie.setAttribute(COOKIE_MAX_AGE_ATTR, null, true),
                () -> cookie.setAttribute(COOKIE_PATH_ATTR, null, true),
                () -> cookie.setAttribute(COOKIE_SAME_SITE_ATTR, null, true),
                () -> cookie.setAttribute(COOKIE_SECURE_ATTR, null, true),
                () -> cookie.setAttribute(COOKIE_DISCARD_ATTR, null, true),
                () -> cookie.setAttribute(COOKIE_EXPIRES_ATTR, null, true)
        );

        assertAll(
