                () -> assertNull(cookie.getAttribute(COOKIE_DOMAIN_ATTR)),
                () -> assertNull(cookie.getAttribute(COOKIE_HTTP_ONLY_ATTR)),
                () -> assertNull(cookie.getAttribute(COOKIE_MAX_AGE_ATTR)),
                () -> assertNull(cookie.getAttribute(COOKIE_PATH_ATTR)),
                () -> assertNull(cookie.getAttribute(COOKIE_SAME_SITE_ATTR)),
                () -> assertNull(cookie.getAttribute(COOKIE_SECURE_ATTR)),
                () -> assertNull(cookie.getAttribute(COOKIE_DISCARD_ATTR)),
                () -> assertNull(cookie.getAttribute(COOKIE_EXPIRES_ATTR))
        );
        assertTrue(cookie.getAttributes().isEmpty());
