        cookie.setAttribute(COOKIE_PATH_ATTR, "/p", true);
        cookie.setAttribute(COOKIE_MAX_AGE_ATTR, "10", true);
        cookie.setAttribute(COOKIE_SECURE_ATTR, "true", true);

        cookie.setAttribute(COOKIE_PATH_ATTR, null, false);
        cookie.setAttribute(COOKIE_MAX_AGE_ATTR, null, false);
        cookie.setAttribute(COOKIE_SECURE_ATTR, null, false);

        assertNull(cookie.getPath());
        assertEquals(Integer.valueOf(-1), cookie.getMaxAge());
        assertFalse(cookie.isSecure());
        assertNull(cookie.getAttribute(COOKIE_PATH_ATTR));
        assertNull(cookie.getAttribute(COOKIE_MAX_AGE_ATTR));
        assertNull(cookie.getAttribute(COOKIE_SECURE_ATTR));
    }

    @Test
    void unknownAttributeOnlyAffectsAttributeMap() {
        CookieImpl cookie = cookie();
        cookie.setAttribute(COOKIE_PATH_ATTR, "/p", true);
        cookie.setAttribute(COOKIE_MAX_AGE_ATTR, "10", true);

        cookie.setAttribute("Custom-Header", "custom-value", true);

        assertEquals("custom-value", cookie.getAttribute("Custom-Header"));
        assertEquals("custom-value", cookie.getAttributes().get("Custom-Header"));
        assertEquals("/p", cookie.getPath());
        assertEquals(Integer.valueOf(10), cookie.getMaxAge());
        assertEquals(2 + 1, cookie.getAttributes().size());
    }

    @Test
    void unknownAttributeWithNullValueRemovesItWithoutChangingTypedFields() {
        CookieImpl cookie = cookie();
        cookie.setAttribute("Custom-Header", "custom-value", true);
        cookie.setAttribute(COOKIE_PATH_ATTR, "/p", true);

        cookie.setAttribute("Custom-Header", null, true);

        assertNull(cookie.getAttribute("Custom-Header"));
        assertFalse(cookie.getAttributes().containsKey("Custom-Header"));
        assertEquals("/p", cookie.getPath());
        assertEquals("/p", cookie.getAttribute(COOKIE_PATH_ATTR));
    }

    @Test
    void attributeNameMatchingIsCaseSensitiveForFieldSync() {
        CookieImpl cookie = cookie();

        cookie.setAttribute("path", "/lower-case", true);

        // The switch uses exact constant names, so the typed field is not synchronized.
        assertNull(cookie.getPath());
        // The attribute map itself is case-insensitive when queried through getAttribute.
        assertEquals("/lower-case", cookie.getAttribute("path"));
        assertEquals("/lower-case", cookie.getAttribute("PATH"));
        assertEquals("/lower-case", cookie.getAttributes().get("path"));
    }

    @Test
    void settingThenRemovingOneAttributeLeavesOtherAttributesIntact() {
        CookieImpl cookie = cookie();
        cookie.setAttribute(COOKIE_DOMAIN_ATTR, "example.com", true);
        cookie.setAttribute(COOKIE_PATH_ATTR, "/p", true);

        cookie.setAttribute(COOKIE_DOMAIN_ATTR, null, true);

        assertNull(cookie.getDomain());
        assertNull(cookie.getAttribute(COOKIE_DOMAIN_ATTR));
        assertEquals("/p", cookie.getPath());
        assertEquals("/p", cookie.getAttribute(COOKIE_PATH_ATTR));
        Map<String, String> attributes = cookie.getAttributes();
        assertEquals(1, attributes.size());
        assertEquals("/p", attributes.get(COOKIE_PATH_ATTR));
    }

    @Test
    void nullNameThrowsNullPointerException() {
        assertAll(
                () -> assertThrows(NullPointerException.class,
                        () -> cookie().setAttribute(null, "value", true)),
                () -> assertThrows(NullPointerException.class,
                        () -> cookie().setAttribute(null, "value", false)),
                () -> assertThrows(NullPointerException.class,
                        () -> cookie().setAttribute(null, null, true))
        );
    }

    @Test
    void repeatedNonNullSetOverwritesPreviousValueAndAttribute() {
        CookieImpl cookie = cookie();

        cookie.setAttribute(COOKIE_PATH_ATTR, "/first", true);
        cookie.setAttribute(COOKIE_PATH_ATTR, "/second", true);

        assertEquals("/second", cookie.getPath());
        assertEquals("/second", cookie.getAttribute(COOKIE_PATH_ATTR));
        assertEquals(1, cookie.getAttributes().size());
    }
