    private static MCMPHandler.RequestData requestData(String contextPath, String jvmRoute, String aliases) {
        MCMPHandler.RequestData data = new MCMPHandler.RequestData();
        if (contextPath != null) {
            add(data, CONTEXT, contextPath);
        }
        if (jvmRoute != null) {
            add(data, JVMROUTE, jvmRoute);
        }
        if (aliases != null) {
            add(data, ALIAS, aliases);
        }
        return data;
    }

    private static void add(MCMPHandler.RequestData data, HttpString name, String value) {
        Deque<String> values = new ArrayDeque<>();
        values.add(value);
        data.addValues(name, values);
    }

    private static ExchangeResult newExchange() throws Exception {
        CapturingSender sender = new CapturingSender();
        HttpServerExchange exchange = new HttpServerExchange(null);
        exchange.setSourceAddress(new InetSocketAddress("127.0.0.1", 12345));
        exchange.startBlocking(new CapturingBlockingHttpExchange(sender));

        Field state = HttpServerExchange.class.getDeclaredField("state");
        state.setAccessible(true);
        state.setInt(exchange, state.getInt(exchange) | FLAG_REQUEST_TERMINATED | FLAG_RESPONSE_TERMINATED);
        return new ExchangeResult(exchange, sender);
    }

    private static void assertOk(ExchangeResult result) {
        assertEquals(StatusCodes.OK, result.exchange.getStatusCode());
        assertEquals(CONTENT_TYPE, result.exchange.getResponseHeaders().getFirst(Headers.CONTENT_TYPE));
        assertNull(result.exchange.getResponseHeaders().getFirst(VERSION_HEADER));
        assertNull(result.exchange.getResponseHeaders().getFirst(TYPE_HEADER));
        assertNull(result.exchange.getResponseHeaders().getFirst(MESSAGE_HEADER));
        assertTrue(result.sender.getBody().isEmpty());
    }

    private static void assertError(ExchangeResult result, String type, String message) {
        assertEquals(StatusCodes.INTERNAL_SERVER_ERROR, result.exchange.getStatusCode());
        assertEquals(CONTENT_TYPE, result.exchange.getResponseHeaders().getFirst(Headers.CONTENT_TYPE));
        assertEquals("0.2.1", result.exchange.getResponseHeaders().getFirst(VERSION_HEADER));
        assertEquals(type, result.exchange.getResponseHeaders().getFirst(TYPE_HEADER));
        assertEquals(message, result.exchange.getResponseHeaders().getFirst(MESSAGE_HEADER));
        assertTrue(result.sender.getBody().isEmpty());
    }

    private static final class ExchangeResult {
        private final HttpServerExchange exchange;
        private final CapturingSender sender;

        private ExchangeResult(HttpServerExchange exchange, CapturingSender sender) {
            this.exchange = exchange;
            this.sender = sender;
        }
    }

