    private static TestNode node(ModCluster cluster, ModClusterContainer container, String route, String domain,
                                 boolean available, boolean inError, boolean hotStandby, int loadStatus) throws Exception {
        NodeConfig config = NodeConfig.builder(cluster)
                .setJvmRoute(route)
                .setBalancer("test-balancer")
                .setHostname("127.0.0.1")
                .setPort(8080)
                .setDomain(domain)
                .build();
        return new TestNode(container, config, available, inError, hotStandby, loadStatus);
    }

    private static Context enabledContext(TestNode node) {
        Context context = new Context("/", null, node);
        context.enable();
        return context;
    }

    private static VirtualHost.HostEntry entry(Context... contexts) {
        VirtualHost virtualHost = new VirtualHost();
        for (Context context : contexts) {
            virtualHost.registerContext("/", context.getJVMRoute(), context);
        }
        return virtualHost.match("/").getValue();
    }

    @SuppressWarnings("unchecked")
    private static void addNode(ModClusterContainer container, Node node) throws Exception {
        Field nodesField = ModClusterContainer.class.getDeclaredField("nodes");
        nodesField.setAccessible(true);
        ((Map<String, Node>) nodesField.get(container)).put(node.getJvmRoute(), node);
    }

    @SuppressWarnings("unchecked")
    private static void cacheFailoverDomain(ModClusterContainer container, String jvmRoute, String domain) throws Exception {
        Field failoverDomainsField = ModClusterContainer.class.getDeclaredField("failoverDomains");
        failoverDomainsField.setAccessible(true);
        ((LRUCache<String, String>) failoverDomainsField.get(container)).add(jvmRoute, domain);
    }

    private static final class TestNode extends Node {

        private final boolean available;
        private final boolean inError;
        private final boolean hotStandby;
