    private static CachingResourceManager manager(DirectBufferCache dataCache, StubRangeAwareResource underlying) {
        return manager(dataCache, underlying, MAX_FILE_SIZE);
    }

    private static CachingResourceManager manager(DirectBufferCache dataCache, StubRangeAwareResource underlying,
                                                  long maxFileSize) {
        return new CachingResourceManager(16, maxFileSize, dataCache,
                new StubResourceManager(underlying), CachingResourceManager.MAX_AGE_NO_EXPIRY);
    }

    private static CachedResource.CacheKey cacheKey(CachingResourceManager manager) {
        return new CachedResource.CacheKey(manager, CACHE_KEY);
    }

    private static DirectBufferCache.CacheEntry cachedEntry(DirectBufferCache dataCache,
                                                            CachingResourceManager manager,
                                                            String content) {
        DirectBufferCache.CacheEntry entry = dataCache.add(cacheKey(manager), content.length(),
                DirectBufferCache.MAX_AGE_NO_EXPIRY);
        assertTrue(entry.allocate());
        fill(entry, content);
        entry.enable();
        assertTrue(entry.enabled());
        return entry;
    }

    private static void fill(DirectBufferCache.CacheEntry entry, String content) {
        int offset = 0;
        for (LimitedBufferSlicePool.PooledByteBuffer pooled : entry.buffers()) {
            ByteBuffer buffer = pooled.getBuffer();
            int amount = Math.min(buffer.remaining(), content.length() - offset);
            buffer.put(content.substring(offset, offset + amount).getBytes(StandardCharsets.US_ASCII));
            buffer.flip();
            offset += amount;
        }
        assertEquals(content.length(), offset);
    }

