import java.nio.ByteBuffer;

import io.undertow.util.BadRequestException;
import io.undertow.util.Headers;
import org.junit.jupiter.api.Test;

/**
 * Unit tests for {@link AjpRequestParser#parseString(ByteBuffer, AjpRequestParseState, AjpRequestParser.StringType)}.
 */
class AjpRequestParserParseStringTests {

    private static AjpRequestParser parser(boolean allowUnescapedCharactersInUrl) {
        return new AjpRequestParser("UTF-8", true, 10000, 100, false, allowUnescapedCharactersInUrl);
    }

    private static AjpRequestParser parser() {
        return parser(false);
    }

    /**
     * Builds a byte buffer from unsigned byte values.
     */
    private static ByteBuffer buffer(int... unsignedBytes) {
        byte[] bytes = new byte[unsignedBytes.length];
        for (int i = 0; i < unsignedBytes.length; i++) {
            bytes[i] = (byte) unsignedBytes[i];
        }
        return ByteBuffer.wrap(bytes);
    }

    private static void assertIncomplete(AjpRequestParser.StringHolder holder) {
        assertNull(holder.value, "an incomplete read must not produce a value");
        assertNull(holder.header, "an incomplete read must not produce a header");
        assertFalse(holder.readComplete, "an incomplete read must not be marked complete");
        assertFalse(holder.containsUrlCharacters, "an incomplete read must not report URL characters");
        assertFalse(holder.containsUnencodedCharacters, "an incomplete read must not report unencoded characters");
    }

    // ------------------------------------------------------------------
    // Empty buffer
    // ------------------------------------------------------------------

    @Test
    void emptyBufferReturnsIncompleteHolderAndLeavesStateUntouched() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();

        AjpRequestParser.StringHolder holder = parser().parseString(ByteBuffer.allocate(0), state, AjpRequestParser.StringType.OTHER);

        assertIncomplete(holder);
        assertEquals(-1, state.stringLength);
        assertEquals(0, state.getCurrentStringLength());
    }

    // ------------------------------------------------------------------
    // Length reading
    // ------------------------------------------------------------------

    @Test
    void singleByteLengthIsSavedWithMaskAndResolvedOnNextCall() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        AjpRequestParser parser = parser();

        AjpRequestParser.StringHolder first = parser.parseString(buffer(0x00), state, AjpRequestParser.StringType.OTHER);

        assertIncomplete(first);
        assertEquals(AjpRequestParser.STRING_LENGTH_MASK, state.stringLength,
                "the partially read length byte must be stored together with the mask flag");

        AjpRequestParser.StringHolder second = parser.parseString(buffer(0x03, 'a', 'b', 'c', 0x00), state, AjpRequestParser.StringType.OTHER);

        assertEquals("abc", second.value);
        assertTrue(second.readComplete);
        assertFalse(second.containsUrlCharacters);
        assertFalse(second.containsUnencodedCharacters);
        assertEquals(-1, state.stringLength);
        assertEquals(0, state.getCurrentStringLength(), "the collected bytes must be cleared");
    }

    @Test
    void maskedLengthInStateIsCompletedFromNextByte() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        state.stringLength = AjpRequestParser.STRING_LENGTH_MASK;

        AjpRequestParser.StringHolder holder = parser().parseString(buffer(0x02, 'h', 'i', 0x00), state, AjpRequestParser.StringType.OTHER);

        assertEquals("hi", holder.value);
        assertTrue(holder.readComplete);
        assertEquals(-1, state.stringLength);
    }

    @Test
    void twoByteLengthIsReadFromSingleBufferAndTerminatorConsumed() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        ByteBuffer buf = buffer(0x00, 0x05, 'h', 'e', 'l', 'l', 'o', 0x00);

        AjpRequestParser.StringHolder holder = parser().parseString(buf, state, AjpRequestParser.StringType.OTHER);

        assertEquals("hello", holder.value);
        assertTrue(holder.readComplete);
        assertFalse(holder.containsUrlCharacters);
        assertFalse(holder.containsUnencodedCharacters);
        assertNull(holder.header);
        assertEquals(-1, state.stringLength);
        assertEquals(0, state.getCurrentStringLength());
        assertEquals(buf.limit(), buf.position(), "the length, content and terminator must be consumed");
    }

    @Test
    void zeroLengthStringYieldsEmptyValue() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        ByteBuffer buf = buffer(0x00, 0x00, 0x00);

        AjpRequestParser.StringHolder holder = parser().parseString(buf, state, AjpRequestParser.StringType.OTHER);

        assertEquals("", holder.value);
        assertTrue(holder.readComplete);
        assertFalse(holder.containsUrlCharacters);
        assertFalse(holder.containsUnencodedCharacters);
        assertEquals(-1, state.stringLength);
        assertEquals(3, buf.position());
    }

    @Test
    void zeroLengthStringWithoutTerminatorIsIncomplete() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        AjpRequestParser parser = parser();

        AjpRequestParser.StringHolder first = parser.parseString(buffer(0x00, 0x00), state, AjpRequestParser.StringType.OTHER);

