    private Harness harness(final TestSourceConduit source, final TestSinkConduit sink, final OptionMap options,
            final ByteBufferPool pool, final List<HttpServerExchange> handled) {
        final TestStreamConnection streamConnection = new TestStreamConnection(ioThread, source, sink);
        final HttpHandler handler = new HttpHandler() {
            @Override
            public void handleRequest(final HttpServerExchange exchange) {
                handled.add(exchange);
                // keep the exchange "in progress" so that the listener is not reset by the exchange completion
                exchange.dispatch(NO_OP_EXECUTOR, new Runnable() {
                    @Override
                    public void run() {
                    }
                });
            }
        };
        final HttpServerConnection connection = new HttpServerConnection(streamConnection, pool, handler, options, 8192, null);
        final HttpReadListener listener = new HttpReadListener(connection, RequestParser.instance(options), null);
        connection.setReadListener(listener);
        Harness harness = new Harness(streamConnection, connection, listener);
        harnesses.add(harness);
        return harness;
    }

    private static byte[] bytes(final String value) {
        return value.getBytes(StandardCharsets.US_ASCII);
    }

    private static String remaining(final ByteBuffer buffer) {
        ByteBuffer copy = buffer.duplicate();
        byte[] data = new byte[copy.remaining()];
        copy.get(data);
        return new String(data, StandardCharsets.US_ASCII);
    }

    private static ParseTimeoutUpdater parseTimeoutUpdater(final HttpReadListener listener) throws Exception {
        Field field = HttpReadListener.class.getDeclaredField("parseTimeoutUpdater");
        field.setAccessible(true);
        return (ParseTimeoutUpdater) field.get(listener);
    }

    private static boolean isParsing(final ParseTimeoutUpdater updater) throws Exception {
        Field field = ParseTimeoutUpdater.class.getDeclaredField("parsing");
        field.setAccessible(true);
        return (Boolean) field.get(updater);
    }

    private static final class Harness {
        private final TestStreamConnection streamConnection;
        private final HttpServerConnection connection;
        private final HttpReadListener listener;

        private Harness(final TestStreamConnection streamConnection, final HttpServerConnection connection,
                final HttpReadListener listener) {
            this.streamConnection = streamConnection;
            this.connection = connection;
            this.listener = listener;
        }
    }

    /**
     * A {@link PooledByteBuffer} that records if it has been released.
     */
    private static final class TrackingPooledByteBuffer implements PooledByteBuffer {

        private final ByteBuffer buffer;
        private boolean closed;

        private TrackingPooledByteBuffer(final ByteBuffer buffer) {
            this.buffer = buffer;
        }

        private TrackingPooledByteBuffer(final byte[] data) {
            this(ByteBuffer.wrap(data));
        }

        @Override
        public ByteBuffer getBuffer() {
            return buffer;
        }

        @Override
        public void close() {
            closed = true;
        }

        @Override
        public boolean isOpen() {
            return !closed;
        }

        private boolean isClosed() {
            return closed;
        }
    }

    /**
     * A buffer pool that records allocations and can be configured to fail like a shutdown pool does.
     */
    private static final class TrackingByteBufferPool implements ByteBufferPool {

        private final int bufferSize;
        private final boolean failOnAllocate;
        private final List<TrackingPooledByteBuffer> allocated = new ArrayList<>();
        private int allocateCount;

        private TrackingByteBufferPool(final int bufferSize, final boolean failOnAllocate) {
            this.bufferSize = bufferSize;
            this.failOnAllocate = failOnAllocate;
        }

        @Override
        public PooledByteBuffer allocate() {
            allocateCount++;
            if (failOnAllocate) {
                throw new IllegalStateException("buffer pool is closed");
            }
            TrackingPooledByteBuffer pooled = new TrackingPooledByteBuffer(ByteBuffer.allocate(bufferSize));
            allocated.add(pooled);
            return pooled;
        }

        @Override
        public ByteBufferPool getArrayBackedPool() {
            return this;
        }

        @Override
        public void close() {
        }

        @Override
        public int getBufferSize() {
            return bufferSize;
        }

        @Override
        public boolean isDirect() {
            return false;
        }

        private TrackingPooledByteBuffer lastAllocated() {
            assertFalse(allocated.isEmpty(), "no buffer has been allocated");
            return allocated.get(allocated.size() - 1);
        }
    }

    /**
     * A source conduit whose read results are scripted by the test.
     */
    private static final class TestSourceConduit implements StreamSourceConduit {

        private final XnioIoThread ioThread;
        private final Deque<Object> script = new ArrayDeque<>();
        private ReadReadyHandler readReadyHandler;
        private boolean readShutdown;
        private int readCount;
        private int suspendCount;
        private int resumeCount;

        private TestSourceConduit(final XnioIoThread ioThread) {
            this.ioThread = ioThread;
        }

        private void addData(final String data) {
            script.add(ByteBuffer.wrap(bytes(data)));
        }

        private void addReadResult(final int result) {
            script.add(Integer.valueOf(result));
        }

        private void addReadFailure(final IOException exception) {
            script.add(exception);
        }

        private void setReadShutdown(final boolean readShutdown) {
            this.readShutdown = readShutdown;
        }

        private void resetCounters() {
            readCount = 0;
            suspendCount = 0;
            resumeCount = 0;
        }

        @Override
        public int read(final ByteBuffer dst) throws IOException {
            readCount++;
            Object next = script.poll();
            if (next == null) {
                return -1;
            }
            if (next instanceof IOException) {
                throw (IOException) next;
            }
            if (next instanceof Integer) {
                return ((Integer) next).intValue();
            }
            ByteBuffer data = (ByteBuffer) next;
            int count = Math.min(dst.remaining(), data.remaining());
            for (int i = 0; i < count; i++) {
                dst.put(data.get());
            }
            if (data.hasRemaining()) {
                script.addFirst(data);
            }
            return count;
        }

