        assertEquals(expectedWeak, eTag.isWeak(), () -> "Unexpected weakness for response header <" + headerValue + ">");
        assertEquals(expectedTag, eTag.getTag(), () -> "Unexpected tag for response header <" + headerValue + ">");
        final String expectedToString = expectedWeak ? "W/\"" + expectedTag + "\"" : "\"" + expectedTag + "\"";
        assertEquals(expectedToString, eTag.toString(), () -> "toString mismatch for response header <" + headerValue + ">");
    }

    private static void assertNotParsed(final String headerValue) {
