    static Stream<Arguments> wellFormedHeaders() {
        return Stream.of(
                Arguments.of("\"abc\"", false, "abc"),
                Arguments.of("W/\"abc\"", true, "abc"),
                Arguments.of("W/\"\"", true, ""),
                Arguments.of("\"\"", false, ""),
                Arguments.of("\"0\"", false, "0"),
                Arguments.of("W/\"0\"", true, "0"),
                Arguments.of("\"a-b_c.d:e\"", false, "a-b_c.d:e"),
                Arguments.of(" \"abc\"", false, "abc"),
                Arguments.of("\"abc\"   ", false, "abc"),
                Arguments.of("W/\"  abc\"", true, "abc"),
                Arguments.of("\"abc  \" , W/\"def\"", false, "abc"),
                // The parser accepts a quote directly after "W" (no slash) and treats the tag as weak.
                Arguments.of("W\"abc\"", true, "abc"),
                // A duplicated slash is tolerated as well.
                Arguments.of("W//\"abc\"", true, "abc"),
                // Only a quote can start a value, so an unrecognised leading token is simply skipped.
                Arguments.of("w/\"abc\"", false, "abc"),
                Arguments.of("\"abc", false, "abc"),
                Arguments.of("W/\"abc", true, "abc"));
