    private static byte[] sequence(int length) {
        return sequence(length, 0);
    }

    private static byte[] sequence(int length, int offset) {
        byte[] data = new byte[length];
        for (int i = 0; i < length; i++) {
            data[i] = (byte) ((i + offset) * 37 + 11);
