import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.fail;

/**
 * Tests for {@link FlexBase64.Decoder#decode(ByteBuffer, ByteBuffer)}.
 */
class FlexBase64DecodeTests {

    private FlexBase64.Decoder decoder;

    @BeforeEach
    void setUp() {
        decoder = FlexBase64.createDecoder();
    }

    private static ByteBuffer ascii(String value) {
        return ByteBuffer.wrap(value.getBytes(StandardCharsets.US_ASCII));
    }

    /**
     * Returns a copy of everything that has been written into the supplied target buffer.
     */
    private static byte[] bytesWritten(ByteBuffer target) {
        ByteBuffer view = target.duplicate();
        view.flip();
        byte[] result = new byte[view.remaining()];
        view.get(result);
        return result;
    }

    /**
     * Drives the decoder until the (fully available) source has been consumed, using a single
     * generously sized target buffer. Fails if the decoder ever stops making progress.
     */
    private byte[] decodeFully(byte[] encoded, int targetCapacity) throws IOException {
        ByteBuffer source = ByteBuffer.wrap(encoded);
        ByteBuffer target = ByteBuffer.allocate(targetCapacity);
        int guard = 0;
        while (source.hasRemaining()) {
            int before = source.position();
            decoder.decode(source, target);
            if (source.position() == before && source.hasRemaining()) {
                fail("Decoder made no progress at source position " + before);
            }
            if (++guard > 100_000) {
                fail("Decoder did not terminate");
            }
        }
        return bytesWritten(target);
    }

    /**
     * Drives the decoder until the source is consumed, supplying a fresh, small target buffer for
     * every invocation and concatenating whatever was produced by each call.
     */
    private byte[] decodeUsingSmallTargets(byte[] encoded, int targetCapacity) throws IOException {
        ByteBuffer source = ByteBuffer.wrap(encoded);
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        int guard = 0;
        while (source.hasRemaining()) {
            int before = source.position();
            ByteBuffer target = ByteBuffer.allocate(targetCapacity);
            decoder.decode(source, target);
            output.write(bytesWritten(target));
            if (source.position() == before && source.hasRemaining()) {
                fail("Decoder made no progress at source position " + before);
            }
            if (++guard > 100_000) {
                fail("Decoder did not terminate");
            }
        }
        return output.toByteArray();
    }

    private void decodeInto(ByteBuffer source, ByteBuffer target) throws IOException {
        int guard = 0;
        while (source.hasRemaining()) {
            int before = source.position();
            decoder.decode(source, target);
            if (source.position() == before && source.hasRemaining()) {
                fail("Decoder made no progress at source position " + before);
            }
            if (++guard > 100_000) {
                fail("Decoder did not terminate");
            }
        }
    }

    // ---------------------------------------------------------------------------------------------
    // Normal operation
    // ---------------------------------------------------------------------------------------------

    @Test
    void decodesSingleFourCharacterGroup() throws IOException {
        byte[] decoded = decodeFully("TWFu".getBytes(StandardCharsets.US_ASCII), 16);
        assertArrayEquals("Man".getBytes(StandardCharsets.US_ASCII), decoded);
    }

    @Test
    void decodesGroupWithOnePaddingCharacter() throws IOException {
        byte[] decoded = decodeFully("TWE=".getBytes(StandardCharsets.US_ASCII), 16);
        assertArrayEquals("Ma".getBytes(StandardCharsets.US_ASCII), decoded);
    }

    @Test
    void decodesGroupWithTwoPaddingCharacters() throws IOException {
        byte[] decoded = decodeFully("TQ==".getBytes(StandardCharsets.US_ASCII), 16);
        assertArrayEquals("M".getBytes(StandardCharsets.US_ASCII), decoded);
    }

    @Test
    void decodesMultipleGroupsInOneSource() throws IOException {
        byte[] decoded = decodeFully("TWFuTWE=".getBytes(StandardCharsets.US_ASCII), 16);
        assertArrayEquals("ManMa".getBytes(StandardCharsets.US_ASCII), decoded);
    }

    @Test
    void decodesEmptySourceWithoutTouchingTarget() throws IOException {
        ByteBuffer source = ascii("");
        ByteBuffer target = ByteBuffer.allocate(8);

        decoder.decode(source, target);

        assertEquals(0, source.position());
        assertEquals(0, target.position());
        assertEquals(8, target.limit());
        assertArrayEquals(new byte[0], bytesWritten(target));
    }

    @Test
    void decodesAllByteValues() throws IOException {
        byte[] raw = new byte[256];
        for (int i = 0; i < raw.length; i++) {
            raw[i] = (byte) i;
        }
        byte[] encoded = Base64.getEncoder().encode(raw);

        byte[] decoded = decodeFully(encoded, raw.length + 64);

        assertArrayEquals(raw, decoded);
    }

    @Test
    void decodesLargePayload() throws IOException {
        byte[] raw = new byte[4096];
        new Random(424242L).nextBytes(raw);
        byte[] encoded = Base64.getEncoder().encode(raw);

        byte[] decoded = decodeFully(encoded, raw.length + 64);

        assertArrayEquals(raw, decoded);
    }

    @Test
    void decodesSourceStartingAtNonZeroPosition() throws IOException {
        ByteBuffer source = ByteBuffer.wrap(new byte[] { 0x58, 0x58, 0x54, 0x57, 0x46, 0x75 });
        source.position(2);

        ByteBuffer target = ByteBuffer.allocate(8);
        decodeInto(source, target);

        assertArrayEquals("Man".getBytes(StandardCharsets.US_ASCII), bytesWritten(target));
        assertEquals(source.limit(), source.position());
    }

    // ---------------------------------------------------------------------------------------------
    // Whitespace handling
    // ---------------------------------------------------------------------------------------------

    @Test
    void skipsWhitespaceBetweenGroups() throws IOException {
        byte[] decoded = decodeFully("TWFu TWE=".getBytes(StandardCharsets.US_ASCII), 16);
        assertArrayEquals("ManMa".getBytes(StandardCharsets.US_ASCII), decoded);
    }

    @Test
    void skipsAllWhitespaceKinds() throws IOException {
        byte[] encoded = "TW\r\nFu\tTW\r E=".getBytes(StandardCharsets.US_ASCII);
        byte[] decoded = decodeFully(encoded, 16);
        assertArrayEquals("ManMa".getBytes(StandardCharsets.US_ASCII), decoded);
    }

    @Test
    void consumesWhitespaceOnlySourceWithoutOutput() throws IOException {
        ByteBuffer source = ascii(" \t\r\n ");
        ByteBuffer target = ByteBuffer.allocate(8);

        decoder.decode(source, target);

        assertEquals(source.limit(), source.position());
        assertEquals(0, target.position());
    }

    @Test
    void skipsLeadingAndTrailingWhitespace() throws IOException {
        byte[] encoded = "  \r\nTWFu TWE=  \r\n".getBytes(StandardCharsets.US_ASCII);

        byte[] decoded = decodeFully(encoded, 16);

        assertArrayEquals("ManMa".getBytes(StandardCharsets.US_ASCII), decoded);
    }

    // ---------------------------------------------------------------------------------------------
    // Target buffer handling / state persistence
    // ---------------------------------------------------------------------------------------------

    @Test
    void writesAtCurrentTargetPositionAndLeavesRestUntouched() throws IOException {
        ByteBuffer source = ascii("TWFu");
        ByteBuffer target = ByteBuffer.allocate(12);
        target.put((byte) 0x7F);
        target.put((byte) 0x7F);

        decodeInto(source, target);

        assertEquals(5, target.position());
        assertEquals(12, target.limit());
        assertArrayEquals(
                new byte[] { 0x7F, 0x7F, 'M', 'a', 'n', 0, 0, 0, 0, 0, 0, 0 },
                target.array());
        assertFalse(source.hasRemaining());
    }

    @Test
    void resumesDecodingUsingSingleByteTargets() throws IOException {
        byte[] decoded = decodeUsingSmallTargets("aGVsbG8=".getBytes(StandardCharsets.US_ASCII), 1);
        assertArrayEquals("hello".getBytes(StandardCharsets.US_ASCII), decoded);
    }

    @Test
    void resumesDecodingUsingTwoByteTargets() throws IOException {
        byte[] raw = "The quick brown fox jumps over the lazy dog".getBytes(StandardCharsets.US_ASCII);
        byte[] encoded = Base64.getEncoder().encode(raw);

        byte[] decoded = decodeUsingSmallTargets(encoded, 2);

        assertArrayEquals(raw, decoded);
    }

    @Test
    void fullTargetProducesNoOutputAndKeepsState() throws IOException {
        ByteBuffer source = ascii("TWFu");
        ByteBuffer emptyTarget = ByteBuffer.allocate(0);

        decoder.decode(source, emptyTarget);

        assertEquals(0, emptyTarget.position());
        assertEquals(0, source.position(), "source must not be consumed when the target is full");

        // the state must be untouched, so the very same source can still be decoded completely
        ByteBuffer realTarget = ByteBuffer.allocate(8);
        decodeInto(source, realTarget);
        assertArrayEquals("Man".getBytes(StandardCharsets.US_ASCII), bytesWritten(realTarget));
    }

    @Test
    void targetLimitIsNotChanged() throws IOException {
        ByteBuffer source = ascii("TWFu");
        ByteBuffer target = ByteBuffer.allocate(16);
        target.limit(10);

        decodeInto(source, target);

        assertEquals(3, target.position());
        assertEquals(10, target.limit());
    }

    @Test
    void decoderIsReusableForIndependentInputs() throws IOException {
        byte[] first = decodeFully("TQ==".getBytes(StandardCharsets.US_ASCII), 8);
        assertArrayEquals("M".getBytes(StandardCharsets.US_ASCII), first);

        byte[] second = decodeFully("TWFu".getBytes(StandardCharsets.US_ASCII), 8);
        assertArrayEquals("Man".getBytes(StandardCharsets.US_ASCII), second);
    }

    @Test
    void decoderIsReusableAfterUnpaddedGroup() throws IOException {
        byte[] first = decodeFully("TWFu".getBytes(StandardCharsets.US_ASCII), 8);
        assertArrayEquals("Man".getBytes(StandardCharsets.US_ASCII), first);

        byte[] second = decodeFully("aGVsbG8=".getBytes(StandardCharsets.US_ASCII), 8);
        assertArrayEquals("hello".getBytes(StandardCharsets.US_ASCII), second);
    }

    @Test
    void continuesAfterPaddedGroupWithinSameSource() throws IOException {
        ByteBuffer source = ascii("TQ==TWFu");
        ByteBuffer target = ByteBuffer.allocate(8);

        decoder.decode(source, target);
        assertArrayEquals("M".getBytes(StandardCharsets.US_ASCII), bytesWritten(target));
        assertTrue(source.hasRemaining(), "decoder should stop after the padding");

        ByteBuffer secondTarget = ByteBuffer.allocate(8);
        decodeInto(source, secondTarget);
        assertArrayEquals("Man".getBytes(StandardCharsets.US_ASCII), bytesWritten(secondTarget));
    }

    // ---------------------------------------------------------------------------------------------
    // URL safe variant
    // ---------------------------------------------------------------------------------------------

    @Test
    void urlDecoderDecodesUrlSafeAlphabet() throws IOException {
        byte[] raw = new byte[] { (byte) 0xFB, (byte) 0xFF };
        String urlEncoded = Base64.getUrlEncoder().withoutPadding().encodeToString(raw);
        assertEquals("-_8", urlEncoded);

        decoder = FlexBase64.createURLDecoder();
        byte[] decoded = decodeFully((urlEncoded + "=").getBytes(StandardCharsets.US_ASCII), 16);

        assertArrayEquals(raw, decoded);
    }

    @Test
    void standardDecoderRejectsUrlSafeAlphabet() {
        ByteBuffer source = ascii("-_8=");
        ByteBuffer target = ByteBuffer.allocate(8);

        IOException e = assertThrows(IOException.class, () -> decoder.decode(source, target));
        assertTrue(e.getMessage().contains("Invalid base64 character"), e.getMessage());
    }

    @Test
    void urlDecoderRejectsStandardAlphabet() {
        decoder = FlexBase64.createURLDecoder();
        ByteBuffer source = ascii("+/8=");
        ByteBuffer target = ByteBuffer.allocate(8);

        IOException e = assertThrows(IOException.class, () -> decoder.decode(source, target));
        assertTrue(e.getMessage().contains("Invalid base64 character"), e.getMessage());
    }

    // ---------------------------------------------------------------------------------------------
    // Invalid input
    // ---------------------------------------------------------------------------------------------

    @Test
    void nullTargetThrowsIllegalStateException() {
        ByteBuffer source = ascii("TWFu");

        assertThrows(IllegalStateException.class, () -> decoder.decode(source, null));
        assertEquals(0, source.position());
    }

    @Test
    void illegalCharacterThrowsIOException() {
        ByteBuffer source = ascii("TW*F");
        ByteBuffer target = ByteBuffer.allocate(8);

        IOException e = assertThrows(IOException.class, () -> decoder.decode(source, target));
        assertTrue(e.getMessage().contains("Invalid base64 character"), e.getMessage());
    }

    @Test
    void characterBelowSupportedRangeThrowsIOException() {
        ByteBuffer source = ByteBuffer.wrap(new byte[] { 'T', 'W', '!', 'F' });
        ByteBuffer target = ByteBuffer.allocate(8);

        IOException e = assertThrows(IOException.class, () -> decoder.decode(source, target));
        assertTrue(e.getMessage().contains("Invalid base64 character"), e.getMessage());
    }

    @Test
    void characterAboveSupportedRangeThrowsIOException() {
        ByteBuffer source = ByteBuffer.wrap(new byte[] { 'T', 'W', (byte) 0x7F, 'F' });
        ByteBuffer target = ByteBuffer.allocate(8);

        IOException e = assertThrows(IOException.class, () -> decoder.decode(source, target));
        assertTrue(e.getMessage().contains("Invalid base64 character"), e.getMessage());
    }

    @Test
    void highBitByteThrowsIOException() {
        ByteBuffer source = ByteBuffer.wrap(new byte[] { 'T', 'W', (byte) 0x80, 'F' });
        ByteBuffer target = ByteBuffer.allocate(8);

        IOException e = assertThrows(IOException.class, () -> decoder.decode(source, target));
        assertTrue(e.getMessage().contains("Invalid base64 character"), e.getMessage());
    }

    @Test
    void paddingAsFirstCharacterThrowsIOException() {
        ByteBuffer source = ascii("=TWF");
        ByteBuffer target = ByteBuffer.allocate(8);

        IOException e = assertThrows(IOException.class, () -> decoder.decode(source, target));
        assertTrue(e.getMessage().contains("Unexpected padding character"), e.getMessage());
    }

    @Test
    void paddingAfterFirstDataCharacterThrowsIOException() {
        ByteBuffer source = ascii("T=");
        ByteBuffer target = ByteBuffer.allocate(8);

        IOException e = assertThrows(IOException.class, () -> decoder.decode(source, target));
        assertTrue(e.getMessage().contains("Unexpected padding character"), e.getMessage());
    }

    @Test
    void missingSecondPaddingCharacterThrowsIOException() throws IOException {
        ByteBuffer source = ascii("TQ=A");
        ByteBuffer target = ByteBuffer.allocate(8);

        // the first invocation stops right after the first padding character; the second one
        // observes the malformed padding
        decoder.decode(source, target);

        IOException e = assertThrows(IOException.class, () -> decoder.decode(source, target));
        assertTrue(e.getMessage().contains("Expected padding character"), e.getMessage());
    }

    @Test
    void decodeRoundTripForTextPayload() throws IOException {
        byte[] raw = "Undertow is a flexible performant web server written in java".getBytes(StandardCharsets.US_ASCII);
        byte[] encoded = Base64.getEncoder().encode(raw);

        assertArrayEquals(raw, decodeFully(encoded, raw.length + 32));
        assertArrayEquals(raw, decodeUsingSmallTargets(encoded, 3));
    }
}

