    static Stream<Arguments> largeReadConfigurations() {
        int[] bufferSizes = { 1, 4, 8, 16, 100, 8192 };
        int[] chunks = { 64, 512, 9000 };
        List<Arguments> arguments = new ArrayList<>();
        for (boolean wrap : new boolean[] { false, true }) {
            for (int size : DATA_SIZES) {
                for (int bufferSize : bufferSizes) {
                    for (int chunk : chunks) {
                        if (chunk <= bufferSize) {
                            // only interested in reads that exceed the internal buffer
