            for (int size : new int[] { 0, 1, 2, 3, 55, 56, 57, 58, 200 }) {
                byte[] data = data(size);
                InputStream input = FlexBase64.createEncoderInputStream(new ByteArrayInputStream(data), 16, wrap);
                byte[] buffer = new byte[offset + chunk + sentinel];
                Arrays.fill(buffer, (byte) 0x5A);
                ByteArrayOutputStream output = new ByteArrayOutputStream();

                int read;
                while ((read = input.read(buffer, offset, chunk)) != -1) {
                    assertTrue(read <= chunk, "read more bytes than requested");
                    for (int i = 0; i < offset; i++) {
                        assertEquals((byte) 0x5A, buffer[i], "byte before the offset was modified");
                    }
                    for (int i = offset + read; i < buffer.length; i++) {
                        assertEquals((byte) 0x5A, buffer[i], "byte after the read data was modified");
                    }
                    output.write(buffer, offset, read);
                    // wipe the scratch area so that stale data from a previous read cannot mask a
                    // write past the number of bytes reported by the stream
                    Arrays.fill(buffer, (byte) 0x5A);
