        Map<TestToken, String> result = parser.parseHeader("third=three, first=one,second=two");

        assertEquals(List.of(TestToken.THIRD, TestToken.FIRST, TestToken.SECOND),
                new ArrayList<>(result.keySet()));
        assertEquals("three", result.get(TestToken.THIRD));
        assertEquals("one", result.get(TestToken.FIRST));
        assertEquals("two", result.get(TestToken.SECOND));
    }

    @Test
    void ignoresWhitespaceAroundNamesSeparatorsAndUnquotedValues() {
        Map<TestToken, String> result = parser.parseHeader(
                " \t first=one ,\n second= two  , \t third=three \t ");

        assertEquals(List.of(TestToken.FIRST, TestToken.SECOND, TestToken.THIRD),
                new ArrayList<>(result.keySet()));
        assertEquals("one", result.get(TestToken.FIRST));
        assertEquals("two", result.get(TestToken.SECOND));
        assertEquals("three", result.get(TestToken.THIRD));
    }

