        Map<TestToken, String> result = parser.parseHeader("first=one second=two");

        assertEquals(List.of(TestToken.FIRST, TestToken.SECOND),
                new ArrayList<>(result.keySet()));
        assertEquals("one", result.get(TestToken.FIRST));
        assertEquals("two", result.get(TestToken.SECOND));
    }

    @Test
    void preservesDelimiterCharactersAndWhitespaceInsideQuotedValues() {
        Map<TestToken, String> result = parser.parseHeader("quoted=\"a, b=c\" , third=three");

        assertEquals("a, b=c", result.get(TestToken.QUOTED));
        assertEquals("three", result.get(TestToken.THIRD));
    }

    @Test
    void parsesAnEmptyQuotedValue() {
        Map<TestToken, String> result = parser.parseHeader("quoted=\"\"");

        assertEquals(1, result.size());
        assertEquals("", result.get(TestToken.QUOTED));
    }

    @Test
    void treatsQuotesAsLiteralCharactersWhenTokenDoesNotAllowQuotedValues() {
        Map<TestToken, String> result = parser.parseHeader("unquoted=\"literal\"");

        assertEquals("\"literal\"", result.get(TestToken.UNQUOTED));
