    @ParameterizedTest
    @ValueSource(strings = {"", "   ", ",", ", ,", "\t,\n", " , \t , "})
    void returnsAnEmptyMapWhenTheHeaderHasNoParameters(String header) {
        assertTrue(parser.parseHeader(header).isEmpty());
    }

    @Test
    void rejectsAnUnexpectedTokenWithTheTokenName() {
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
