        assertEquals("UT000025: Unexpected token 'unknown' within header.", exception.getMessage());
    }

    @ParameterizedTest
    @ValueSource(strings = {"first", "first ", "first\t"})
    void rejectsAParameterWithoutAnEqualsSign(String header) {
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
