        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> parser.parseHeader(header));

        assertEquals("UT000026: Invalid header received.", exception.getMessage());
    }

    @Test
    void rejectsANullHeader() {
        assertThrows(NullPointerException.class, () -> parser.parseHeader(null));
    }

    private enum TestToken implements HeaderToken {
