package io.undertow.util;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Unit tests for {@link QValueParser#parse(List)}.
 *
 * <p>The parsed result is rendered as a list of groups separated by spaces, where each group is
 * written as {@code [value/qvalue,value/qvalue]} so that both the grouping (equal q values) and the
 * ordering (highest priority first) can be asserted at once.</p>
 */
public class QValueParserParseTests {

    private static String render(final List<List<QValueParser.QValueResult>> parsed) {
        final StringBuilder sb = new StringBuilder();
        for (int i = 0; i < parsed.size(); i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append('[');
            final List<QValueParser.QValueResult> group = parsed.get(i);
            for (int j = 0; j < group.size(); j++) {
                if (j > 0) {
                    sb.append(',');
                }
                sb.append(group.get(j).getValue()).append('/').append(group.get(j).getQvalue());
            }
            sb.append(']');
        }
        return sb.toString();
    }

    private static String parseAndRender(final String... headers) {
        return render(QValueParser.parse(Arrays.asList(headers)));
    }

    @Test
    public void testEmptyHeaderList() {
        final List<List<QValueParser.QValueResult>> result = QValueParser.parse(new ArrayList<String>());
        assertNotNull(result);
        assertTrue(result.isEmpty(), "no headers means no results");
    }

    @Test
    public void testSingleValueWithoutQValue() {
        final List<List<QValueParser.QValueResult>> result = QValueParser.parse(Collections.singletonList("gzip"));
        assertEquals(1, result.size());
        assertEquals(1, result.get(0).size());
        final QValueParser.QValueResult value = result.get(0).get(0);
        assertEquals("gzip", value.getValue());
        assertEquals("1", value.getQvalue(), "the default q value is 1");
    }

