import org.junit.jupiter.api.Test;

/**
 * Unit tests for {@link WebSocketFramePriority#insertFrame(StreamSinkFrameChannel, List)}.
 *
 * <p>The tests use a lightweight controllable {@link StreamSinkFrameChannel} implementation so
 * that frame type, fragmentation state, writability shutdown state, open state and brokenness can
 * all be observed directly.</p>
 */
class WebSocketFramePriorityInsertFrameTests {

    private WebSocketFramePriority priority;
    private List<StreamSinkFrameChannel> pendingFrames;
    private WebSocketChannel openChannel;
    private WebSocketChannel remotelyClosedChannel;

    @BeforeEach
    void setUp() {
        priority = new WebSocketFramePriority();
        pendingFrames = new ArrayList<>();

        openChannel = createNiceMock(WebSocketChannel.class);
        expect(openChannel.isCloseFrameReceived()).andReturn(false).anyTimes();
        replay(openChannel);

        remotelyClosedChannel = createNiceMock(WebSocketChannel.class);
        expect(remotelyClosedChannel.isCloseFrameReceived()).andReturn(true).anyTimes();
        replay(remotelyClosedChannel);
    }

    // ------------------------------------------------------------------
    // Simple, non-fragmented insertion
    // ------------------------------------------------------------------

    @Test
    @DisplayName("A regular frame is appended when no frames are pending")
    void regularFrameIsAppendedToEmptyPendingFrames() {
        TestStreamSinkFrameChannel frame = frame(WebSocketFrameType.TEXT);

        assertTrue(priority.insertFrame(frame, pendingFrames), "a normal frame must be accepted");

        assertEquals(1, pendingFrames.size());
        assertSame(frame, pendingFrames.get(0));
        assertFalse(frame.broken, "an accepted frame must not be marked broken");
        assertFalse(priority.closed);
    }

    @Test
    @DisplayName("Regular frames are appended in insertion order when no fragmentation is active")
    void regularFramesAreAppendedInOrder() {
        TestStreamSinkFrameChannel first = frame(WebSocketFrameType.TEXT).writesShutdown(true);
        TestStreamSinkFrameChannel second = frame(WebSocketFrameType.BINARY).writesShutdown(true);

        assertTrue(priority.insertFrame(first, pendingFrames));
        assertTrue(priority.insertFrame(second, pendingFrames));

        assertEquals(List.of(first, second), pendingFrames);
        assertFalse(first.broken);
        assertFalse(second.broken);
    }

    @Test
    @DisplayName("A frame is dropped and marked broken when the priority is already closed")
    void frameIsDroppedWhenPriorityIsClosed() {
        priority.closed = true;
        TestStreamSinkFrameChannel frame = frame(WebSocketFrameType.TEXT);

        assertTrue(priority.insertFrame(frame, pendingFrames), "closed priority still reports the frame as consumed");

        assertTrue(pendingFrames.isEmpty(), "a dropped frame must not be queued");
        assertTrue(frame.broken, "a dropped frame must be marked broken");
    }

    @Test
    @DisplayName("Control frames are also dropped when the priority is closed")
    void controlFrameIsDroppedWhenPriorityIsClosed() {
        priority.closed = true;
        TestStreamSinkFrameChannel ping = frame(WebSocketFrameType.PING).writesShutdown(true);

        assertTrue(priority.insertFrame(ping, pendingFrames));

        assertTrue(pendingFrames.isEmpty());
        assertTrue(ping.broken);
    }

    @Test
    @DisplayName("A close frame is queued and closes the priority for later frames")
    void closeFrameClosesPriority() {
        TestStreamSinkFrameChannel close = frame(WebSocketFrameType.CLOSE);

        assertTrue(priority.insertFrame(close, pendingFrames));
        assertEquals(List.of(close), pendingFrames);
        assertTrue(priority.closed, "a close frame must close the priority");

        TestStreamSinkFrameChannel later = frame(WebSocketFrameType.TEXT);
        assertTrue(priority.insertFrame(later, pendingFrames));

        assertEquals(List.of(close), pendingFrames, "frames after close must not be queued");
        assertTrue(later.broken, "frames after close must be marked broken");
    }

    // ------------------------------------------------------------------
