    // ------------------------------------------------------------------

    @Test
    @DisplayName("A non-control frame is rejected while another stream's strict-order frame is open")
    void nonControlFrameIsRejectedWhileStrictOrderFrameIsOpen() {
        TestStreamSinkFrameChannel order = frame(WebSocketFrameType.TEXT).open(true);
        priority.addToOrderQueue(order);

        TestStreamSinkFrameChannel frame = frame(WebSocketFrameType.BINARY);

        assertFalse(priority.insertFrame(frame, pendingFrames),
