    @Test
    @DisplayName("A non-control frame is accepted when the head strict-order frame is no longer open")
    void nonControlFrameIsAcceptedWhenStrictOrderFrameIsClosed() {
        TestStreamSinkFrameChannel order = frame(WebSocketFrameType.TEXT).open(false);
        priority.addToOrderQueue(order);

        TestStreamSinkFrameChannel frame = frame(WebSocketFrameType.BINARY);

        assertTrue(priority.insertFrame(frame, pendingFrames));
        assertEquals(List.of(frame), pendingFrames);
    }

    @Test
    @DisplayName("A close frame is rejected while ordering is outstanding and no remote close was received")
    void closeFrameIsRejectedWhileStrictOrderFrameIsOpenAndNoRemoteClose() {
        TestStreamSinkFrameChannel order = frame(WebSocketFrameType.TEXT).open(true);
        priority.addToOrderQueue(order);

        TestStreamSinkFrameChannel close = frame(WebSocketFrameType.CLOSE, openChannel);

        assertFalse(priority.insertFrame(close, pendingFrames));
        assertTrue(pendingFrames.isEmpty());
        assertFalse(priority.closed, "a rejected close frame must not close the priority");
    }

    @Test
    @DisplayName("A close frame is accepted while ordering is outstanding once the remote close was received")
    void closeFrameIsAcceptedAfterRemoteCloseReceived() {
        TestStreamSinkFrameChannel order = frame(WebSocketFrameType.TEXT).open(true);
        priority.addToOrderQueue(order);

        TestStreamSinkFrameChannel close = frame(WebSocketFrameType.CLOSE, remotelyClosedChannel);

        assertTrue(priority.insertFrame(close, pendingFrames));
        assertEquals(List.of(close), pendingFrames);
        assertTrue(priority.closed);
    }

    @Test
    @DisplayName("A close frame is accepted while ordering is outstanding when immediate close is enabled")
    void closeFrameIsAcceptedWhenImmediateCloseFrameIsEnabled() {
        TestStreamSinkFrameChannel order = frame(WebSocketFrameType.TEXT).open(true);
        priority.addToOrderQueue(order);
        priority.immediateCloseFrame();

        TestStreamSinkFrameChannel close = frame(WebSocketFrameType.CLOSE, openChannel);

        assertTrue(priority.insertFrame(close, pendingFrames));
        assertEquals(List.of(close), pendingFrames);
        assertTrue(priority.closed);
    }

    @Test
    @DisplayName("A close frame is accepted when the outstanding strict-order frame is closed")
    void closeFrameIsAcceptedWhenStrictOrderFrameIsClosed() {
        TestStreamSinkFrameChannel order = frame(WebSocketFrameType.TEXT).open(false);
        priority.addToOrderQueue(order);

        TestStreamSinkFrameChannel close = frame(WebSocketFrameType.CLOSE, openChannel);

        assertTrue(priority.insertFrame(close, pendingFrames));
        assertEquals(List.of(close), pendingFrames);
