        priority.addToOrderQueue(order);

        assertTrue(priority.insertFrame(order, pendingFrames));
        assertEquals(List.of(order), pendingFrames);

        TestStreamSinkFrameChannel later = frame(WebSocketFrameType.BINARY);
        assertTrue(priority.insertFrame(later, pendingFrames),
                "after the order head is polled, later frames must be accepted");
        assertEquals(List.of(order, later), pendingFrames);
    }

    @Test
    @DisplayName("The strict-order head stays queued when its inserted frame is not final")
    void nonFinalFragmentOfStrictOrderHeadRemainsQueued() {
        TestStreamSinkFrameChannel order = frame(WebSocketFrameType.TEXT)
                .open(true).finalFragment(false).writesShutdown(true);
        priority.addToOrderQueue(order);

        assertTrue(priority.insertFrame(order, pendingFrames));
        assertEquals(List.of(order), pendingFrames);

        TestStreamSinkFrameChannel later = frame(WebSocketFrameType.BINARY);
        assertFalse(priority.insertFrame(later, pendingFrames),
                "the non-final order head must continue to block other streams");
        assertEquals(List.of(order), pendingFrames);
