    // ------------------------------------------------------------------

    @Test
    @DisplayName("A control frame is inserted before the first non-control pending frame")
    void controlFrameIsInsertedBeforeFirstNonControlFrame() {
        TestStreamSinkFrameChannel inFlight = frame(WebSocketFrameType.BINARY).writesShutdown(true);
        TestStreamSinkFrameChannel pendingPing = frame(WebSocketFrameType.PING).writesShutdown(true);
        TestStreamSinkFrameChannel pendingPong = frame(WebSocketFrameType.PONG).writesShutdown(true);
        TestStreamSinkFrameChannel pendingText = frame(WebSocketFrameType.TEXT).writesShutdown(true);
