                .finalFragment(false).writesShutdown(false);
        assertTrue(priority.insertFrame(fragmenter, pendingFrames));

        fragmenter.finalFragment(true);
        assertTrue(priority.insertFrame(fragmenter, pendingFrames));
        assertEquals(List.of(fragmenter, fragmenter), pendingFrames);

        TestStreamSinkFrameChannel next = frame(WebSocketFrameType.TEXT);
        assertTrue(priority.insertFrame(next, pendingFrames),
                "after the final fragment a new stream may start");
        assertEquals(List.of(fragmenter, fragmenter, next), pendingFrames);
