    @Test
    @DisplayName("A close frame cannot be queued in the middle of another fragmented send")
    void closeFrameIsRejectedDuringAnotherFragmentedSend() {
        TestStreamSinkFrameChannel fragmenter = frame(WebSocketFrameType.TEXT)
                .finalFragment(false).writesShutdown(false);
