        assertFalse(priority.insertFrame(frame, pendingFrames),
                "the ordering check happens before the closed check");
        assertTrue(pendingFrames.isEmpty());
        assertFalse(frame.broken, "a frame rejected by strict ordering is not marked broken");
    }

