        EasyMock.expect(connection.getSinkChannel()).andReturn(sinkChannel).anyTimes();

        EasyMock.replay(connection);
    }

    @AfterEach
    public void tearDown() {
        for (StreamSourceFrameChannel channel : createdChannels) {
            IoUtils.safeClose(channel);
        }
        createdChannels.clear();
        for (WebSocketChannel channel : createdWebSocketChannels) {
            IoUtils.safeClose(channel);
        }
        createdWebSocketChannels.clear();
        bufferPool.close();
