    @Test
    void sixteenBitExtendedPayloadLengthIsDecoded() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        ByteBuffer frame = buffer(firstByte(true, 0, OPCODE_BINARY), secondByte(false, 126), 0x01, 0x00);
        header.handle(frame);

        assertTrue(header.isDone());
        assertEquals(256, header.getFrameLength());
        assertEquals(0, frame.remaining());
    }

    @Test
    void sixteenBitExtendedPayloadLengthIsUnsigned() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        header.handle(buffer(firstByte(true, 0, OPCODE_BINARY), secondByte(false, 126), 0xFF, 0xFF));

        assertTrue(header.isDone());
        assertEquals(65535, header.getFrameLength(), "the extended length must be treated as unsigned");
    }

    @Test
    void sixtyFourBitExtendedPayloadLengthIsDecoded() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        ByteBuffer frame = buffer(firstByte(true, 0, OPCODE_BINARY), secondByte(false, 127),
                0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x00);
        header.handle(frame);

        assertTrue(header.isDone());
        assertEquals(256, header.getFrameLength());
        assertEquals(0, frame.remaining());
    }

    @Test
    void sixtyFourBitExtendedPayloadLengthWithHighBytesIsDecoded() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        header.handle(buffer(firstByte(true, 0, OPCODE_BINARY), secondByte(false, 127),
                0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08));

        assertTrue(header.isDone());
        assertEquals(0x0102030405060708L, header.getFrameLength());
    }

    @Test
    void incompleteEightByteExtendedPayloadLengthIsPostponed() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        ByteBuffer partial = buffer(firstByte(true, 0, OPCODE_BINARY), secondByte(false, 127), 0x01, 0x02);
        header.handle(partial);
        assertFalse(header.isDone(), "the 8 byte extended length is not complete yet");
        assertEquals(0, partial.remaining(), "the available bytes must be consumed");

        ByteBuffer rest = buffer(0x03, 0x04, 0x05, 0x06, 0x07, 0x08);
        header.handle(rest);
        assertTrue(header.isDone());
        assertEquals(0x0102030405060708L, header.getFrameLength());
        assertEquals(0, rest.remaining());
    }

    @Test
    void extendedPayloadLengthMarkerWithoutFollowingBytesIsPostponed() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        header.handle(buffer(firstByte(true, 0, OPCODE_BINARY), secondByte(false, 126)));
        assertFalse(header.isDone(), "the extended 16 bit length has not been read yet");

        header.handle(buffer(0x00, 0x7D));
        assertTrue(header.isDone());
        assertEquals(125, header.getFrameLength());
    }

    // -------------------------------------------------------------- masking tests

    @Test
    void maskedFrameReadsTheMaskingKey() throws Exception {
        WebSocket07Channel channel = newChannel(false, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        ByteBuffer frame = buffer(firstByte(true, 0, OPCODE_TEXT), secondByte(true, 3),
                0x0A, 0x0B, 0x0C, 0x0D);
        header.handle(frame);

        assertTrue(header.isDone());
        assertEquals(3, header.getFrameLength());
        assertEquals(0x0A0B0C0D, header.getMaskingKey());
        assertEquals(0, frame.remaining());
    }

    @Test
    void maskedFrameWithExtendedPayloadLengthReadsTheMaskingKey() throws Exception {
        WebSocket07Channel channel = newChannel(false, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        ByteBuffer frame = buffer(firstByte(true, 0, OPCODE_BINARY), secondByte(true, 127),
                0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x03,
                0x11, 0x22, 0x33, 0x44);
        header.handle(frame);

        assertTrue(header.isDone());
        assertEquals(3, header.getFrameLength());
        assertEquals(0x11223344, header.getMaskingKey());
        assertEquals(0, frame.remaining());
    }

    @Test
    void maskingKeyIsAccumulatedOverSeveralInvocations() throws Exception {
        WebSocket07Channel channel = newChannel(false, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        header.handle(buffer(firstByte(true, 0, OPCODE_TEXT), secondByte(true, 0)));
        assertFalse(header.isDone(), "the masking key has not been read yet");

        header.handle(buffer(0x01));
        assertFalse(header.isDone());
        header.handle(buffer(0x02));
        assertFalse(header.isDone());
        header.handle(buffer(0x03));
        assertFalse(header.isDone());
        assertEquals(0, header.getFrameLength());

        header.handle(buffer(0x04));
        assertTrue(header.isDone());
        assertEquals(0x01020304, header.getMaskingKey());
        assertEquals(0, header.getFrameLength());
    }

    @Test
    void unmaskedDataFrameOnServerChannelIsRejected() {
        WebSocket07Channel channel = newChannel(false, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        WebSocketFrameCorruptedException exception = assertThrows(WebSocketFrameCorruptedException.class,
                () -> header.handle(buffer(firstByte(true, 0, OPCODE_TEXT), secondByte(false, 1))));

        assertMessageContains(exception, "was not masked");
        assertFalse(header.isDone());
    }

    @Test
    void maskedDataFrameOnServerChannelIsAccepted() throws Exception {
        WebSocket07Channel channel = newChannel(false, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        header.handle(buffer(firstByte(true, 0, OPCODE_TEXT), secondByte(true, 1), 0x01, 0x02, 0x03, 0x04));

        assertTrue(header.isDone());
        assertEquals(1, header.getFrameLength());
        assertEquals(0x01020304, header.getMaskingKey());
    }

    @Test
    void unmaskedDataFrameOnClientChannelIsAccepted() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        header.handle(buffer(firstByte(true, 0, OPCODE_BINARY), secondByte(false, 1)));

        assertTrue(header.isDone());
        assertEquals(1, header.getFrameLength());
        assertEquals(0, header.getMaskingKey());
    }

    // -------------------------------------------------------------- data frame validation

    @Test
    void reservedDataOpcodeIsRejected() {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        WebSocketFrameCorruptedException exception = assertThrows(WebSocketFrameCorruptedException.class,
                () -> header.handle(buffer(firstByte(true, 0, 0x3), secondByte(false, 0))));

        assertMessageContains(exception, "Data frame using reserved opcode = 3");
        assertFalse(header.isDone());
    }

    @Test
    void continuationFrameOutsideFragmentedMessageIsRejected() {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        WebSocketFrameCorruptedException exception = assertThrows(WebSocketFrameCorruptedException.class,
                () -> header.handle(buffer(firstByte(true, 0, OPCODE_CONT), secondByte(false, 0))));

        assertMessageContains(exception, "continuation data frame outside fragmented message");
        assertFalse(header.isDone());
    }

    @Test
    void nonContinuationFrameInsideFragmentedMessageIsRejected() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);

        newHeader(channel).handle(buffer(firstByte(false, 0, OPCODE_TEXT), secondByte(false, 0)));

        WebSocket07Channel.WebSocketFrameHeader second = newHeader(channel);
        WebSocketFrameCorruptedException exception = assertThrows(WebSocketFrameCorruptedException.class,
                () -> second.handle(buffer(firstByte(true, 0, OPCODE_TEXT), secondByte(false, 0))));

        assertMessageContains(exception, "non-continuation data frame while inside fragmented message");
        assertFalse(second.isDone());
    }

    @Test
    void continuationFrameInsideFragmentedMessageIsAcceptedAndResetsTheState() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);

        WebSocket07Channel.WebSocketFrameHeader first = newHeader(channel);
        first.handle(buffer(firstByte(false, 0, OPCODE_TEXT), secondByte(false, 4)));
        assertTrue(first.isDone());
        assertFalse(first.isFinalFragment());

        WebSocket07Channel.WebSocketFrameHeader continuation = newHeader(channel);
        continuation.handle(buffer(firstByte(true, 0, OPCODE_CONT), secondByte(false, 2)));
        assertTrue(continuation.isDone());
        assertTrue(continuation.isFinalFragment());
        assertEquals(2, continuation.getFrameLength());

        // the fragmented message is finished, a new data frame must be accepted again
        WebSocket07Channel.WebSocketFrameHeader text = newHeader(channel);
        text.handle(buffer(firstByte(true, 0, OPCODE_TEXT), secondByte(false, 0)));
        assertTrue(text.isDone());
    }

    @Test
    void pingFrameInTheMiddleOfAFragmentedMessageDoesNotResetTheState() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);

        newHeader(channel).handle(buffer(firstByte(false, 0, OPCODE_BINARY), secondByte(false, 0)));

        WebSocket07Channel.WebSocketFrameHeader ping = newHeader(channel);
        ping.handle(buffer(firstByte(true, 0, OPCODE_PING), secondByte(false, 0)));
        assertTrue(ping.isDone());

        WebSocket07Channel.WebSocketFrameHeader text = newHeader(channel);
        WebSocketFrameCorruptedException exception = assertThrows(WebSocketFrameCorruptedException.class,
                () -> text.handle(buffer(firstByte(true, 0, OPCODE_TEXT), secondByte(false, 0))));
        assertMessageContains(exception, "non-continuation data frame while inside fragmented message");

        // the fragmented message is still in progress, so continuation frames are still allowed
        WebSocket07Channel.WebSocketFrameHeader continuation = newHeader(channel);
        continuation.handle(buffer(firstByte(true, 0, OPCODE_CONT), secondByte(false, 0)));
        assertTrue(continuation.isDone());
    }

    @Test
    void pongFrameInTheMiddleOfAFragmentedMessageDoesNotResetTheState() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);

        newHeader(channel).handle(buffer(firstByte(false, 0, OPCODE_TEXT), secondByte(false, 0)));

        WebSocket07Channel.WebSocketFrameHeader pong = newHeader(channel);
        pong.handle(buffer(firstByte(true, 0, OPCODE_PONG), secondByte(false, 0)));
        assertTrue(pong.isDone());

        WebSocket07Channel.WebSocketFrameHeader text = newHeader(channel);
        WebSocketFrameCorruptedException exception = assertThrows(WebSocketFrameCorruptedException.class,
                () -> text.handle(buffer(firstByte(true, 0, OPCODE_TEXT), secondByte(false, 0))));
        assertMessageContains(exception, "non-continuation data frame while inside fragmented message");
    }

    @Test
    void finalPingFrameWithoutAFragmentedMessageKeepsNewDataFramesAllowed() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);

        WebSocket07Channel.WebSocketFrameHeader ping = newHeader(channel);
        ping.handle(buffer(firstByte(true, 0, OPCODE_PING), secondByte(false, 0)));
        assertTrue(ping.isDone());

        WebSocket07Channel.WebSocketFrameHeader text = newHeader(channel);
        text.handle(buffer(firstByte(true, 0, OPCODE_TEXT), secondByte(false, 0)));
        assertTrue(text.isDone());
    }

