            throw new UnsupportedOperationException("the header decoder does not allocate buffers");
        }

        @Override
        public ByteBufferPool getArrayBackedPool() {
            return this;
        }

        @Override
        public void close() {
        }

        @Override
        public int getBufferSize() {
            return 1024;
        }

        @Override
        public boolean isDirect() {
            return false;
