/**
 * Unit tests for {@link UndertowResolver#resolve(String)}.
 *
 * <p>The resolver is exercised with a mocked {@link HttpServletRequest} and a mocked
 * {@link ServletRequestContext} backed by a real {@link HttpServerExchange}, so every
 * variable name / request accessor mapping can be asserted in isolation.</p>
 */
class UndertowResolverResolveTests {

    private static final String RFC1123_PATTERN = "EEE, dd MMM yyyy HH:mm:ss z";

    private static XnioWorker worker;

    private HttpServletRequest request;
    private ServletRequestContext servletRequestContext;
    private HttpServerExchange exchange;
    private UndertowResolver resolver;

    @BeforeAll
    static void createWorker() throws Exception {
        // A real I/O thread is required because DateUtils.getCurrentDateTime() schedules
        // an invalidation task on the exchange's I/O thread.
        worker = Xnio.getInstance().createWorker(OptionMap.create(Options.WORKER_IO_THREADS, 1));
    }

    @AfterAll
    static void destroyWorker() {
        if (worker != null) {
            worker.shutdownNow();
        }
    }

    @BeforeEach
    void setUp() {
        request = mock(HttpServletRequest.class);
        ServerConnection connection = mock(ServerConnection.class);
        when(connection.getIoThread()).thenReturn(worker.getIoThread());
        exchange = new HttpServerExchange(connection);
        exchange.setRelativePath("/relative/request/path");
        servletRequestContext = mock(ServletRequestContext.class);
        when(servletRequestContext.getExchange()).thenReturn(exchange);
        resolver = new UndertowResolver(servletRequestContext, request);
    }

    // ---------------------------------------------------------------- headers

    @Test
    void httpUserAgentReadsUserAgentHeader() {
        when(request.getHeader("user-agent")).thenReturn("Mozilla/5.0 (X11; Linux x86_64)");

        assertEquals("Mozilla/5.0 (X11; Linux x86_64)", resolver.resolve("HTTP_USER_AGENT"));
        verify(request).getHeader("user-agent");
    }

    @Test
    void httpUserAgentReturnsNullWhenHeaderAbsent() {
        assertNull(resolver.resolve("HTTP_USER_AGENT"));
    }

    @Test
    void httpRefererReadsRefererHeader() {
        when(request.getHeader("referer")).thenReturn("http://example.com/previous");

        assertEquals("http://example.com/previous", resolver.resolve("HTTP_REFERER"));
        verify(request).getHeader("referer");
    }

    @Test
    void httpCookieReadsCookieHeader() {
        when(request.getHeader("cookie")).thenReturn("JSESSIONID=abc123; theme=dark");

        assertEquals("JSESSIONID=abc123; theme=dark", resolver.resolve("HTTP_COOKIE"));
        verify(request).getHeader("cookie");
    }

    @Test
    void httpForwardedReadsForwardedHeader() {
        when(request.getHeader("forwarded")).thenReturn("for=192.0.2.60;proto=http;by=203.0.113.43");

        assertEquals("for=192.0.2.60;proto=http;by=203.0.113.43", resolver.resolve("HTTP_FORWARDED"));
        verify(request).getHeader("forwarded");
    }

    @Test
    void httpProxyConnectionReadsProxyConnectionHeader() {
        when(request.getHeader("proxy-connection")).thenReturn("Keep-Alive");

        assertEquals("Keep-Alive", resolver.resolve("HTTP_PROXY_CONNECTION"));
        verify(request).getHeader("proxy-connection");
    }

    @Test
    void httpAcceptReadsAcceptHeader() {
        when(request.getHeader("accept")).thenReturn("text/html,application/xhtml+xml");

        assertEquals("text/html,application/xhtml+xml", resolver.resolve("HTTP_ACCEPT"));
        verify(request).getHeader("accept");
    }

    // ------------------------------------------------------------- HTTP_HOST

    @Test
    void httpHostStripsPortFromHostHeader() {
        when(request.getHeader("host")).thenReturn("www.example.com:8080");

        assertEquals("www.example.com", resolver.resolve("HTTP_HOST"));
        verify(request).getHeader("host");
    }

    @Test
    void httpHostWithoutPortIsReturnedUnchanged() {
        when(request.getHeader("host")).thenReturn("www.example.com");

        assertEquals("www.example.com", resolver.resolve("HTTP_HOST"));
    }

    @Test
    void httpHostReturnsNullWhenHeaderMissing() {
        assertNull(resolver.resolve("HTTP_HOST"));
    }

    @Test
    void httpHostWithEmptyHostPartYieldsEmptyString() {
        when(request.getHeader("host")).thenReturn(":8080");

        assertEquals("", resolver.resolve("HTTP_HOST"));
    }

    // ------------------------------------------------------- remote variables

    @Test
    void remoteAddrReadsRemoteAddr() {
        when(request.getRemoteAddr()).thenReturn("203.0.113.7");

        assertEquals("203.0.113.7", resolver.resolve("REMOTE_ADDR"));
        verify(request).getRemoteAddr();
    }

    @Test
    void remoteHostReadsRemoteHost() {
        when(request.getRemoteHost()).thenReturn("client.example.com");

        assertEquals("client.example.com", resolver.resolve("REMOTE_HOST"));
        verify(request).getRemoteHost();
    }

    @Test
    void remotePortIsConvertedToString() {
        when(request.getRemotePort()).thenReturn(54321);

        assertEquals("54321", resolver.resolve("REMOTE_PORT"));
        verify(request).getRemotePort();
    }

    @Test
    void remotePortZeroIsConvertedToString() {
        when(request.getRemotePort()).thenReturn(0);

        assertEquals("0", resolver.resolve("REMOTE_PORT"));
    }

    @Test
    void remoteUserReadsRemoteUser() {
        when(request.getRemoteUser()).thenReturn("alice");

        assertEquals("alice", resolver.resolve("REMOTE_USER"));
        verify(request).getRemoteUser();
    }

    @Test
    void remoteUserReturnsNullForAnonymousRequest() {
        when(request.getRemoteUser()).thenReturn(null);

        assertNull(resolver.resolve("REMOTE_USER"));
    }

    @Test
    void remoteIdentUsesRemoteUserAsWell() {
        when(request.getRemoteUser()).thenReturn("bob");

        assertEquals("bob", resolver.resolve("REMOTE_IDENT"));
        assertEquals("bob", resolver.resolve("REMOTE_USER"));
        verify(request, times(2)).getRemoteUser();
    }

    // ----------------------------------------------------------- request data

    @Test
    void requestMethodReadsMethod() {
        when(request.getMethod()).thenReturn("POST");

        assertEquals("POST", resolver.resolve("REQUEST_METHOD"));
        verify(request).getMethod();
    }

    @Test
    void requestUriReadsRequestUri() {
