    private ManagedListener[] listenersOf(String fieldName) {
        try {
            Field field = ApplicationListeners.class.getDeclaredField(fieldName);
            field.setAccessible(true);
            return (ManagedListener[]) field.get(listeners);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError("could not read " + fieldName, e);
        }
    }

    @SuppressWarnings("unchecked")
    private List<ManagedListener> allListeners() {
        try {
            Field field = ApplicationListeners.class.getDeclaredField("allListeners");
            field.setAccessible(true);
            return (List<ManagedListener>) field.get(listeners);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError("could not read allListeners", e);
