        @Override
        public void contextInitialized(ServletContextEvent sce) {
            calls.add(name + ":contextInitialized");
        }

        @Override
        public void contextDestroyed(ServletContextEvent sce) {
            calls.add(name + ":contextDestroyed");
        }
    }

    private static final class ContextAndSessionListener implements ServletContextListener, HttpSessionListener {

        private final List<String> calls;

        ContextAndSessionListener(List<String> calls) {
            this.calls = calls;
