package io.undertow.servlet.handlers.security;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Arrays;
import java.util.HashSet;

import io.undertow.servlet.api.DeploymentInfo;
import io.undertow.servlet.api.SecurityConstraint;
import io.undertow.servlet.api.SecurityInfo.EmptyRoleSemantic;
import io.undertow.servlet.api.SingleConstraintMatch;
import io.undertow.servlet.api.TransportGuaranteeType;
import io.undertow.servlet.api.WebResourceCollection;
import io.undertow.util.Methods;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

/**
 * Unit tests for {@link SecurityPathMatches#getSecurityInfo(String, String)}.
 */
@Tag("io.undertow.testutils.category.UnitTest")
class SecurityPathMatchesGetSecurityInfoTests {

    // ------------------------------------------------------------------
    // helpers
    // ------------------------------------------------------------------

    private static SecurityConstraint constraintFor(final String urlPattern, final String... roles) {
        final SecurityConstraint constraint = new SecurityConstraint();
        constraint.addRolesAllowed(roles);
        constraint.addWebResourceCollection(new WebResourceCollection().addUrlPattern(urlPattern));
        return constraint;
    }

    private static SecurityConstraint defaultConstraint(final String... roles) {
        final SecurityConstraint constraint = new SecurityConstraint();
        constraint.addRolesAllowed(roles);
        // no url patterns -> applies to everything
        constraint.addWebResourceCollection(new WebResourceCollection());
        return constraint;
    }

    private static SecurityConstraint methodConstraint(final String urlPattern, final String httpMethod, final String... roles) {
        final SecurityConstraint constraint = new SecurityConstraint();
        constraint.addRolesAllowed(roles);
        constraint.addWebResourceCollection(new WebResourceCollection().addUrlPattern(urlPattern).addHttpMethod(httpMethod));
        return constraint;
    }

    private static SecurityConstraint omissionConstraint(final String urlPattern, final String omittedMethod, final String... roles) {
        final SecurityConstraint constraint = new SecurityConstraint();
        constraint.addRolesAllowed(roles);
        constraint.addWebResourceCollection(new WebResourceCollection().addUrlPattern(urlPattern).addHttpMethodOmission(omittedMethod));
        return constraint;
    }

    private static SecurityConstraint semanticConstraint(final String urlPattern, final EmptyRoleSemantic semantic) {
        final SecurityConstraint constraint = new SecurityConstraint();
        constraint.setEmptyRoleSemantic(semantic);
        constraint.addWebResourceCollection(new WebResourceCollection().addUrlPattern(urlPattern));
        return constraint;
    }

    private static SecurityPathMatches matches(final boolean denyUncoveredHttpMethods, final SecurityConstraint... constraints) {
        final DeploymentInfo deploymentInfo = new DeploymentInfo();
        deploymentInfo.setDenyUncoveredHttpMethods(denyUncoveredHttpMethods);
        return matches(deploymentInfo, constraints);
    }

    private static SecurityPathMatches matches(final DeploymentInfo deploymentInfo, final SecurityConstraint... constraints) {
        final SecurityPathMatches.Builder builder = SecurityPathMatches.builder(deploymentInfo);
        for (SecurityConstraint constraint : constraints) {
            builder.addSecurityConstraint(constraint);
        }
        return builder.build();
    }

    private static void assertPermit(final SecurityPathMatch match, final String... expectedRoles) {
        assertNotNull(match, "match");
        final SingleConstraintMatch merged = match.getMergedConstraint();
        assertNotNull(merged, "merged constraint");
        assertEquals(EmptyRoleSemantic.PERMIT, merged.getEmptyRoleSemantic(), "empty role semantic");
        assertEquals(new HashSet<>(Arrays.asList(expectedRoles)), new HashSet<>(merged.getRequiredRoles()), "required roles");
    }

    private static void assertConstraint(final SecurityPathMatch match, final EmptyRoleSemantic semantic, final String... expectedRoles) {
        assertNotNull(match, "match");
        final SingleConstraintMatch merged = match.getMergedConstraint();
        assertNotNull(merged, "merged constraint");
        assertEquals(semantic, merged.getEmptyRoleSemantic(), "empty role semantic");
        assertEquals(new HashSet<>(Arrays.asList(expectedRoles)), new HashSet<>(merged.getRequiredRoles()), "required roles");
    }

    private static void assertDenied(final SecurityPathMatch match) {
        assertConstraint(match, EmptyRoleSemantic.DENY);
        assertTrue(match.getMergedConstraint().getRequiredRoles().isEmpty(), "a denial must not carry roles");
    }

    // ------------------------------------------------------------------
    // no configuration
    // ------------------------------------------------------------------

    @Test
    @DisplayName("without any constraint every path is permitted without required roles")
    void noConstraintsPermitsEverything() {
        final SecurityPathMatches matches = matches(false);

        for (String path : new String[]{"/", "", "/foo", "/foo/bar", "/foo/bar.txt", "/foo?x=1", "/a/b.txt?version=1"}) {
            final SecurityPathMatch match = matches.getSecurityInfo(path, Methods.GET_STRING);
            assertPermit(match);
            assertEquals(TransportGuaranteeType.NONE, match.getTransportGuaranteeType(), "transport for " + path);
        }
    }

    // ------------------------------------------------------------------
    // exact path matches
    // ------------------------------------------------------------------

    @Test
    @DisplayName("an exact pattern match returns its roles and is not overridden by other patterns")
    void exactMatchReturnsRoles() {
        final SecurityPathMatches matches = matches(false,
                constraintFor("/admin", "admin"),
                constraintFor("/admin/*", "adminSub"),
                constraintFor("/", "root"));

        assertPermit(matches.getSecurityInfo("/admin", Methods.GET_STRING), "admin");
        assertPermit(matches.getSecurityInfo("/admin", Methods.POST_STRING), "admin");
        assertPermit(matches.getSecurityInfo("/admin/index.html", Methods.GET_STRING), "adminSub");
        assertPermit(matches.getSecurityInfo("/other", Methods.GET_STRING), "root");
    }

    @Test
    @DisplayName("an exact match requires an exactly equal path, a trailing slash does not match")
    void exactMatchRequiresExactPath() {
        final SecurityPathMatches matches = matches(false, constraintFor("/admin", "admin"));

        assertPermit(matches.getSecurityInfo("/admin", Methods.GET_STRING), "admin");
        assertPermit(matches.getSecurityInfo("/admin/", Methods.GET_STRING));
        assertPermit(matches.getSecurityInfo("/Admin", Methods.GET_STRING));
        assertPermit(matches.getSecurityInfo("/admin/sub", Methods.GET_STRING));
    }

    @Test
    @DisplayName("roles of several constraints on the same path are merged")
    void rolesOfSeveralConstraintsAreMerged() {
        final SecurityPathMatches matches = matches(false,
                constraintFor("/admin", "one"),
                constraintFor("/admin", "two", "three"));

        assertPermit(matches.getSecurityInfo("/admin", Methods.GET_STRING), "one", "two", "three");
    }

    // ------------------------------------------------------------------
    // prefix (path) matches
    // ------------------------------------------------------------------

    @Test
    @DisplayName("a prefix pattern matches its own path and all paths below it on segment boundaries")
    void prefixMatchAppliesToSubtree() {
        final SecurityPathMatches matches = matches(false, constraintFor("/admin/*", "admin"));

        assertPermit(matches.getSecurityInfo("/admin", Methods.GET_STRING), "admin");
        assertPermit(matches.getSecurityInfo("/admin/", Methods.GET_STRING), "admin");
        assertPermit(matches.getSecurityInfo("/admin/page.jsp", Methods.GET_STRING), "admin");
        assertPermit(matches.getSecurityInfo("/admin/a/b/c", Methods.PUT_STRING), "admin");
        // a query string is only retried against exact patterns, a prefix pattern on the bare
        // path without a trailing slash is therefore not resolved through the query string
        assertPermit(matches.getSecurityInfo("/admin?q=1", Methods.GET_STRING));
        assertPermit(matches.getSecurityInfo("/admin/page.jsp?q=1", Methods.GET_STRING), "admin");

        // segment boundary must be respected
        assertPermit(matches.getSecurityInfo("/administrator", Methods.GET_STRING));
        assertPermit(matches.getSecurityInfo("/adminx/page", Methods.GET_STRING));
    }

    @Test
    @DisplayName("a prefix pattern also matches when the request carries a query string")
    void prefixMatchWithQueryString() {
        final SecurityPathMatches matches = matches(false, constraintFor("/a/b/*", "ab"));

        assertPermit(matches.getSecurityInfo("/a/b/c?x=1", Methods.GET_STRING), "ab");
        assertPermit(matches.getSecurityInfo("/a/b/anything?x=1&y=2", Methods.GET_STRING), "ab");
        assertPermit(matches.getSecurityInfo("/a/b/c/d.jpg?size=2", Methods.GET_STRING), "ab");
    }

    @Test
    @DisplayName("the '/*' pattern matches every path, including the root")
    void rootPrefixPatternMatchesEverything() {
        final SecurityPathMatches matches = matches(false, constraintFor("/*", "any"));

        assertPermit(matches.getSecurityInfo("/", Methods.GET_STRING), "any");
        assertPermit(matches.getSecurityInfo("/foo", Methods.GET_STRING), "any");
        assertPermit(matches.getSecurityInfo("/foo/bar.txt", Methods.GET_STRING), "any");
        assertPermit(matches.getSecurityInfo("/foo/bar.txt?v=1", Methods.GET_STRING), "any");
    }

    // ------------------------------------------------------------------
    // extension matches
    // ------------------------------------------------------------------

    @Test
    @DisplayName("an extension pattern matches the last extension of the path")
    void extensionMatchUsesLastExtension() {
        final SecurityPathMatches matches = matches(false, constraintFor("*.txt", "reader"));

        assertPermit(matches.getSecurityInfo("/docs/file.txt", Methods.GET_STRING), "reader");
        assertPermit(matches.getSecurityInfo("/file.txt", Methods.GET_STRING), "reader");
        assertPermit(matches.getSecurityInfo("/docs/a.b.txt", Methods.GET_STRING), "reader");
        assertPermit(matches.getSecurityInfo("/docs/file.txt?version=2", Methods.GET_STRING), "reader");

        assertPermit(matches.getSecurityInfo("/docs/file.pdf", Methods.GET_STRING));
        assertPermit(matches.getSecurityInfo("/docs/file.TXT", Methods.GET_STRING));
        assertPermit(matches.getSecurityInfo("/docs", Methods.GET_STRING));
    }

    @Test
    @DisplayName("a path prefix match wins over an extension match")
    void prefixMatchWinsOverExtensionMatch() {
        final SecurityPathMatches matches = matches(false,
                constraintFor("*.txt", "reader"),
                constraintFor("/docs/*", "docsUser"));

        assertPermit(matches.getSecurityInfo("/docs/file.txt", Methods.GET_STRING), "docsUser");
        assertPermit(matches.getSecurityInfo("/other/file.txt", Methods.GET_STRING), "reader");
    }

    @Test
    @DisplayName("an exact match with a query string is resolved against the path without the query string")
    void exactMatchWithQueryString() {
        final SecurityPathMatches matches = matches(false,
                constraintFor("/app/page", "pageUser"),
                constraintFor("/app/page.html", "htmlUser"));

        assertPermit(matches.getSecurityInfo("/app/page", Methods.GET_STRING), "pageUser");
        assertPermit(matches.getSecurityInfo("/app/page?x=1", Methods.GET_STRING), "pageUser");
        assertPermit(matches.getSecurityInfo("/app/page?x=1&y=2", Methods.GET_STRING), "pageUser");
        assertPermit(matches.getSecurityInfo("/app/page.html?v=1", Methods.GET_STRING), "htmlUser");
    }

    // ------------------------------------------------------------------
    // '/' fallback
    // ------------------------------------------------------------------

    @Test
    @DisplayName("the '/' pattern is used as fallback when nothing else matches")
    void rootPatternIsFallback() {
        final SecurityPathMatches matches = matches(false, constraintFor("/", "root"));

        assertPermit(matches.getSecurityInfo("/", Methods.GET_STRING), "root");
        assertPermit(matches.getSecurityInfo("", Methods.GET_STRING), "root");
        assertPermit(matches.getSecurityInfo("/unknown/path", Methods.GET_STRING), "root");
        assertPermit(matches.getSecurityInfo("/unknown/file.png", Methods.GET_STRING), "root");
        assertPermit(matches.getSecurityInfo("/unknown/path?x=1", Methods.GET_STRING), "root");
    }

    // ------------------------------------------------------------------
    // default security information
    // ------------------------------------------------------------------

    @Test
    @DisplayName("security constraints without url patterns apply to every path and method")
    void defaultSecurityAppliesToEverything() {
        final SecurityPathMatches matches = matches(false, defaultConstraint("user"));

        assertPermit(matches.getSecurityInfo("/", Methods.GET_STRING), "user");
        assertPermit(matches.getSecurityInfo("/any/path", Methods.GET_STRING), "user");
        assertPermit(matches.getSecurityInfo("/any/path.txt", Methods.POST_STRING), "user");
        assertPermit(matches.getSecurityInfo("/any/path?x=1", Methods.DELETE_STRING), "user");
    }

    @Test
    @DisplayName("default security roles are merged with the roles of the matched path")
    void defaultSecurityRolesAreMerged() {
        final SecurityPathMatches matches = matches(false,
                defaultConstraint("user"),
                constraintFor("/admin", "admin"));

        assertPermit(matches.getSecurityInfo("/admin", Methods.GET_STRING), "user", "admin");
        assertPermit(matches.getSecurityInfo("/other", Methods.GET_STRING), "user");
    }

    // ------------------------------------------------------------------
    // empty role semantics
    // ------------------------------------------------------------------

    @Test
    @DisplayName("a constraint without roles but with AUTHENTICATE semantic is propagated")
    void authenticateSemanticIsPropagated() {
        final SecurityPathMatches matches = matches(false, semanticConstraint("/secure", EmptyRoleSemantic.AUTHENTICATE));

        assertConstraint(matches.getSecurityInfo("/secure", Methods.GET_STRING), EmptyRoleSemantic.AUTHENTICATE);
        assertPermit(matches.getSecurityInfo("/other", Methods.GET_STRING));
    }

    @Test
    @DisplayName("a constraint with DENY semantic and no roles denies access")
    void denySemanticIsPropagated() {
        final SecurityPathMatches matches = matches(false, semanticConstraint("/blocked", EmptyRoleSemantic.DENY));

        assertDenied(matches.getSecurityInfo("/blocked", Methods.GET_STRING));
        assertPermit(matches.getSecurityInfo("/other", Methods.GET_STRING));
    }

    @Test
    @DisplayName("an empty role constraint wins over role constraints from the default security")
    void emptyRoleConstraintWinsOverRoles() {
        final SecurityPathMatches matches = matches(false,
                defaultConstraint("user"),
                semanticConstraint("/secure", EmptyRoleSemantic.AUTHENTICATE));

        assertConstraint(matches.getSecurityInfo("/secure", Methods.GET_STRING), EmptyRoleSemantic.AUTHENTICATE);
        assertPermit(matches.getSecurityInfo("/other", Methods.GET_STRING), "user");
    }

    // ------------------------------------------------------------------
    // transport guarantee
    // ------------------------------------------------------------------

    @Test
    @DisplayName("the strongest transport guarantee wins")
    void strongestTransportGuaranteeWins() {
        final SecurityConstraint confidentialDefault = defaultConstraint("user");
        confidentialDefault.setTransportGuaranteeType(TransportGuaranteeType.CONFIDENTIAL);
        final SecurityConstraint integralPath = constraintFor("/admin", "admin");
        integralPath.setTransportGuaranteeType(TransportGuaranteeType.INTEGRAL);
        final SecurityConstraint rejectedPath = constraintFor("/locked", "nobody");
        rejectedPath.setTransportGuaranteeType(TransportGuaranteeType.REJECTED);

        final SecurityPathMatches matches = matches(false, confidentialDefault, integralPath, rejectedPath);

        final SecurityPathMatch adminMatch = matches.getSecurityInfo("/admin", Methods.GET_STRING);
        assertEquals(TransportGuaranteeType.CONFIDENTIAL, adminMatch.getTransportGuaranteeType());
        assertPermit(adminMatch, "user", "admin");

        final SecurityPathMatch lockedMatch = matches.getSecurityInfo("/locked", Methods.GET_STRING);
        assertEquals(TransportGuaranteeType.REJECTED, lockedMatch.getTransportGuaranteeType());
        assertPermit(lockedMatch, "user", "nobody");

        final SecurityPathMatch otherMatch = matches.getSecurityInfo("/other", Methods.GET_STRING);
        assertEquals(TransportGuaranteeType.CONFIDENTIAL, otherMatch.getTransportGuaranteeType());
        assertPermit(otherMatch, "user");
    }

    @Test
    @DisplayName("a transport guarantee on its own is reported without any role")
    void transportGuaranteeWithoutRoles() {
        final SecurityConstraint constraint = semanticConstraint("/secure", EmptyRoleSemantic.PERMIT);
        constraint.setTransportGuaranteeType(TransportGuaranteeType.INTEGRAL);
        final SecurityPathMatches matches = matches(false, constraint);

        final SecurityPathMatch match = matches.getSecurityInfo("/secure", Methods.GET_STRING);
        assertEquals(TransportGuaranteeType.INTEGRAL, match.getTransportGuaranteeType());
        assertPermit(match);

        assertEquals(TransportGuaranteeType.NONE, matches.getSecurityInfo("/other", Methods.GET_STRING).getTransportGuaranteeType());
    }

    // ------------------------------------------------------------------
    // role expansion
    // ------------------------------------------------------------------

    @Test
    @DisplayName("the '*' role is expanded to all declared deployment roles")
    void starRoleIsExpanded() {
        final DeploymentInfo deploymentInfo = new DeploymentInfo();
        deploymentInfo.setDenyUncoveredHttpMethods(false);
        deploymentInfo.addSecurityRoles("role1", "role2");

        final SecurityPathMatches matches = matches(deploymentInfo,
                constraintFor("/star", "*"),
                constraintFor("/starAndMore", "*", "explicit"));

        assertPermit(matches.getSecurityInfo("/star", Methods.GET_STRING), "role1", "role2");
        assertPermit(matches.getSecurityInfo("/starAndMore", Methods.GET_STRING), "role1", "role2", "explicit");
    }

    @Test
    @DisplayName("the '*' role expands to nothing when no deployment roles are declared")
    void starRoleWithoutDeclaredRoles() {
        final SecurityConstraint constraint = constraintFor("/star", "*");
        constraint.setEmptyRoleSemantic(EmptyRoleSemantic.PERMIT);
        final SecurityPathMatches matches = matches(false, constraint);

        assertPermit(matches.getSecurityInfo("/star", Methods.GET_STRING));
    }

    // ------------------------------------------------------------------
    // deny uncovered http methods
    // ------------------------------------------------------------------

    @Test
    @DisplayName("uncovered methods are denied when denyUncoveredHttpMethods is enabled")
    void uncoveredMethodsAreDenied() {
        final SecurityPathMatches matches = matches(true, methodConstraint("/foo", Methods.GET_STRING, "user"));

        assertPermit(matches.getSecurityInfo("/foo", Methods.GET_STRING), "user");
        assertDenied(matches.getSecurityInfo("/foo", Methods.POST_STRING));
        assertDenied(matches.getSecurityInfo("/foo", Methods.HEAD_STRING));
        assertDenied(matches.getSecurityInfo("/bar", Methods.GET_STRING));
    }

    @Test
    @DisplayName("uncovered methods are permitted when denyUncoveredHttpMethods is disabled")
    void uncoveredMethodsAreNotDeniedWhenDisabled() {
        final SecurityPathMatches matches = matches(false, methodConstraint("/foo", Methods.GET_STRING, "user"));

        assertPermit(matches.getSecurityInfo("/foo", Methods.GET_STRING), "user");
        assertPermit(matches.getSecurityInfo("/foo", Methods.POST_STRING));
        assertPermit(matches.getSecurityInfo("/bar", Methods.GET_STRING));
    }

    @Test
    @DisplayName("a constraint without method restrictions covers all methods")
    void methodAgnosticConstraintCoversAllMethods() {
        final SecurityPathMatches matches = matches(true, constraintFor("/foo", "user"));

        assertPermit(matches.getSecurityInfo("/foo", Methods.GET_STRING), "user");
        assertPermit(matches.getSecurityInfo("/foo", Methods.POST_STRING), "user");
        assertPermit(matches.getSecurityInfo("/foo", Methods.TRACE_STRING), "user");
        // but nothing else is covered
        assertDenied(matches.getSecurityInfo("/bar", Methods.GET_STRING));
    }

    @Test
    @DisplayName("method omissions cover all methods except the omitted one")
    void methodOmissionsCoverOtherMethods() {
        final SecurityPathMatches matches = matches(true, omissionConstraint("/foo", Methods.GET_STRING, "admin"));

        assertPermit(matches.getSecurityInfo("/foo", Methods.POST_STRING), "admin");
        assertPermit(matches.getSecurityInfo("/foo", Methods.PUT_STRING), "admin");
        assertDenied(matches.getSecurityInfo("/foo", Methods.GET_STRING));
        // other paths remain uncovered
        assertDenied(matches.getSecurityInfo("/bar", Methods.POST_STRING));
    }

    @Test
    @DisplayName("method omission constraints do not deny when denyUncoveredHttpMethods is disabled")
    void methodOmissionsWithoutDenyUncovered() {
        final SecurityPathMatches matches = matches(false, omissionConstraint("/foo", Methods.GET_STRING, "admin"));

        assertPermit(matches.getSecurityInfo("/foo", Methods.POST_STRING), "admin");
        assertPermit(matches.getSecurityInfo("/foo", Methods.GET_STRING));
    }

    @Test
    @DisplayName("method restrictions of the default security information are honoured")
    void defaultSecurityMethodRestrictions() {
        final SecurityConstraint constraint = new SecurityConstraint();
        constraint.addRoleAllowed("user");
        constraint.addWebResourceCollection(new WebResourceCollection().addHttpMethod(Methods.GET_STRING));
        final SecurityPathMatches matches = matches(true, constraint);

        assertPermit(matches.getSecurityInfo("/anything", Methods.GET_STRING), "user");
        assertDenied(matches.getSecurityInfo("/anything", Methods.POST_STRING));

        final SecurityPathMatches permissive = matches(false, constraint);
        assertPermit(permissive.getSecurityInfo("/anything", Methods.GET_STRING), "user");
        assertPermit(permissive.getSecurityInfo("/anything", Methods.POST_STRING));
    }

    @Test
    @DisplayName("an empty default security is never treated as a deny all")
    void emptyDefaultSecurityIsNotDenyAll() {
        // only an exact constraint is configured, the default security information is empty
        final SecurityPathMatches matches = matches(true, constraintFor("/foo", "user"));

        assertPermit(matches.getSecurityInfo("/foo", Methods.GET_STRING), "user");
        // no match at all -> uncovered -> denied because denyUncoveredHttpMethods is enabled
        assertDenied(matches.getSecurityInfo("/unknown", Methods.GET_STRING));
    }

    @Test
    @DisplayName("the '/' fallback also takes part in uncovered method handling")
    void rootFallbackWithUncoveredMethods() {
        final SecurityPathMatches matches = matches(true,
                methodConstraint("/", Methods.GET_STRING, "root"));

        assertPermit(matches.getSecurityInfo("/", Methods.GET_STRING), "root");
        assertPermit(matches.getSecurityInfo("/some/path", Methods.GET_STRING), "root");
        assertDenied(matches.getSecurityInfo("/some/path", Methods.POST_STRING));
    }

    // ------------------------------------------------------------------
    // combination of matches
    // ------------------------------------------------------------------

    @Test
