    private static final class TestOutputStream extends ServletOutputStreamImpl {

        private ByteBuffer buffer;
        private boolean closed;
        private long remainingContentLength = Long.MAX_VALUE;
        private long written;
        private int updateCalls;
        private int flushInternalCalls;
        private boolean flushWithoutChangingBuffer;
        private IOException flushException;
        private IOException contentLengthException;
        private IOException updateWrittenException;
        private final ByteArrayOutputStream flushed = new ByteArrayOutputStream();

        private TestOutputStream(final int capacity) {
            this(ByteBuffer.allocate(capacity));
        }

        private TestOutputStream(final ByteBuffer buffer) {
            super(null);
            this.buffer = buffer;
        }

        @Override
        ByteBuffer underlyingBuffer() {
            return closed ? null : buffer;
        }

        @Override
        long remainingContentLength() throws IOException {
            if (contentLengthException != null) {
                throw contentLengthException;
            }
            return remainingContentLength;
        }

        @Override
        void updateWritten(final long len) throws IOException {
            if (updateWrittenException != null) {
                throw updateWrittenException;
            }
            written += len;
            updateCalls++;
        }

        @Override
        public void flushInternal() throws IOException {
            flushInternalCalls++;
            if (flushException != null) {
                throw flushException;
            }
            if (flushWithoutChangingBuffer) {
                return;
            }
            buffer.flip();
            final byte[] bytes = new byte[buffer.remaining()];
            buffer.get(bytes);
            flushed.write(bytes, 0, bytes.length);
            buffer.clear();
        }

        @Override
        public void flush() {
            // The tests inspect success via checkError(); a no-op flush keeps
            // the state deterministic and does not disturb the fake buffer.
        }

        private byte[] allBytes() {
            final ByteBuffer copy = buffer.duplicate();
            copy.flip();
            final byte[] buffered = new byte[copy.remaining()];
            copy.get(buffered);
            final byte[] done = flushed.toByteArray();
            final byte[] result = new byte[done.length + buffered.length];
            System.arraycopy(done, 0, result, 0, done.length);
            System.arraycopy(buffered, 0, result, done.length, buffered.length);
            return result;
        }
    }
}

