    private static String decodeUtf8(ByteBuffer buffer) {
        return StandardCharsets.UTF_8.decode(buffer.duplicate()).toString();
    }

    private static String readFully(Reader reader) throws IOException {
        StringBuilder result = new StringBuilder();
        char[] buffer = new char[128];
        int read;
        while ((read = reader.read(buffer)) != -1) {
            result.append(buffer, 0, read);
        }
        return result.toString();
    }

    private static final class RecordingClassIntrospecter implements ClassIntrospecter {
        private final List<Class<?>> requested = new ArrayList<>();
        private final Set<Class<?>> failing = new HashSet<>();

        RecordingClassIntrospecter failFor(Class<?>... classes) {
            failing.addAll(Arrays.asList(classes));
            return this;
        }

        @Override
        public <T> InstanceFactory<T> createInstanceFactory(final Class<T> clazz)
                throws NoSuchMethodException {
            requested.add(clazz);
            if (failing.contains(clazz)) {
                throw new NoSuchMethodException("No default constructor for " + clazz.getName());
            }
            return () -> {
                try {
                    return new SimpleInstanceHandle<>(clazz.getDeclaredConstructor().newInstance());
                } catch (ReflectiveOperationException e) {
                    throw new InstantiationException(e.toString());
                }
            };
        }
    }

    private static final class SimpleInstanceHandle<T> implements InstanceHandle<T> {
        private final T instance;

        private SimpleInstanceHandle(T instance) {
            this.instance = instance;
        }

        @Override
        public T getInstance() {
            return instance;
        }

        @Override
        public void release() {
        }
    }

